insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(1, 1, 'الإشعاع الكهرومغناطيسي شكل من أشكال الطاقة ينتقل في الفضاء على هيئة موجات، ومن أمثلته الضوء المرئي والميكروويف وموجات الراديو والأشعة السينية.', '["الجسيمات المشحونة المنطلقة من النواة وصف لبعض الإشعاعات النووية لا للإشعاع الكهرومغناطيسي.","","الموجات التي تحتاج إلى وسط مادي موجات ميكانيكية كالصوت، أما الإشعاع الكهرومغناطيسي فينتقل في الفراغ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.024Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2, 2, 'الموجات الصوتية موجات ميكانيكية تحتاج إلى وسط مادي لتنتقل، ولا تنتقل في الفراغ، فليست إشعاعًا كهرومغناطيسيًا. أما الأشعة السينية وموجات الراديو فمن أنواع الإشعاع الكهرومغناطيسي.', '["الأشعة السينية نوع من الإشعاع الكهرومغناطيسي ذو طول موجي قصير جدًا.","موجات الراديو نوع من الإشعاع الكهرومغناطيسي ذو طول موجي كبير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.029Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(3, 0, 'جميع الموجات الكهرومغناطيسية تسير في الفراغ بالسرعة نفسها، وهي سرعة الضوء c = 3.00×10⁸ m/s.', '["","الوحدة خاطئة؛ سرعة الضوء 3.00×10⁸ m/s أي 3.00×10⁵ km/s.","هذه القيمة تساوي سرعة الضوء مقدرةً بـ km/s لا بـ m/s، فالأس غير صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.030Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(4, 1, 'الظاهرة س تنتقل في الفراغ بسرعة 3.00×10⁸ m/s وهي صفة الإشعاع الكهرومغناطيسي. أما ص فتحتاج إلى وسط مادي (موجة ميكانيكية كالصوت)، وع جسيمات مشحونة لا موجات كهرومغناطيسية.', '["ع سيل من جسيمات مشحونة لها كتلة، وليست موجة كهرومغناطيسية.","","ص لا تنتقل في الفراغ وسرعتها صغيرة، فهي موجة ميكانيكية تحتاج إلى وسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.031Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(5, 0, 'الإشعاع الكهرومغناطيسي ومنه الضوء ينتقل على هيئة موجات في الفراغ دون حاجة إلى وسط مادي، فيعبر الفضاء ويصل إلى الأرض.', '["","الفضاء شبه خالٍ من الهواء، والضوء لا يعتمد على جزيئات وسط لينتقل.","الضوء ينتقل في الفراغ وفي بعض المواد أيضًا كالهواء والزجاج والماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.031Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(6, 2, 'جميع أنواع الإشعاع الكهرومغناطيسي أشكال من الطاقة تسير بالسرعة نفسها في الفراغ، وتختلف فقط في الطول الموجي والتردد.', '["جميعها تسير في الفراغ بالسرعة نفسها c ولها الطبيعة الموجية نفسها.","كونها شكلًا من أشكال الطاقة صفة مشتركة بينها لا فرق.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.031Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(7, 1, 'رؤية الإشعاع ليست شرطًا لكونه كهرومغناطيسيًا؛ فالضوء المرئي جزء صغير من الإشعاع الكهرومغناطيسي، والأشعة السينية إشعاع كهرومغناطيسي ذو طول موجي قصير جدًا لا تحسه العين.', '["الضوء المرئي جزء فقط من الإشعاع الكهرومغناطيسي، ويشمل أيضًا موجات الراديو والميكروويف والأشعة السينية وغيرها.","","الأشعة السينية ليست موجات ميكانيكية ولا تُسمع، بل تنتقل في الفراغ بسرعة الضوء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.032Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(8, null, null, null, 'الإشعاع الكهرومغناطيسي: شكل من أشكال الطاقة يسلك سلوك الموجات في أثناء انتقاله في الفضاء. أمثلته: الضوء المرئي، والميكروويف، وموجات الراديو (ويقبل: الأشعة السينية، أشعة جاما، الأشعة فوق البنفسجية، الأشعة تحت الحمراء). الصفة المشتركة: جميعها تسير في الفراغ بالسرعة نفسها، سرعة الضوء c = 3.00×10⁸ m/s.', '["التعريف: شكل من أشكال الطاقة","يسلك سلوك الموجات في أثناء انتقاله في الفضاء","ثلاثة أمثلة صحيحة","السرعة نفسها في الفراغ 3.00×10⁸ m/s"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف الصحيح كاملًا","marks":2},{"element":"ثلاثة أمثلة صحيحة","marks":1},{"element":"الصفة المشتركة: السرعة c في الفراغ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل وثلاثة أمثلة صحيحة وذكر السرعة المشتركة"},{"level":"3 درجات","description":"تعريف كامل مع نقص في الأمثلة أو عدم ذكر قيمة السرعة"},{"level":"2 درجتان","description":"تعريف ناقص (دون ذكر الطبيعة الموجية) مع أمثلة صحيحة"},{"level":"1 درجة","description":"أمثلة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الصوت مثالًا على الإشعاع الكهرومغناطيسي","تعريف الإشعاع بأنه جسيمات مشحونة","الاعتقاد بأن الأنواع المختلفة تسير بسرعات مختلفة في الفراغ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.033Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(9, null, null, null, 'إشعاع كهرومغناطيسي: ضوء المصباح، وموجات الميكروويف، وأشعة جاما؛ لأنها أشكال من الطاقة تنتقل على هيئة موجات في الفراغ بسرعة الضوء. غير كهرومغناطيسي: صوت الجرس وأمواج البحر؛ لأنها موجات ميكانيكية تحتاج إلى وسط مادي (الهواء أو الماء) لتنتقل ولا تنتقل في الفراغ.', '["ضوء المصباح والميكروويف وأشعة جاما: كهرومغناطيسية","الصوت وأمواج البحر: غير كهرومغناطيسية","التعليل: الكهرومغناطيسي ينتقل في الفراغ بسرعة الضوء","التعليل: غير الكهرومغناطيسي يحتاج وسطًا ماديًا"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الأمثلة الخمسة صحيحًا","marks":3},{"element":"التعليل لكل فئة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للخمسة مع تعليل الفئتين"},{"level":"3–4 درجات","description":"تصنيف صحيح مع تعليل لفئة واحدة، أو خطأ في مثال واحد مع تعليل كامل"},{"level":"1–2 درجة","description":"تصنيف صحيح لبعض الأمثلة دون تعليل"},{"level":"صفر","description":"تصنيف خاطئ أو لا إجابة"}]'::jsonb, '["عد صوت الجرس إشعاعًا كهرومغناطيسيًا لأنه ينتشر في الهواء","عد أشعة جاما غير كهرومغناطيسية لأنها غير مرئية","التعليل بالرؤية أو السمع بدل الحاجة إلى وسط مادي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.033Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(10, null, null, null, 'الضوء الصادر عن الانفجار إشعاع كهرومغناطيسي، أي شكل من أشكال الطاقة ينتقل على هيئة موجات ولا يحتاج إلى وسط مادي، فيعبر الفراغ بسرعة 3.00×10⁸ m/s ويصل إلى أعين الرواد. أما الصوت فموجة ميكانيكية تحتاج إلى وسط مادي (كالهواء) لتنتقل، والفضاء شبه خالٍ من المادة، فلا ينتقل الصوت ولا يُسمع.', '["الضوء إشعاع كهرومغناطيسي","الإشعاع الكهرومغناطيسي ينتقل في الفراغ دون وسط","الصوت يحتاج إلى وسط مادي","الفضاء شبه خالٍ من المادة فلا ينتقل الصوت"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير رؤية الضوء بأنه إشعاع كهرومغناطيسي ينتقل في الفراغ","marks":2},{"element":"تفسير عدم سماع الصوت لحاجته إلى وسط","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للظاهرتين"},{"level":"2–3 درجات","description":"تفسير إحدى الظاهرتين كاملًا والأخرى ناقصًا"},{"level":"1 درجة","description":"إشارة عامة دون ربط بالوسط المادي"},{"level":"صفر","description":"تفسير خاطئ أو لا إجابة"}]'::jsonb, '["القول إن الصوت أبطأ فقط ولذلك يتأخر وصوله","الاعتقاد بأن الضوء يحتاج إلى الهواء لينتقل","الخلط بين الموجات الميكانيكية والكهرومغناطيسية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.034Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(11, 2, 'خصائص الموجات: الطول الموجي، والتردد، والسعة (وتسير الموجات الكهرومغناطيسية جميعها بالسرعة c في الفراغ).', '["الكتلة من خصائص المادة لا الموجات.","الكثافة من خصائص المادة لا الموجات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.038Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(12, 1, 'يرمز للتردد بالحرف الإغريقي ν (نيو)، ويرمز للطول الموجي بالرمز λ (لامدا).', '["الطول الموجي رمزه λ.","","السعة لا يرمز لها بـ ν."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.038Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(13, 0, 'الطول الموجي مسافة فيقاس بوحدات الطول (m أو cm أو nm)، والتردد يقاس بـ Hz أو s⁻¹، والسعة ارتفاع فتقاس بوحدة طول.', '["","التردد يقاس بالهيرتز Hz (s⁻¹) لا بوحدة طول.","السعة ارتفاع يقاس بوحدة طول، والهيرتز وحدة التردد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.039Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(14, 2, 'من الجدول السعة متساوية (3 وحدات) في الموجتين، بينما يختلف الطول الموجي والتردد.', '["تردد (أ) 5.0×10¹⁴ Hz وتردد (ب) 1.0×10¹⁵ Hz، فهما مختلفان.","الطول الموجي لـ(أ) ضعف الطول الموجي لـ(ب).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.039Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(15, 0, 'الطول الموجي مسافة أفقية بين قمتين متتاليتين، والسعة ارتفاع القمة عن خط الأصل، وكلاهما يقاس بوحدات الطول، أما التردد فيقاس بـ Hz.', '["","التردد يقاس بـ Hz (s⁻¹) وليس بوحدة طول.","التردد ليس مسافة، بل عدد موجات في الثانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.040Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(16, 1, 'ارتفاع القمة عن خط الأصل هو السعة، فسعة الأولى ضعف الثانية. والطول الموجي والتردد لا يتأثران بالسعة، فبما أن الطول الموجي متساوٍ يكون التردد متساويًا أيضًا.', '["السعة لا تؤثر في التردد؛ وتساوي الطول الموجي يعني تساوي التردد.","","المعطى أن الطول الموجي متساوٍ، والسعة لا تغيّره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.040Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(17, 2, 'كل الموجات الكهرومغناطيسية تسير في الفراغ بسرعة الضوء نفسها c = 3.00×10⁸ m/s، وتختلف في التردد والطول الموجي.', '["الترددات تختلف من نوع لآخر (من نحو 10⁴ إلى 10²⁰ Hz).","الأطوال الموجية تختلف من نوع لآخر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.040Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(18, null, null, null, '1) الطول الموجي (λ): أقصر مسافة بين قمتين متتاليتين أو قاعين متتاليين، ويقاس بـ m أو cm أو nm. 2) التردد (ν): عدد الموجات التي تعبر نقطة محددة خلال ثانية، ويقاس بـ Hz أو s⁻¹. 3) سعة الموجة: ارتفاع القمة أو انخفاض القاع عن خط الأصل، وتقاس بوحدة طول.', '["الطول الموجي وتعريفه","رمز λ أو وحدته","التردد وتعريفه","رمز ν أو وحدته Hz","السعة وتعريفها"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية الخصائص الثلاث","marks":1},{"element":"تعريف كل خاصية (لكل تعريف درجة)","marks":3},{"element":"الرموز أو الوحدات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ثلاث خصائص بتعريفات ورموز/وحدات صحيحة"},{"level":"3–4 درجات","description":"ثلاث خصائص مع خطأ في تعريف أو وحدة"},{"level":"1–2 درجة","description":"تسمية الخصائص دون تعريفات صحيحة"},{"level":"صفر","description":"لا إجابة أو خصائص خاطئة"}]'::jsonb, '["تعريف الطول الموجي بأنه المسافة بين قمة وقاع","الخلط بين رمزي λ وν","ذكر الكتلة أو الكثافة من خصائص الموجات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.041Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(19, null, null, null, 'الطول الموجي: (س) أكبر لأن قممها متباعدة، و(ص) أصغر. التردد: (ص) أكبر لأن طولها الموجي أقصر (والعلاقة بين التردد والطول الموجي عكسية لأن السرعة ثابتة c)، و(س) أقل. السعة: (س) أكبر لأن قممها أعلى، و(ص) أصغر. والسعة مستقلة عن الطول الموجي والتردد.', '["الطول الموجي: س > ص","التردد: ص > س مع التعليل بالعلاقة العكسية","السعة: س > ص","الإشارة إلى أن السعة لا تتأثر بالطول الموجي والتردد"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة الطول الموجي","marks":1},{"element":"مقارنة التردد مع التعليل","marks":2},{"element":"مقارنة السعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المقارنات الثلاث صحيحة مع تعليل التردد"},{"level":"3 درجات","description":"المقارنات صحيحة دون تعليل التردد"},{"level":"1–2 درجة","description":"مقارنة أو اثنتان صحيحتان"},{"level":"صفر","description":"مقارنات خاطئة"}]'::jsonb, '["الاعتقاد بأن الموجة الأعلى سعة لها تردد أكبر","عكس العلاقة بين الطول الموجي والتردد","الخلط بين السعة والطول الموجي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.042Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(20, null, null, null, 'المعنى: يمكن أن تتغير سعة الموجة (ارتفاع القمة عن خط الأصل) دون أن يتغير طولها الموجي أو ترددها، والعكس، فالسعة خاصية مستقلة. مثال: موجتان طول كل منهما الموجي 500 nm (ولهما التردد نفسه) لكن سعة الأولى 2 وحدة وسعة الثانية 4 وحدات؛ اختلفت السعة مع ثبات الطول الموجي والتردد. (أو موجتان لهما السعة نفسها وطولان موجيان مختلفان).', '["السعة خاصية مستقلة عن الطول الموجي والتردد","تغير السعة لا يغير الطول الموجي أو التردد","مثال صحيح بموجتين تتساويان في λ وν وتختلفان في السعة أو العكس"]'::jsonb, '[]'::jsonb, '[{"element":"توضيح معنى العبارة","marks":2},{"element":"مثال صحيح بموجتين","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"توضيح دقيق ومثال صحيح"},{"level":"2–3 درجات","description":"توضيح صحيح مع مثال ناقص، أو مثال صحيح مع توضيح عام"},{"level":"1 درجة","description":"إعادة صياغة العبارة فقط"},{"level":"صفر","description":"لا إجابة أو فهم خاطئ"}]'::jsonb, '["القول إن زيادة السعة تزيد التردد","اختيار موجتين تختلفان في λ والسعة معًا فلا يثبت شيئًا","الخلط بين السعة والطول الموجي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.042Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(21, 0, 'الطول الموجي (λ) أقصر مسافة بين قمتين متتاليتين أو قاعين متتاليين.', '["","هذا تعريف التردد.","هذا تعريف سعة الموجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.046Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(22, 1, 'الطول الموجي هو المسافة بين نقطتين متماثلتين متتاليتين، كقاعين متتاليين أو قمتين متتاليتين.', '["المسافة الأفقية بين قمة والقاع الذي يليها تساوي نصف طول موجي فقط.","","ارتفاع القمة عن خط الأصل هو السعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.047Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(23, 2, '1 nm = 1×10⁻⁹ m، إذن 656 nm = 656×10⁻⁹ m = 6.56×10⁻⁷ m.', '["ناتج القسمة على 10⁻⁹ بدل الضرب فيه.","خطأ في تعديل الأس: 656×10⁻⁹ تساوي 6.56×10⁻⁷ لا 6.56×10⁻¹¹.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.048Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(24, 1, 'المسافة الأفقية بين قمة والقاع التالي تساوي نصف طول موجي، إذن λ = 2 × 2.0 = 4.0 cm.', '["ناتج قسمة المسافة على 2 بدل ضربها.","","عُدّت المسافة بين القمة والقاع طولًا موجيًا كاملًا، وهي نصفه فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-11T11:15:01.049Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(25, 0, 'λ = الطول الكلي ÷ عدد الموجات الكاملة = 12 ÷ 3 = 4.0 m.', '["","ناتج ضرب الطول في عدد الموجات بدل القسمة.","ناتج قسمة عدد الموجات على الطول (عكس النسبة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.049Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(26, 2, 'أصغر قيمة في الجدول 3×10⁻¹² m وهي لأشعة جاما، فطولها الموجي هو الأقصر.', '["طوله الموجي 3×10⁻² m وهو الأطول بين الثلاثة.","طوله الموجي 5×10⁻⁷ m وهو أكبر من طول أشعة جاما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.049Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(27, 0, 'يرمز للطول الموجي بالحرف λ (لامدا)، ولأنه مسافة فوحدته الأساسية المتر m (ويقاس أيضًا بـ cm وnm).', '["","ν رمز التردد لا الطول الموجي.","الهيرتز وحدة التردد، أما الطول الموجي فمسافة تقاس بالمتر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.050Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(28, null, null, null, 'الطول الموجي: أقصر مسافة بين قمتين متتاليتين أو قاعين متتاليين، ورمزه λ. التحويل: 1 nm = 1×10⁻⁹ m، إذن 4.50×10² nm × (1×10⁻⁹ m/nm) = 4.50×10⁻⁷ m.', '["التعريف الصحيح","الرمز λ","استخدام 1 nm = 1×10⁻⁹ m","الناتج 4.50×10⁻⁷ m"]'::jsonb, '["1 nm = 1×10⁻⁹ m","4.50×10² × 10⁻⁹ = 4.50×10⁻⁷ m"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الرمز","marks":1},{"element":"علاقة التحويل والتعويض","marks":1},{"element":"الناتج بالأرقام المعنوية الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف ورمز وتحويل صحيح"},{"level":"3 درجات","description":"تعريف ورمز صحيحان مع خطأ في الأس"},{"level":"2 درجتان","description":"تعريف صحيح فقط أو تحويل صحيح فقط"},{"level":"1 درجة","description":"الرمز فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب الأس بشكل خاطئ: 10² × 10⁻⁹ = 10⁻¹¹","تعريف الطول الموجي بالمسافة بين قمة وقاع","كتابة الرمز ν بدل λ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.050Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(29, null, null, null, '(أ) λ = 15 cm ÷ 2.5 = 6.0 cm. (ب) المسافة الأفقية بين قمة والقاع التالي تساوي نصف طول موجي = 3.0 cm؛ وخطؤه أن الطول الموجي هو المسافة بين قمتين متتاليتين أو قاعين متتاليين، لا بين قمة وقاع.', '["λ = 15 ÷ 2.5","λ = 6.0 cm","قيمة الطالب 3.0 cm (نصف الطول الموجي)","تصحيح الخطأ بالتعريف"]'::jsonb, '["λ = المسافة ÷ عدد الموجات = 15 ÷ 2.5 = 6.0 cm","قمة ← قاع تالٍ = λ/2 = 3.0 cm"]'::jsonb, '[{"element":"(أ) طريقة الحساب","marks":1},{"element":"(أ) الناتج 6.0 cm","marks":1},{"element":"(ب) قيمة الطالب 3.0 cm","marks":1},{"element":"(ب) بيان الخطأ بالتعريف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح وتحديد قيمة الطالب وخطئه"},{"level":"3 درجات","description":"حساب صحيح مع تفسير ناقص للخطأ"},{"level":"2 درجتان","description":"حساب (أ) فقط صحيح"},{"level":"1 درجة","description":"طريقة صحيحة مع خطأ حسابي"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب المسافة في عدد الموجات","عد نصف الموجة موجة كاملة","إهمال الوحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-11T11:15:01.051Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(30, null, null, null, '410 nm = 410×10⁻⁹ m = 4.10×10⁻⁷ m. بالمقارنة: 6.56×10⁻⁷ m > 4.10×10⁻⁷ m، فالخط 6.56×10⁻⁷ m (656 nm) أطول موجة. النسبة: 6.56 ÷ 4.10 = 1.60 مرة تقريبًا.', '["تحويل 410 nm إلى 4.10×10⁻⁷ m (أو 6.56×10⁻⁷ m إلى 656 nm)","تحديد أن 6.56×10⁻⁷ m أطول","النسبة 1.60"]'::jsonb, '["410 nm = 4.10×10⁻⁷ m","6.56×10⁻⁷ > 4.10×10⁻⁷","6.56 ÷ 4.10 = 1.60"]'::jsonb, '[{"element":"التحويل الصحيح","marks":2},{"element":"المقارنة الصحيحة","marks":1},{"element":"حساب النسبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحويل ومقارنة ونسبة صحيحة"},{"level":"3 درجات","description":"تحويل ومقارنة صحيحان مع خطأ في النسبة"},{"level":"1–2 درجة","description":"تحويل صحيح فقط أو مقارنة صحيحة دون تحويل"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["مقارنة الأرقام 410 و6.56 دون توحيد الوحدات","الخطأ في أس التحويل","قسمة الصغير على الكبير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.051Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(31, 2, 'التردد (ν) هو عدد الموجات التي تعبر نقطة محددة خلال ثانية واحدة، ويقاس بالهيرتز Hz أو s⁻¹.', '["هذا تعريف الطول الموجي.","هذا تعريف سعة الموجة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.054Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(32, 1, 'التردد = عدد الموجات ÷ الزمن بالثواني = 50 ÷ 10 = 5.0 Hz.', '["ناتج ضرب عدد الموجات في الزمن بدل القسمة.","","ناتج قسمة الزمن على عدد الموجات (عكس النسبة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.054Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(33, 0, 'الهيرتز يعني موجة واحدة في الثانية، فالتردد 5.0×10¹⁴ Hz يعني أن 5.0×10¹⁴ موجة تعبر نقطة محددة في كل ثانية.', '["","المسافة بين قمتين متتاليتين هي الطول الموجي، وتقاس بالمتر لا بالهيرتز.","ارتفاع القمة هو السعة، والهيرتز ليس وحدة طول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.054Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(34, 2, 'التردد = عدد الموجات ÷ الزمن: (أ) 30 ÷ 3 = 10 Hz ، (ب) 40 ÷ 8 = 5 Hz ، (ج) 12 ÷ 1 = 12 Hz؛ فالموجة (ج) ترددها الأكبر.', '["ترددها 10 Hz وهو أقل من تردد (ج).","عدد موجاتها أكبر لكن زمنها أطول، فترددها 5 Hz فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.055Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(35, 1, '1 MHz = 1×10⁶ Hz، إذن 98.5 MHz = 98.5×10⁶ Hz = 9.85×10⁷ Hz.', '["استُخدم 10³ (كيلو) بدل 10⁶ (ميجا).","","خطأ في تعديل الأس عند التحويل إلى الصيغة العلمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.055Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(36, 2, 'يرمز للتردد بالحرف الإغريقي ν (نيو).', '["λ رمز الطول الموجي.","c رمز سرعة الضوء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.055Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(37, 0, 'أشعة جاما لها أعلى تردد (نحو 10²⁰ Hz) وأقصر طول موجي، بينما موجات الراديو لها أقل تردد (نحو 10⁴ Hz).', '["","موجات الراديو لها أقل تردد في الطيف الكهرومغناطيسي.","تردد الميكروويف أقل بكثير من تردد أشعة جاما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.056Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(38, null, null, null, 'التردد: عدد الموجات التي تعبر نقطة محددة خلال ثانية. رمزه ν، ووحدته الهيرتز Hz (وتكافئ s⁻¹). التردد 1 Hz يعني أن موجة واحدة كاملة تعبر نقطة محددة كل ثانية.', '["التعريف","الرمز ν","الوحدة Hz أو s⁻¹","معنى 1 Hz: موجة واحدة في الثانية"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الرمز","marks":1},{"element":"الوحدة","marks":1},{"element":"معنى 1 Hz","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين التردد والطول الموجي","كتابة الوحدة m/s","كتابة الرمز v (السرعة) أو λ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.056Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(39, null, null, null, '(أ) ν = عدد الموجات ÷ الزمن = 1200 ÷ 4.0 s = 3.0×10² Hz (300 Hz). (ب) يتضاعف التردد ليصبح 6.0×10² Hz؛ لأن التردد هو عدد الموجات في الثانية، فمضاعفة العدد في الزمن نفسه تضاعفه.', '["العلاقة: التردد = عدد الموجات ÷ الزمن","الناتج 3.0×10² Hz","يتضاعف التردد","التفسير بالتعريف"]'::jsonb, '["ν = 1200 ÷ 4.0","ν = 3.0×10² Hz","عند مضاعفة العدد: ν = 2400 ÷ 4.0 = 6.0×10² Hz"]'::jsonb, '[{"element":"(أ) العلاقة والتعويض","marks":1},{"element":"(أ) الناتج بالوحدة","marks":1},{"element":"(ب) الاستنتاج مع التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح واستنتاج مفسر"},{"level":"3 درجات","description":"حساب صحيح واستنتاج دون تفسير"},{"level":"2 درجتان","description":"حساب صحيح فقط"},{"level":"1 درجة","description":"علاقة صحيحة مع خطأ حسابي"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قسمة الزمن على عدد الموجات","إهمال الوحدة","القول إن التردد يقل إلى النصف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.056Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(40, null, null, null, '98.5 MHz = 98.5×10⁶ Hz = 9.85×10⁷ Hz. 1200 kHz = 1200×10³ Hz = 1.20×10⁶ Hz. بما أن 9.85×10⁷ Hz > 1.20×10⁶ Hz فمحطة FM ترددها أكبر، أي يعبر نقطة ما من موجاتها عدد أكبر في كل ثانية.', '["1 MHz = 10⁶ Hz","9.85×10⁷ Hz","1 kHz = 10³ Hz","1.20×10⁶ Hz","المقارنة: FM أكبر مع الربط بتعريف التردد"]'::jsonb, '["98.5×10⁶ = 9.85×10⁷ Hz","1200×10³ = 1.20×10⁶ Hz","9.85×10⁷ > 1.20×10⁶"]'::jsonb, '[{"element":"تحويل تردد FM","marks":2},{"element":"تحويل تردد AM","marks":2},{"element":"المقارنة والربط بالتعريف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحويلان صحيحان ومقارنة مفسرة"},{"level":"3–4 درجات","description":"تحويل صحيح وآخر بخطأ في الأس مع مقارنة"},{"level":"1–2 درجة","description":"تحويل واحد صحيح أو مقارنة دون تحويل صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين 10³ و10⁶","المقارنة بين 98.5 و1200 دون توحيد الوحدات","الخطأ في كتابة الصيغة العلمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.057Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(41, 0, 'سعة الموجة هي ارتفاع القمة أو انخفاض القاع عن خط الأصل (خط الاتزان).', '["","هذا تعريف الطول الموجي.","هذا يصف التردد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.059Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(42, 1, 'السعة تقاس من خط الأصل إلى القمة، وخط الأصل في منتصف المسافة بين القمة والقاع، إذن السعة = 8.0 ÷ 2 = 4.0 cm.', '["هذه المسافة من القمة إلى القاع وتساوي ضعف السعة.","","ناتج ضرب المسافة في 2 بدل قسمتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.059Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(43, 2, 'السعة هي ارتفاع القمة عن خط الأصل، فزيادة ارتفاع القمم مع بقاء المسافة بينها ثابتة تغيّر السعة دون تغيير الطول الموجي أو التردد.', '["هذا يغير التردد لا السعة.","هذا يغير الطول الموجي (ومعه التردد) لا السعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.059Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(44, 2, 'السعة نصف المسافة الرأسية بين القمة والقاع: 10 ÷ 2 = 5.0 cm. أما المسافة بين قمتين متتاليتين فهي الطول الموجي ولا علاقة لها بالسعة.', '["هذه المسافة الرأسية بين القمة والقاع وهي ضعف السعة.","هذه المسافة بين قمتين متتاليتين، أي الطول الموجي للموجة (ب).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.060Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(45, 1, 'ذكرت المذكرة أن الطول الموجي والتردد لا يؤثران في السعة، فهي خاصية مستقلة.', '["لا علاقة بين السعة والتردد.","","لا علاقة بين السعة والطول الموجي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.061Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(46, 0, 'السعة ارتفاع (مسافة رأسية) فتقاس بوحدة طول مثل cm أو m.', '["","الهيرتز وحدة التردد.","s⁻¹ تكافئ الهيرتز وهي وحدة التردد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.061Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(47, 0, 'ارتفاع القمة عن خط الأصل هو السعة، فسعة (س) = 3 cm وسعة (ص) = 1 cm، أي أن سعة (س) ثلاثة أمثال سعة (ص)، والتردد متساوٍ كما في المعطى.', '["","المعطى أن الترددين متساويان، والسعة لا تؤثر في التردد.","عكس للعلاقة؛ قمم (س) هي الأعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.061Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(48, null, null, null, 'سعة الموجة: ارتفاع القمة أو انخفاض القاع عن خط الأصل. لقياسها على الرسم: نرسم خط الأصل (خط الاتزان) في منتصف المسافة بين القمم والقيعان، ثم نقيس المسافة الرأسية من خط الأصل إلى قمة (أو إلى قاع). الخطأ الشائع: قياس المسافة الرأسية من القمة إلى القاع وعدّها السعة، وهي في الحقيقة ضعف السعة.', '["التعريف","تحديد خط الأصل","القياس الرأسي من خط الأصل إلى القمة أو القاع","الخطأ: القياس من القمة إلى القاع"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"طريقة القياس","marks":2},{"element":"الخطأ الشائع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وطريقة قياس وخطأ شائع صحيح"},{"level":"3 درجات","description":"تعريف وطريقة قياس صحيحان"},{"level":"1–2 درجة","description":"التعريف فقط أو طريقة ناقصة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين السعة والطول الموجي","قياس السعة أفقيًا","عدّ المسافة من القمة إلى القاع سعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.061Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(49, null, null, null, 'السعة: خط الأصل في منتصف المسافة الرأسية بين القمة والقاع، فالسعة = 12 ÷ 2 = 6.0 cm. الطول الموجي: هو المسافة بين قمتين متتاليتين = 20 cm مباشرة.', '["السعة = نصف المسافة الرأسية بين القمة والقاع","السعة 6.0 cm","الطول الموجي = المسافة بين قمتين متتاليتين","الطول الموجي 20 cm"]'::jsonb, '["السعة = 12 ÷ 2 = 6.0 cm","λ = 20 cm"]'::jsonb, '[{"element":"حساب السعة مع التعليل","marks":2},{"element":"تحديد الطول الموجي مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"القيمتان صحيحتان مع التعليل"},{"level":"3 درجات","description":"القيمتان صحيحتان دون تعليل كافٍ"},{"level":"2 درجتان","description":"قيمة واحدة صحيحة"},{"level":"1 درجة","description":"تعريف صحيح دون حساب"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة السعة 12 cm","قسمة الطول الموجي على 2","تبديل القيمتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.062Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(50, null, null, null, 'مثال: موجتان المسافة بين قمتين متتاليتين في كل منهما 4 cm (الطول الموجي نفسه، فالتردد نفسه)، لكن قمم الأولى ترتفع 1 cm عن خط الأصل وقمم الثانية 3 cm. اختلفت السعة (1 cm و3 cm) مع ثبات الطول الموجي والتردد، فتغير السعة لا يرتبط بتغير الطول الموجي أو التردد، أي أنهما لا يؤثران فيها.', '["موجتان بالطول الموجي نفسه","سعتان مختلفتان","الاستنتاج: السعة مستقلة عن الطول الموجي والتردد"]'::jsonb, '[]'::jsonb, '[{"element":"وصف/رسم صحيح لموجتين بالطول الموجي نفسه","marks":1},{"element":"سعتان مختلفتان موضحتان","marks":1},{"element":"الربط بالاستنتاج","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح واستنتاج واضح"},{"level":"2–3 درجات","description":"وصف صحيح واستنتاج ناقص"},{"level":"1 درجة","description":"وصف موجتين تختلفان في أكثر من خاصية"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["رسم موجتين تختلفان في الطول الموجي والسعة معًا","الاعتقاد بأن الموجة الأعلى سعة أسرع","قياس السعة من القمة إلى القاع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.062Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(51, 1, 'يقاس التردد بالهيرتز Hz، ويكافئ s⁻¹ (موجة في الثانية).', '["المتر وحدة الطول الموجي.","","الجول وحدة الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.064Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(52, 2, '1 Hz = 1 s⁻¹، أي موجة واحدة في الثانية.', '["m/s وحدة السرعة.","الثانية وحدة الزمن لا التردد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.064Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(53, 0, '1 kHz = 10³ Hz، إذن 750 kHz = 750×10³ Hz = 7.50×10⁵ Hz.', '["","استُخدم 10⁶ (ميجا) بدل 10³ (كيلو).","ناتج القسمة على 10³ بدل الضرب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.064Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(54, 1, '1 MHz = 10⁶ Hz، إذن 2.0×10⁸ Hz ÷ 10⁶ = 2.0×10² MHz = 200 MHz.', '["ناتج الضرب في 10⁶ بدل القسمة.","","استُخدم 10³ بدل 10⁶ في التحويل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.064Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(55, 2, 'الكمية المقيسة بـ s⁻¹ (أي Hz) هي التردد، وهي القيمة (3).', '["وحدتها m فهي طول موجي.","وحدتها m/s فهي سرعة الضوء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.065Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(56, 0, 'ν = c ÷ λ ، والوحدة (m/s) ÷ m = 1/s = s⁻¹ وهي الهيرتز.', '["","هذا ناتج ضرب الوحدتين لا قسمتهما.","الثانية ناتج قسمة الطول على السرعة (عكس العلاقة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.065Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(57, 0, 'بالتحويل إلى Hz: 5000 Hz = 5×10³ Hz ، 50 kHz = 5×10⁴ Hz ، 5 MHz = 5×10⁶ Hz؛ فالترتيب التصاعدي: 5000 Hz < 50 kHz < 5 MHz.', '["","هذا ترتيب تنازلي لا تصاعدي.","50 kHz = 5×10⁴ Hz وهي أكبر من 5000 Hz."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.065Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(58, null, null, null, 'وحدة التردد الهيرتز ورمزها Hz، وتكافئ s⁻¹. والسبب أن التردد هو عدد الموجات التي تعبر نقطة خلال ثانية، والعدد ليس له وحدة، فتكون الوحدة 1/ثانية أي s⁻¹ (1 Hz = موجة واحدة في الثانية).', '["الهيرتز","الرمز Hz","تكافئ s⁻¹","التعليل بتعريف التردد"]'::jsonb, '[]'::jsonb, '[{"element":"اسم الوحدة ورمزها","marks":1},{"element":"الوحدة المكافئة s⁻¹","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة مع تعليل"},{"level":"2–3 درجات","description":"الوحدة والمكافئ دون تعليل كافٍ"},{"level":"1 درجة","description":"اسم الوحدة فقط"},{"level":"صفر","description":"وحدة خاطئة"}]'::jsonb, '["كتابة m/s أو s للتردد","الخلط بين Hz وH","عدم ربط الوحدة بتعريف التردد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.065Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(59, null, null, null, '(أ) 102.5 MHz = 102.5×10⁶ Hz = 1.025×10⁸ Hz. (ب) 640 kHz = 640×10³ Hz = 6.40×10⁵ Hz. النسبة: 1.025×10⁸ ÷ 6.40×10⁵ ≈ 160 مرة.', '["1 MHz = 10⁶ Hz","1.025×10⁸ Hz","1 kHz = 10³ Hz","6.40×10⁵ Hz","النسبة ≈ 160"]'::jsonb, '["102.5×10⁶ = 1.025×10⁸ Hz","640×10³ = 6.40×10⁵ Hz","1.025×10⁸ ÷ 6.40×10⁵ = 160"]'::jsonb, '[{"element":"(أ) التحويل","marks":2},{"element":"(ب) التحويل","marks":2},{"element":"حساب النسبة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحويلان ونسبة صحيحة"},{"level":"3–4 درجات","description":"تحويلان صحيحان مع خطأ في النسبة أو خطأ في أحد الأسين"},{"level":"1–2 درجة","description":"تحويل واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين بادئتي كيلو وميجا","كتابة 102.5×10⁶ بصيغة علمية خاطئة","قسمة القيمتين دون توحيد الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.066Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(60, null, null, null, '(أ) ν = c ÷ λ ، والوحدة = (m/s) ÷ m = s⁻¹ = Hz. (ب) ν = 3.00×10⁸ ÷ 0.50 = 6.0×10⁸ Hz، وبالميجاهيرتز: 6.0×10⁸ ÷ 10⁶ = 6.0×10² MHz (600 MHz).', '["إعادة ترتيب العلاقة ν = c/λ","تحليل الوحدات إلى s⁻¹","ν = 6.0×10⁸ Hz","ν = 600 MHz"]'::jsonb, '["ν = c ÷ λ","(m/s) ÷ m = s⁻¹ = Hz","ν = 3.00×10⁸ ÷ 0.50 = 6.0×10⁸ Hz","6.0×10⁸ ÷ 10⁶ = 6.0×10² MHz"]'::jsonb, '[{"element":"(أ) تحليل الوحدات","marks":2},{"element":"(ب) التردد بالهيرتز","marks":2},{"element":"(ب) التحويل إلى MHz","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء كلها صحيحة"},{"level":"3–4 درجات","description":"حساب صحيح مع خلل في تحليل الوحدات أو التحويل"},{"level":"1–2 درجة","description":"العلاقة صحيحة مع أخطاء حسابية"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب c في λ","ناتج الوحدة m²/s","الضرب في 10⁶ عند التحويل إلى MHz"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.066Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(61, 1, 'الطول الموجي أقصر مسافة بين قمتين متتاليتين، والسهم 1 يمتد أفقيًا من قمة إلى القمة التالية لها.', '["السهم 4 من قمة إلى القاع التالي أفقيًا، وطوله نصف طول موجي.","","السهم 3 رأسي من القمة إلى القاع، ويساوي ضعف السعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.068Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(62, 0, 'السعة ارتفاع القمة عن خط الأصل، والسهم 2 يمتد رأسيًا من خط الأصل إلى القمة.', '["","السهم 3 من القمة إلى القاع ويساوي ضعف السعة.","السهم 1 أفقي بين قمتين متتاليتين ويمثل الطول الموجي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.068Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(63, 2, 'الطول الموجي المسافة بين قمتين متتاليتين: 6 − 2 = 4 cm (و10 − 6 = 4 cm).', '["2 cm هو موضع القمة الأولى لا المسافة بين قمتين.","8 cm المسافة بين القمة الأولى والثالثة، أي طولان موجيان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.069Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(64, 0, 'السعة ارتفاع القمة عن خط الأصل = 3 cm.', '["","6 cm المسافة الرأسية بين القمة والقاع، وهي ضعف السعة.","ناتج قسمة السعة على 2 خطأً."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.069Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(65, 2, 'الطول الموجي المسافة بين قاعين متتاليين أو قمتين متتاليتين، و(ب) و(د) قاعان متتاليان (ويصح أيضًا بين أ وج).', '["(أ) قمة و(ب) قاع؛ المسافة بينهما نصف طول موجي.","(ب) قاع و(ج) قمة؛ المسافة بينهما نصف طول موجي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.070Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(66, 0, 'الطول الموجي هو المسافة الأفقية بين قمتين متتاليتين (6 cm)، والسعة ارتفاع القمة عن خط الأصل (2 cm).', '["","بُدّل بين الطول الموجي والسعة.","المسافة الأفقية بين قمة وقاع نصف طول موجي (فيصبح λ = 12 cm)، والمسافة الرأسية بينهما ضعف السعة (فتصبح السعة 1 cm)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.070Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(67, 1, 'الطول الموجي: (س) 10 − 2 = 8 cm و(ص) 7 − 1 = 6 cm. السعة: (س) 4 ÷ 2 = 2 cm لأن القياس من القمة إلى القاع ضعف السعة، و(ص) 3 cm لأن القياس من خط الأصل؛ فسعة (ص) أكبر.', '["الطولان الموجيان 8 cm و6 cm فهما مختلفان.","","سعة (س) 2 cm لا 4 cm؛ لأن 4 cm قيست من القمة إلى القاع، فالسعتان مختلفتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.071Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(68, null, null, null, 'الرسم: خط أفقي يمثل خط الأصل، وفوقه وتحته موجة منتظمة. الطول الموجي: سهم أفقي يبدأ من قمة وينتهي عند القمة التالية لها مباشرة (أو من قاع إلى القاع التالي). السعة: سهم رأسي يبدأ من خط الأصل وينتهي عند قمة (أو عند قاع). خط الأصل: الخط الأفقي في منتصف المسافة بين القمم والقيعان.', '["رسم خط الأصل في المنتصف","سهم الطول الموجي بين قمتين متتاليتين أو قاعين متتاليين","سهم السعة رأسيًا من خط الأصل إلى القمة أو القاع","انتظام الموجة"]'::jsonb, '[]'::jsonb, '[{"element":"رسم الموجة وخط الأصل","marks":1},{"element":"تحديد الطول الموجي صحيحًا","marks":1},{"element":"تحديد السعة صحيحًا","marks":1},{"element":"توضيح بداية الأسهم ونهايتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم منتظم وتحديد صحيح للعناصر الثلاثة"},{"level":"3 درجات","description":"تحديد صحيح مع نقص في التوضيح"},{"level":"2 درجتان","description":"تحديد صحيح لعنصر واحد من الطول الموجي أو السعة"},{"level":"1 درجة","description":"رسم الموجة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["رسم سهم الطول الموجي من قمة إلى قاع","رسم سهم السعة من القمة إلى القاع","رسم خط الأصل عند القيعان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.071Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(69, null, null, null, 'الطول الموجي: المسافة الأفقية بين قمتين متتاليتين = 5.5 − 1.5 = 4.0 cm (أو بين قاعين متتاليين 7.5 − 3.5 = 4.0 cm). السعة: البعد الرأسي للقمة عن خط الأصل = 2.5 cm (وليست 5.0 cm التي هي المسافة من القمة إلى القاع).', '["اختيار قمتين متتاليتين أو قاعين متتاليين","λ = 4.0 cm","السعة من خط الأصل","السعة = 2.5 cm"]'::jsonb, '["λ = 5.5 − 1.5 = 4.0 cm","السعة = |+2.5| = 2.5 cm"]'::jsonb, '[{"element":"الطول الموجي مع النقاط المستخدمة","marks":2},{"element":"السعة مع التوضيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"القيمتان صحيحتان مع التوضيح"},{"level":"3 درجات","description":"القيمتان صحيحتان دون توضيح النقاط"},{"level":"2 درجتان","description":"قيمة واحدة صحيحة"},{"level":"1 درجة","description":"محاولة صحيحة الطريقة بخطأ حسابي"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["حساب λ من قمة إلى قاع = 2.0 cm","كتابة السعة 5.0 cm","استخدام الإحداثي الأفقي للقمة الأولى طولًا موجيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.071Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(70, null, null, null, '(أ) الموجة (أ): λ = 3 cm والسعة 2 cm. الموجة (ب): λ = 6 cm والسعة 1 cm. (ب) الموجة (أ) ترددها أكبر؛ لأن طولها الموجي أقصر، والعلاقة بين الطول الموجي والتردد عكسية لأن جميع الموجات الكهرومغناطيسية تسير بالسرعة نفسها (c = λν). أما السعة فلا تؤثر في التردد.', '["λ(أ) = 3 cm والسعة 2 cm","λ(ب) = 6 cm والسعة 1 cm","(أ) ترددها أكبر","التعليل بالعلاقة العكسية وثبات c","السعة لا تحدد التردد"]'::jsonb, '[]'::jsonb, '[{"element":"قيم الموجة (أ)","marks":1},{"element":"قيم الموجة (ب)","marks":1},{"element":"تحديد الموجة الأعلى ترددًا","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للقيم واستنتاج مع تعليل كامل"},{"level":"3–4 درجات","description":"قيم صحيحة واستنتاج بتعليل ناقص"},{"level":"1–2 درجة","description":"قيم صحيحة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الاستدلال بالسعة على التردد","عكس العلاقة بين λ وν","الخلط بين الطول الموجي والسعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.072Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(71, 1, 'من العلاقة c = λν، وبما أن c ثابتة، فكلما زاد الطول الموجي قل التردد، فالعلاقة عكسية.', '["في العلاقة الطردية يزداد أحدهما بزيادة الآخر، وهذا عكس ما يحدث هنا.","","ترتبط الكميتان بالعلاقة c = λν."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.074Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(72, 2, 'سرعة الموجة الكهرومغناطيسية تساوي حاصل ضرب طولها الموجي في ترددها: c = λν.', '["قسمة λ على ν تعطي وحدة m·s لا m/s.","قسمة ν على λ تعطي وحدة 1/(m·s) لا m/s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.074Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(73, 0, 'λν = c ثابت، فإذا تضاعف λ يجب أن يقل ν إلى النصف ليبقى الناتج ثابتًا.', '["","هذا يحدث في العلاقة الطردية، والعلاقة هنا عكسية.","التردد يتغير لأن حاصل الضرب λν يجب أن يبقى مساويًا لـ c."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.074Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(74, 1, 'جميع الموجات الكهرومغناطيسية تسير في الفراغ بالسرعة نفسها c، وبما أن c = λν فحاصل ضرب λ في ν ثابت، ولذا تكون العلاقة عكسية.', '["طاقة الفوتون تختلف باختلاف التردد، فالموجات ليست متساوية الطاقة.","","السعة لا تتأثر بالطول الموجي ولا التردد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.075Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(75, 2, 'العلاقة عكسية، فالإشعاع ذو أقصر طول موجي (الأشعة السينية 1×10⁻¹⁰ m) له أعلى تردد.', '["طوله الموجي أطول من الأشعة السينية فتردده أقل.","له أطول طول موجي في الجدول فتردده الأقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.075Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(76, 0, 'التردد يزداد كلما قصر الطول الموجي: موجات الراديو أطولها وأقلها ترددًا، ثم الميكروويف، ثم فوق البنفسجية، ثم الأشعة السينية أعلاها ترددًا.', '["","هذا ترتيب تصاعدي حسب الطول الموجي (أي تنازلي حسب التردد).","تردد الراديو أقل من الميكروويف، وتردد فوق البنفسجية أقل من السينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.075Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(77, 1, 'بما أن λν = c للموجتين، فإذا كان λ(أ) = 3λ(ب) فإن ν(أ) = ν(ب) ÷ 3.', '["هذه علاقة طردية، والصحيح أن العلاقة عكسية.","","الترددان متساويان فقط إذا تساوى الطولان الموجيان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.075Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(78, null, null, null, 'العلاقة عكسية: كلما زاد الطول الموجي قل التردد. المعادلة: c = λν، حيث c سرعة الضوء (3.00×10⁸ m/s)، وλ الطول الموجي (m)، وν التردد (Hz أو s⁻¹). التعليل: جميع الموجات الكهرومغناطيسية تسير في الفراغ بالسرعة نفسها c، فحاصل ضرب λ في ν ثابت، وزيادة أحدهما تستلزم نقص الآخر.', '["العلاقة عكسية","المعادلة c = λν","تعريف الرموز ووحداتها","التعليل بثبات c"]'::jsonb, '[]'::jsonb, '[{"element":"نوع العلاقة","marks":1},{"element":"المعادلة","marks":1},{"element":"تعريف الرموز","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"نوع العلاقة والمعادلة فقط"},{"level":"1 درجة","description":"نوع العلاقة فقط"},{"level":"صفر","description":"علاقة خاطئة"}]'::jsonb, '["القول إن العلاقة طردية","كتابة c = λ/ν","الاعتقاد بأن سرعة الموجات تختلف باختلاف نوعها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.076Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(79, null, null, null, '(1) λν = 6.00×10⁻⁷ × 5.00×10¹⁴ = 3.00×10⁸ m/s، وهي سرعة الضوء c. (2) (ب) ν = c ÷ λ = 3.00×10⁸ ÷ 3.00×10⁻⁷ = 1.00×10¹⁵ Hz. (ج) λ = c ÷ ν = 3.00×10⁸ ÷ 1.00×10¹⁴ = 3.00×10⁻⁶ m. (3) عندما قل الطول الموجي إلى النصف (أ← ب) تضاعف التردد، وعندما قل التردد (ج) زاد الطول الموجي؛ فالعلاقة عكسية وحاصل ضربهما ثابت يساوي c.', '["λν(أ) = 3.00×10⁸ m/s = c","ν(ب) = 1.00×10¹⁵ Hz","λ(ج) = 3.00×10⁻⁶ m","الاستنتاج: علاقة عكسية وحاصل الضرب ثابت"]'::jsonb, '["6.00×10⁻⁷ × 5.00×10¹⁴ = 3.00×10⁸","ν(ب) = 3.00×10⁸ ÷ 3.00×10⁻⁷ = 1.00×10¹⁵ Hz","λ(ج) = 3.00×10⁸ ÷ 1.00×10¹⁴ = 3.00×10⁻⁶ m"]'::jsonb, '[{"element":"(1) الحساب والتفسير","marks":1},{"element":"(2) قيمة ν(ب)","marks":1},{"element":"(2) قيمة λ(ج)","marks":1},{"element":"(3) الاستنتاج","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة واستنتاج مدعوم بالبيانات"},{"level":"3–4 درجات","description":"حسابات صحيحة مع استنتاج ناقص"},{"level":"1–2 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخطأ في جمع الأسس","ضرب c في λ لحساب ν","استنتاج علاقة طردية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.076Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(80, null, null, null, 'حسب الطول الموجي تصاعديًا: الأشعة السينية < فوق البنفسجية < الميكروويف < الراديو. حسب التردد تصاعديًا: الراديو < الميكروويف < فوق البنفسجية < الأشعة السينية. الترتيبان متعاكسان لأن العلاقة بين الطول الموجي والتردد عكسية (c = λν وc ثابتة لجميعها)، فالأقصر طولًا موجيًا هو الأعلى ترددًا.', '["الترتيب حسب الطول الموجي","الترتيب حسب التردد","التفسير بالعلاقة العكسية وثبات c"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب حسب الطول الموجي","marks":2},{"element":"الترتيب حسب التردد","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ترتيبان صحيحان وتفسير"},{"level":"3–4 درجات","description":"ترتيبان صحيحان دون تفسير أو خطأ في موضع واحد"},{"level":"1–2 درجة","description":"ترتيب واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["وضع الميكروويف قبل الراديو في الطول الموجي","إعطاء الترتيب نفسه للحالتين","التفسير باختلاف السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.077Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(81, 1, 'من c = λν نقسم الطرفين على ν: λ = c ÷ ν.', '["الضرب يعطي وحدة m/s² وليس m.","","قسمة ν على c عكس العلاقة الصحيحة وتعطي وحدة m⁻¹."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.079Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(82, 2, 'λ = c ÷ ν = (3.00×10⁸ m/s) ÷ (2.45×10⁹ s⁻¹) = 1.22×10⁻¹ m.', '["ناتج ضرب c في ν بدل القسمة.","ناتج قسمة ν على c (عكس العلاقة).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.080Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(83, 0, 'ν = c ÷ λ = (3.00×10⁸) ÷ (5.00×10⁻⁷) = 6.00×10¹⁴ s⁻¹.', '["","ناتج قسمة λ على c (عكس العلاقة).","ناتج ضرب c في λ بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-11T11:15:01.080Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(84, 1, 'نحول التردد: 98.5 MHz = 9.85×10⁷ Hz، ثم λ = c ÷ ν = 3.00×10⁸ ÷ 9.85×10⁷ = 3.05 m.', '["نُسي تحويل MHz إلى Hz فقُسمت c على 98.5 مباشرة.","","ناتج قسمة التردد على c (عكس العلاقة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.080Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(85, 2, 'نحول: 4.50×10² nm = 4.50×10⁻⁷ m، ثم ν = c ÷ λ = 3.00×10⁸ ÷ 4.50×10⁻⁷ = 6.67×10¹⁴ s⁻¹.', '["نُسي تحويل nm إلى m.","ناتج قسمة λ (بالمتر) على c، أي عكس العلاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.080Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(86, 0, 'ν = c ÷ λ = (3.00×10⁸) ÷ (1.15×10⁻¹⁰) = 2.61×10¹⁸ s⁻¹.', '["","ناتج قسمة λ على c.","ناتج ضرب c في λ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-11T11:15:01.081Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(87, 0, 'λ = c ÷ ν = 3.00×10⁸ ÷ 1.00×10⁸ = 3.00 m للموجة (أ). أما (ب) فطولها 1.00 m و(ج) 0.333 m.', '["","λ = 3.00×10⁸ ÷ 3.00×10⁸ = 1.00 m.","λ = 3.00×10⁸ ÷ 9.00×10⁸ = 0.333 m؛ وقد يختارها من يضرب بدل أن يقسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.081Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(88, null, null, null, 'المعطيات: ν = 3.44×10⁹ s⁻¹ ، c = 3.00×10⁸ m/s. المطلوب: λ. العلاقة: c = λν ← λ = c ÷ ν. التعويض: λ = (3.00×10⁸ m/s) ÷ (3.44×10⁹ s⁻¹) = 8.72×10⁻² m.', '["المعطيات والمطلوب","λ = c ÷ ν","التعويض الصحيح","الناتج 8.72×10⁻² m"]'::jsonb, '["λ = c ÷ ν","λ = 3.00×10⁸ ÷ 3.44×10⁹","λ = 8.72×10⁻² m"]'::jsonb, '[{"element":"المعطيات والعلاقة","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج العددي","marks":1},{"element":"الوحدة والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل بناتج 8.72×10⁻² m"},{"level":"3 درجات","description":"حل صحيح مع خطأ في الوحدة أو الأرقام المعنوية"},{"level":"2 درجتان","description":"علاقة وتعويض صحيحان مع خطأ في الأسس"},{"level":"1 درجة","description":"العلاقة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب c في ν","قسمة ν على c","الخطأ في طرح الأسس (8 − 9 = −1)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.081Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(89, null, null, null, '(أ) 656 nm = 656×10⁻⁹ m = 6.56×10⁻⁷ m. (ب) ν = c ÷ λ = 3.00×10⁸ ÷ 6.56×10⁻⁷ = 4.57×10¹⁴ s⁻¹. (ج) أكبر؛ لأن العلاقة بين الطول الموجي والتردد عكسية.', '["التحويل 6.56×10⁻⁷ m","ν = c ÷ λ","ν = 4.57×10¹⁴ s⁻¹","الخط الأقصر طولًا موجيًا تردده أكبر"]'::jsonb, '["656×10⁻⁹ = 6.56×10⁻⁷ m","ν = 3.00×10⁸ ÷ 6.56×10⁻⁷ = 4.57×10¹⁴ s⁻¹"]'::jsonb, '[{"element":"(أ) التحويل","marks":1},{"element":"(ب) العلاقة والتعويض","marks":1},{"element":"(ب) الناتج بالوحدة","marks":1},{"element":"(ج) الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"3 درجات","description":"خطأ في جزء واحد"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان تحويل nm إلى m فيكون الناتج 4.57×10⁵","الخطأ في أس التحويل","القول إن التردد أصغر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.082Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(90, null, null, null, '(أ) AM: ν = 1200 kHz = 1.20×10⁶ Hz، λ = 3.00×10⁸ ÷ 1.20×10⁶ = 2.50×10² m. FM: ν = 98.5 MHz = 9.85×10⁷ Hz، λ = 3.00×10⁸ ÷ 9.85×10⁷ = 3.05 m. (ب) الطول الموجي لموجات AM أكبر بكثير (نحو 82 مرة)؛ لأن ترددها أقل، والعلاقة بين التردد والطول الموجي عكسية (λν = c ثابت).', '["تحويل الترددين إلى Hz","λ(AM) = 2.50×10² m","λ(FM) = 3.05 m","المقارنة والتفسير بالعلاقة العكسية"]'::jsonb, '["1200 kHz = 1.20×10⁶ Hz ، 98.5 MHz = 9.85×10⁷ Hz","λ(AM) = 3.00×10⁸ ÷ 1.20×10⁶ = 2.50×10² m","λ(FM) = 3.00×10⁸ ÷ 9.85×10⁷ = 3.05 m","2.50×10² ÷ 3.05 ≈ 82"]'::jsonb, '[{"element":"تحويل الوحدات","marks":1},{"element":"حساب λ(AM)","marks":1},{"element":"حساب λ(FM)","marks":1},{"element":"المقارنة والتفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة ومقارنة مفسرة"},{"level":"3–4 درجات","description":"حسابان صحيحان مع تفسير ناقص"},{"level":"1–2 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان تحويل kHz وMHz","الخلط بين 10³ و10⁶","تفسير الفرق بالسعة أو السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.082Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(91, 1, 'الكم هو أقل كمية من الطاقة يمكن أن تكتسبها الذرة أو تفقدها، وطاقته E = hν.', '["الكم أصغر كمية لا أكبرها.","","الطاقة الكلية للشعاع تتكون من عدد كبير من الكمات، والكم الواحد هو أصغر وحدة منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.084Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(92, 2, 'افترض ماكس بلانك أن الطاقة تُكتسب أو تُفقد على شكل كمات، وأن طاقة الكم تتناسب طرديًا مع التردد (E = hν).', '["بور وضع نموذجًا لذرة الهيدروجين بمستويات طاقة محددة، مستفيدًا لاحقًا من فكرة التكميم.","دي برولي اقترح الطبيعة الموجية للجسيمات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.084Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(93, 1, 'الذرة تكتسب أو تفقد الطاقة بأعداد صحيحة من الكمات (hν، 2hν، 3hν ...)، ولا تكتسب كسرًا من الكم، فالمقدار 1.5hν غير ممكن.', '["2hν عدد صحيح من الكمات (كمّان) فيمكن اكتسابه.","","3hν عدد صحيح من الكمات (ثلاث كمات) فيمكن اكتسابه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.084Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(94, 0, 'E = hν = (6.626×10⁻³⁴ J·s)(7.230×10¹⁴ s⁻¹) = 4.791×10⁻¹⁹ J.', '["","ناتج قسمة h على ν بدل الضرب.","ناتج قسمة ν على h."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.085Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(95, 0, 'التكميم يعني أن الطاقة تُكتسب بمقادير محددة (كمات)، كدرجات السلم التي لا يمكن الوقوف بينها، لا بصورة متصلة.', '["","المنحدر يمثل تغير الطاقة بصورة متصلة، وهو عكس فكرة التكميم.","تدفق الماء المتصل يمثل اكتساب الطاقة بصورة متصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.085Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(96, 2, 'طاقة الكم E = hν تتناسب طرديًا مع التردد، وأقل تردد للإشعاع (أ) 3.0×10¹² s⁻¹، فطاقة كمه الأصغر (نحو 2.0×10⁻²¹ J).', '["تردده 6.0×10¹⁴ s⁻¹ فطاقة كمه أكبر من (أ).","تردده أعلى ما في الجدول فطاقة كمه الأكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.085Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(97, 2, 'طاقة الكم E = hν طردية مع التردد، وزيادة الطول الموجي تعني نقص التردد (c = λν)، فتقل طاقة الكم.', '["هذا مفهوم خاطئ شائع؛ العلاقة بين طاقة الكم والطول الموجي عكسية.","طاقة الكم تعتمد على تردد الإشعاع (E = hν).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.085Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(98, null, null, null, 'الكم: أقل كمية من الطاقة يمكن أن تكتسبها الذرة أو تفقدها. فرضية بلانك: المادة لا تكتسب الطاقة أو تفقدها بصورة متصلة، بل على شكل كمات محددة، وتكتسب أو تفقد عددًا صحيحًا منها (hν، 2hν، 3hν ...). العلاقة: E(الكم) = hν، حيث E طاقة الكم بالجول (J)، وh ثابت بلانك = 6.626×10⁻³⁴ J·s، وν تردد الإشعاع (s⁻¹).', '["تعريف الكم","الطاقة لا تُكتسب بصورة متصلة بل بكمات","أعداد صحيحة من الكمات","E = hν","تعريف الرموز وقيمة h ووحداتها"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الكم","marks":1},{"element":"فرضية بلانك","marks":2},{"element":"العلاقة وتعريف رموزها","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة دقيقة"},{"level":"3–4 درجات","description":"تعريف وعلاقة صحيحان مع فرضية ناقصة"},{"level":"1–2 درجة","description":"التعريف أو العلاقة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تعريف الكم بأنه أكبر كمية من الطاقة","كتابة E = h/ν","الاعتقاد بإمكان اكتساب كسر من الكم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.086Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(99, null, null, null, '(أ) E = hν = 6.626×10⁻³⁴ × 6.0×10¹⁴ = 4.0×10⁻¹⁹ J. (ب) 3 × 4.0×10⁻¹⁹ = 1.2×10⁻¹⁸ J. (ج) لا؛ لأن 6.0×10⁻¹⁹ ÷ 4.0×10⁻¹⁹ = 1.5 كم، والذرة تفقد الطاقة بأعداد صحيحة من الكمات فقط.', '["E = hν = 4.0×10⁻¹⁹ J","طاقة ثلاث كمات 1.2×10⁻¹⁸ J","عدد الكمات 1.5","الاستنتاج: غير ممكن لأنه ليس عددًا صحيحًا"]'::jsonb, '["E = 6.626×10⁻³⁴ × 6.0×10¹⁴ = 4.0×10⁻¹⁹ J","3E = 1.2×10⁻¹⁸ J","6.0×10⁻¹⁹ ÷ 4.0×10⁻¹⁹ = 1.5"]'::jsonb, '[{"element":"(أ) حساب طاقة الكم","marks":2},{"element":"(ب) طاقة ثلاث كمات","marks":1},{"element":"(ج) الاستنتاج مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة واستنتاج معلل"},{"level":"3–4 درجات","description":"حسابات صحيحة مع تعليل ناقص"},{"level":"1–2 درجة","description":"حساب (أ) فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قسمة h على ν","جمع الطاقات بدل ضربها في عدد الكمات بشكل صحيح","القول إن الذرة تفقد أي مقدار من الطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.086Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(100, null, null, null, 'الطاقة المتصلة: يمكن أن تتغير بأي مقدار مهما صغر، مثل الصعود على منحدر (يمكن التوقف عند أي ارتفاع). الطاقة المكمّاة: تتغير بمقادير محددة فقط (كمات)، مثل الصعود على درج (لا يمكن الوقوف بين درجتين). الذرة تكتسب الطاقة وتفقدها بصورة مكمّاة: بأعداد صحيحة من الكمات، طاقة كل منها hν.', '["وصف الطاقة المتصلة","مثال للمتصلة","وصف الطاقة المكماة","مثال للمكماة","الذرة: مكمّاة بأعداد صحيحة من hν"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة بين الفكرتين","marks":2},{"element":"مثالان مناسبان","marks":2},{"element":"تحديد ما ينطبق على الذرة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة دقيقة ومثالان مناسبان وتحديد صحيح"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع مثال واحد أو تحديد دون تعليل"},{"level":"1–2 درجة","description":"تعريف إحدى الفكرتين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب أمثلة غير مناسبة للتكميم (كتدفق الماء)","القول إن الذرة تكتسب الطاقة بصورة متصلة","الخلط بين الكم والفوتون دون توضيح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.087Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(101, 0, 'الطيف الكهرومغناطيسي سلسلة متصلة من الموجات الكهرومغناطيسية تسير جميعها بسرعة الضوء، وتختلف في التردد والطول الموجي فقط، ويشمل من موجات الراديو حتى أشعة جاما.', '["","هذا وصف لطيف الانبعاث الذري (الخطي).","الضوء المرئي جزء صغير فقط من الطيف الكهرومغناطيسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:01.089Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(102, 1, 'جميع موجات الطيف الكهرومغناطيسي تسير بسرعة الضوء في الفراغ ولها الطبيعة نفسها، وتختلف في التردد والطول الموجي فقط.', '["سرعتها جميعًا في الفراغ واحدة وتساوي c.","","جميعها موجات كهرومغناطيسية لا تحتاج وسطًا ماديًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.089Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(103, 2, 'يتحلل الضوء الأبيض إلى ألوان (أحمر، برتقالي، أصفر، أخضر، أزرق، نيلي، بنفسجي) متصلة دون فجوات، فيسمى طيفًا مستمرًا (متصلًا).', '["الطيف الخطي خطوط منفصلة تفصلها مناطق معتمة، كطيف انبعاث الهيدروجين.","طيف الامتصاص يظهر فيه خطوط معتمة لترددات امتصتها الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.089Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(104, 0, 'الطيف المرئي مستمر لأن الألوان تتدرج دون فجوات، وكل نقطة فيه تتوافق مع طول موجي وتردد مميزين.', '["","لكل لون طول موجي مختلف؛ فالأحمر أطولها والبنفسجي أقصرها.","ألوان الضوء تسير بالسرعة نفسها في الفراغ وتختلف في التردد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.090Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(105, 1, 'الأحمر في طرف الطيف المرئي ذي التردد الأقل، فطوله الموجي الأطول، والبنفسجي أقصرها طولًا موجيًا.', '["البنفسجي له أقصر طول موجي وأعلى تردد في الطيف المرئي.","","الأخضر في وسط الطيف المرئي، فطوله الموجي أقصر من الأحمر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.090Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(106, 2, 'ترتيب الطيف تصاعديًا حسب التردد: الراديو، الميكروويف، تحت الحمراء، الضوء المرئي، فوق البنفسجية، السينية، جاما؛ فالمنطقة بين الميكروويف والضوء المرئي هي الأشعة تحت الحمراء.', '["الأشعة فوق البنفسجية تقع بعد الضوء المرئي (ترددها أعلى منه).","أشعة جاما في طرف الطيف ذي التردد الأعلى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.090Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(107, 0, 'الطيف الكهرومغناطيسي واسع جدًا (من موجات الراديو حتى أشعة جاما)، والضوء المرئي الذي تحسه العين جزء صغير منه.', '["","الضوء المرئي مدى ضيق من الأطوال الموجية مقارنة بالطيف كله.","أشعة جاما أقصر موجات الطيف وأعلاها ترددًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:01.090Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(108, null, null, null, 'الطيف الكهرومغناطيسي: سلسلة موجات متصلة تسير بسرعة الضوء وتختلف في التردد والطول الموجي فقط، ويمتد من موجات الراديو (أطولها موجة وأقلها ترددًا) إلى أشعة جاما (أقصرها موجة وأعلاها ترددًا). الثابت: السرعة في الفراغ (c = 3.00×10⁸ m/s) والطبيعة الكهرومغناطيسية. المتغير: التردد والطول الموجي (وطاقة الفوتون تبعًا للتردد).', '["سلسلة موجات متصلة","تسير بسرعة الضوء","تختلف في التردد والطول الموجي فقط","امتداده من الراديو إلى جاما","تحديد الثابت والمتغير"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"الثابت","marks":1},{"element":"المتغير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وتحديد صحيح للثابت والمتغير"},{"level":"3 درجات","description":"تعريف صحيح مع نقص في أحدهما"},{"level":"2 درجتان","description":"تعريف ناقص مع تحديد صحيح"},{"level":"1 درجة","description":"عبارة عامة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين الطيف الكهرومغناطيسي والطيف المرئي","القول إن السرعة تختلف من نوع لآخر","الخلط مع طيف الانبعاث الخطي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.090Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(109, null, null, null, '(أ) يشاهد حزمة ألوان متدرجة: أحمر، برتقالي، أصفر، أخضر، أزرق، نيلي، بنفسجي. (ب) لأن الألوان تتدرج دون فجوات، وكل نقطة فيه تتوافق مع طول موجي وتردد مميزين. (ج) الأحمر: أطول طولًا موجيًا وأقل ترددًا؛ البنفسجي: أقصر طولًا موجيًا وأعلى ترددًا (فطاقته أكبر).', '["الألوان السبعة مرتبة","التعليل: تدرج دون فجوات، لكل نقطة λ وν مميزان","الأحمر: λ أكبر وν أقل","البنفسجي: λ أصغر وν أكبر"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الوصف والترتيب","marks":1},{"element":"(ب) التعليل","marks":2},{"element":"(ج) المقارنة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"3–4 درجات","description":"خطأ أو نقص في جزء واحد"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس ترتيب الألوان أو وضع الأخضر في الطرف","تعليل الاستمرار بتساوي الأطوال الموجية","القول إن الأحمر أعلى ترددًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.091Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(110, null, null, null, 'الترتيب تصاعديًا حسب الطول الموجي: أشعة جاما < الأشعة السينية < فوق البنفسجية < الضوء المرئي < تحت الحمراء < الميكروويف < موجات الراديو. أعلى تردد: أشعة جاما؛ لأنها أقصر طولًا موجيًا. أقل تردد: موجات الراديو؛ لأنها أطول طولًا موجيًا. والسبب أن العلاقة بين الطول الموجي والتردد عكسية (c = λν).', '["الترتيب الصحيح للمناطق السبع","أعلى تردد: جاما","أقل تردد: الراديو","التعليل بالعلاقة العكسية"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":3},{"element":"تحديد أعلى وأقل تردد","marks":2},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"ترتيب كامل وتحديد صحيح مع تعليل"},{"level":"4–5 درجات","description":"خطأ في موضع واحد أو تعليل ناقص"},{"level":"2–3 درجات","description":"ترتيب جزئي صحيح وتحديد أحد الطرفين"},{"level":"1 درجة","description":"تحديد طرف واحد فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين موضعي الميكروويف وتحت الحمراء","الخلط بين السينية وفوق البنفسجية","عكس العلاقة بين الطول الموجي والتردد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.091Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(111, 1, 'للضوء طبيعة مزدوجة: يسلك سلوك الموجات (له طول موجي وتردد)، ويسلك سلوك الجسيمات (سيل من الفوتونات).', '["الطبيعة الموجية وحدها لم تفسر ظواهر مثل التأثير الكهروضوئي.","","الطبيعة الجسيمية وحدها لا تفسر وصف الضوء بطول موجي وتردد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.093Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(112, 2, 'التأثير الكهروضوئي (انبعاث إلكترونات من سطح فلز عند سقوط ضوء بتردد معين) فُسّر بأن الضوء سيل من الفوتونات طاقة كل منها hν.', '["انتقال الضوء بسرعة c يفسره النموذج الموجي.","تحلل الضوء بالمنشور يفسر باختلاف الأطوال الموجية للألوان (سلوك موجي).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.093Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(113, 0, 'اقترح أينشتاين أن للضوء طبيعة مزدوجة، وأن شعاع الضوء سيل من الفوتونات، وفسّر بذلك التأثير الكهروضوئي.', '["","بلانك افترض تكميم الطاقة لكنه لم يفسر التأثير الكهروضوئي بالفوتونات.","بور وضع نموذجًا لذرة الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.093Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(114, 2, 'الضوء الأحمر عالي الشدة لم يحرر إلكترونات، بينما حررها الأخضر والبنفسجي رغم شدتهما المنخفضة؛ فالانبعاث يعتمد على التردد (طاقة الفوتون الواحد hν) لا على الشدة، وهذا دليل على الطبيعة الجسيمية.', '["الجدول لا يتضمن الزمن، ووفق تفسير الفوتونات لا يحرر الأحمر إلكترونات مهما طال الزمن.","الأحمر الأعلى شدة لم يحرر إلكترونات، فالشدة ليست العامل الحاسم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.094Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(115, 1, 'وصف الضوء بطول موجي وتردد (c = λν) سلوك موجي، أما التأثير الكهروضوئي والفوتونات فتعبر عن الطبيعة الجسيمية.', '["التأثير الكهروضوئي دليل على الطبيعة الجسيمية.","","الفوتونات تمثل الطبيعة الجسيمية للضوء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.094Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(116, 0, 'الفوتون جسيم بلا كتلة يحمل كمًا من الطاقة، فوصف الضوء بالفوتونات وصف لطبيعته الجسيمية.', '["","الطبيعة الموجية تُوصف بالطول الموجي والتردد والسعة.","الضوء ليس موجة ميكانيكية؛ فهو لا يحتاج إلى وسط مادي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.094Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(117, 0, 'الطبيعة المزدوجة تعني أن الضوء يُفسَّر بعض سلوكه بالنموذج الموجي (الطول الموجي والتردد) وبعضه بالنموذج الجسيمي (الفوتونات)، ولا يكتسب كتلة.', '["","الفوتون جسيم لا كتلة له، والضوء لا يتحول إلى مادة ذات كتلة.","الضوء لا يتكون من موجات صوتية ولا جسيمات مشحونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.094Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(118, null, null, null, 'الطبيعة المزدوجة: للضوء سلوك موجي وسلوك جسيمي (مادي). الطبيعة الموجية: يوصف الضوء بطول موجي وتردد وسعة، ويرتبطان بالعلاقة c = λν، ويتحلل الضوء الأبيض بالمنشور إلى ألوان مختلفة الأطوال الموجية. الطبيعة الجسيمية: الضوء سيل من الفوتونات طاقة كل منها E = hν، والدليل التأثير الكهروضوئي (انبعاث إلكترونات من سطح فلز عند سقوط ضوء بتردد معين).', '["تعريف الطبيعة المزدوجة","مظهر موجي (طول موجي/تردد، c = λν)","مظهر جسيمي: الفوتونات E = hν","التأثير الكهروضوئي دليلًا"]'::jsonb, '[]'::jsonb, '[{"element":"توضيح المقصود","marks":1},{"element":"دليل الطبيعة الموجية","marks":1},{"element":"دليل الطبيعة الجسيمية","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"توضيح ودليلان صحيحان"},{"level":"3 درجات","description":"توضيح ودليل جسيمي صحيح مع دليل موجي ناقص"},{"level":"2 درجتان","description":"توضيح مع دليل واحد"},{"level":"1 درجة","description":"ذكر أن للضوء طبيعتين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عد التأثير الكهروضوئي دليلًا على الطبيعة الموجية","القول إن الفوتون له كتلة","عدم ذكر أي دليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.095Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(119, null, null, null, '(أ) وفق النموذج الموجي تتراكم طاقة الضوء باستمرار بزيادة شدته أو زمن سقوطه، فكان المتوقع أن يحرر الضوء الأحمر الشديد إلكترونات في النهاية، وهذا لم يحدث. (ب) الضوء سيل من الفوتونات، وطاقة الفوتون الواحد E = hν تعتمد على التردد. لا يتحرر الإلكترون إلا إذا امتلك الفوتون الساقط حدًا أدنى من الطاقة (ترددًا أدنى). فوتون البنفسجي ذو التردد الأعلى يحمل طاقة كافية، أما فوتون الأحمر فطاقته أقل من اللازم مهما زادت شدة الضوء (عدد الفوتونات).', '["النموذج الموجي يتوقع تراكم الطاقة مع الشدة والزمن","الضوء فوتونات","طاقة الفوتون E = hν تعتمد على التردد","حد أدنى من الطاقة لتحرير الإلكترون","الشدة تعني عدد الفوتونات لا طاقة الواحد"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) سبب عجز النموذج الموجي","marks":2},{"element":"(ب) التفسير بالفوتونات وطاقة الفوتون","marks":2},{"element":"(ب) دور التردد مقابل الشدة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للجزأين"},{"level":"3–4 درجات","description":"تفسير صحيح للجزء (ب) مع نقص في (أ)"},{"level":"1–2 درجة","description":"إشارة إلى الفوتونات دون ربط بالتردد"},{"level":"صفر","description":"لا إجابة أو تفسير خاطئ"}]'::jsonb, '["تفسير الانبعاث بشدة الضوء","الاعتقاد بأن الضوء الأحمر أعلى طاقة لارتباطه بالحرارة","عدم التمييز بين طاقة الفوتون الواحد والطاقة الكلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.095Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(120, null, null, null, '(أ) ν = c ÷ λ = 3.00×10⁸ ÷ 5.00×10⁻⁷ = 6.00×10¹⁴ s⁻¹. (ب) E = hν = 6.626×10⁻³⁴ × 6.00×10¹⁴ = 3.98×10⁻¹⁹ J. (ج) استخدمنا خصائص موجية (الطول الموجي والتردد) لحساب التردد، ثم استخدمنا التردد لحساب طاقة الجسيم (الفوتون)؛ فالتردد يربط الوصف الموجي بالوصف الجسيمي للضوء نفسه.', '["ν = c ÷ λ","ν = 6.00×10¹⁴ s⁻¹","E = hν","E = 3.98×10⁻¹⁹ J","الربط بين الطبيعتين عبر التردد"]'::jsonb, '["ν = 3.00×10⁸ ÷ 5.00×10⁻⁷ = 6.00×10¹⁴ s⁻¹","E = 6.626×10⁻³⁴ × 6.00×10¹⁴ = 3.98×10⁻¹⁹ J"]'::jsonb, '[{"element":"(أ) حساب التردد","marks":2},{"element":"(ب) حساب طاقة الفوتون","marks":2},{"element":"(ج) الربط بين الطبيعتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان وربط واضح"},{"level":"3–4 درجات","description":"حسابان صحيحان مع ربط ناقص"},{"level":"1–2 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["التعويض بالطول الموجي مباشرة في E = hν","ضرب c في λ","إهمال الأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.095Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(121, 1, 'E = hν وh ثابت، فطاقة الكم تتناسب طرديًا مع التردد.', '["العلاقة العكسية هي بين الطاقة والطول الموجي، لا بين الطاقة والتردد.","","الطاقة تعتمد على التردد مباشرة وفق E = hν."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-11T11:15:01.098Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(122, 2, 'ثابت بلانك h = 6.626×10⁻³⁴ J·s (جول × ثانية).', '["الوحدة خاطئة؛ ثابت بلانك بوحدة J·s لا J/s.","3.00×10⁸ قيمة سرعة الضوء بوحدة m/s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.098Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(123, 0, 'E = hν طردية خطية، فإذا قل التردد إلى الثلث قلت طاقة الكم إلى الثلث.', '["","هذا يحدث لو كانت العلاقة عكسية.","العلاقة خطية من الدرجة الأولى، لا تربيعية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.099Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(124, 2, 'E = hν معادلة خط مستقيم يمر بنقطة الأصل، ميله ثابت بلانك h.', '["المنحنى المتناقص يمثل علاقة عكسية كالعلاقة بين التردد والطول الموجي.","الخط الأفقي يعني أن الطاقة لا تتغير بتغير التردد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.099Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(125, 1, 'تردد (ب) ثلاثة أمثال تردد (أ)، والطاقة طردية مع التردد، فطاقة (ب) نحو ثلاثة أمثال طاقة (أ). وبالحساب المباشر: E = hν = 6.626×10⁻³⁴ × 6.00×10¹⁴ = 3.98×10⁻¹⁹ J.', '["هذه طاقة فوتون (أ)؛ الطاقة تتغير بتغير التردد.","","ناتج قسمة طاقة (أ) على 3، أي عكس العلاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.099Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(126, 1, 'ν = E ÷ h = (3.20×10⁻¹⁹ J) ÷ (6.626×10⁻³⁴ J·s) = 4.83×10¹⁴ s⁻¹.', '["ناتج ضرب E في h بدل القسمة.","","ناتج قسمة h على E (عكس العلاقة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.100Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(127, 0, 'الطول الموجي الأقصر (400 nm) يقابله تردد أكبر، وبما أن E = hν فطاقة الفوتون الأول أكبر.', '["","الطول الموجي الأكبر يعني ترددًا أقل وطاقة أقل.","تساوي السرعة لا يعني تساوي الطاقة؛ فالطاقة تعتمد على التردد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T11:15:01.100Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(128, null, null, null, 'العلاقة: E = hν؛ E طاقة الكم (الفوتون) بالجول J، وh ثابت بلانك 6.626×10⁻³⁴ J·s، وν التردد بوحدة s⁻¹ (Hz). العلاقة طردية: كلما زاد التردد زادت طاقة الفوتون. وبما أن ν = c/λ فإن E = hc/λ، أي أن طاقة الفوتون تقل بزيادة الطول الموجي (علاقة عكسية مع الطول الموجي).', '["E = hν","تعريف الرموز والوحدات وقيمة h","العلاقة طردية مع التردد","عكسية مع الطول الموجي (E = hc/λ)"]'::jsonb, '[]'::jsonb, '[{"element":"العلاقة","marks":1},{"element":"الرموز والوحدات","marks":1},{"element":"نوع العلاقة مع التردد","marks":1},{"element":"أثر الطول الموجي مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"العلاقة ونوعها فقط"},{"level":"1 درجة","description":"العلاقة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة E = h/ν","القول إن الطاقة تزداد بزيادة الطول الموجي","الخطأ في وحدة ثابت بلانك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-11T11:15:01.100Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(129, null, null, null, '(أ) ν(656) = 3.00×10⁸ ÷ 6.56×10⁻⁷ = 4.57×10¹⁴ s⁻¹ ؛ ν(434) = 3.00×10⁸ ÷ 4.34×10⁻⁷ = 6.91×10¹⁴ s⁻¹. (ب) E(656) = 6.626×10⁻³⁴ × 4.57×10¹⁴ = 3.03×10⁻¹⁹ J ؛ E(434) = 6.626×10⁻³⁴ × 6.91×10¹⁴ = 4.58×10⁻¹⁹ J. (ج) نسبة الطاقتين = 4.58 ÷ 3.03 = 1.51، ونسبة الترددين = 6.91 ÷ 4.57 = 1.51؛ النسبتان متساويتان، فطاقة الفوتون تتناسب طرديًا مع التردد.', '["تحويل nm إلى m","الترددان 4.57×10¹⁴ و6.91×10¹⁴ s⁻¹","الطاقتان 3.03×10⁻¹⁹ و4.58×10⁻¹⁹ J","النسبتان 1.51","الاستنتاج: تناسب طردي"]'::jsonb, '["656 nm = 6.56×10⁻⁷ m ، 434 nm = 4.34×10⁻⁷ m","ν = c ÷ λ: 4.57×10¹⁴ و6.91×10¹⁴ s⁻¹","E = hν: 3.03×10⁻¹⁹ و4.58×10⁻¹⁹ J","4.58 ÷ 3.03 = 1.51 ، 6.91 ÷ 4.57 = 1.51"]'::jsonb, '[{"element":"(أ) الترددان","marks":2},{"element":"(ب) الطاقتان","marks":2},{"element":"(ج) النسبتان والاستنتاج","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"حسابات صحيحة واستنتاج صحيح"},{"level":"4–5 درجات","description":"خطأ حسابي واحد أو استنتاج ناقص"},{"level":"2–3 درجات","description":"جزء واحد صحيح كاملًا"},{"level":"1 درجة","description":"العلاقات صحيحة دون نتائج"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان تحويل nm","استخدام λ بدل ν في E = hν","استنتاج علاقة عكسية بين الطاقة والتردد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.100Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(130, null, null, null, '(أ) E/ν = 6.63×10⁻²⁰ ÷ 1.00×10¹⁴ = 6.63×10⁻³⁴ ، 1.99×10⁻¹⁹ ÷ 3.00×10¹⁴ = 6.63×10⁻³⁴ ، 3.31×10⁻¹⁹ ÷ 5.00×10¹⁴ = 6.62×10⁻³⁴ ، 5.30×10⁻¹⁹ ÷ 8.00×10¹⁴ = 6.63×10⁻³⁴ (J·s). (ب) الناتج ثابت تقريبًا ويساوي ثابت بلانك h = 6.626×10⁻³⁴ J·s، أي أن E = hν. (ج) خط مستقيم يمر بنقطة الأصل، ميله h، يدل على علاقة طردية.', '["حساب E/ν للقيم الأربع","الناتج ثابت ≈ 6.63×10⁻³⁴ J·s","يمثل ثابت بلانك","خط مستقيم يمر بالأصل ميله h"]'::jsonb, '["6.63×10⁻²⁰ ÷ 1.00×10¹⁴ = 6.63×10⁻³⁴","1.99×10⁻¹⁹ ÷ 3.00×10¹⁴ = 6.63×10⁻³⁴","3.31×10⁻¹⁹ ÷ 5.00×10¹⁴ = 6.62×10⁻³⁴","5.30×10⁻¹⁹ ÷ 8.00×10¹⁴ = 6.63×10⁻³⁴"]'::jsonb, '[{"element":"(أ) الحسابات","marks":2},{"element":"(ب) التعرف على ثابت بلانك","marks":1},{"element":"(ج) وصف التمثيل البياني","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات وتفسير ووصف صحيح"},{"level":"3–4 درجات","description":"حسابات صحيحة مع نقص في التفسير أو الوصف"},{"level":"1–2 درجة","description":"بعض الحسابات صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قسمة التردد على الطاقة","وصف التمثيل بمنحنى متناقص","عدم ملاحظة ثبات الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.101Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(131, 0, 'طاقة الفوتون تساوي حاصل ضرب ثابت بلانك في التردد: E = hν، فهي تتناسب طرديًا مع التردد.', '["","القسمة على التردد تجعل الطاقة تقل بزيادة التردد، وهذا عكس العلاقة الصحيحة.","c × ν ليست علاقة صحيحة؛ العلاقة بين c والتردد هي c = λν."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.103Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(132, 2, '(J·s) × (s⁻¹) = J، أي أن طاقة الفوتون تقاس بالجول.', '["الهيرتز وحدة التردد وليس الطاقة.","J·s وحدة ثابت بلانك، وتختفي الثانية عند الضرب في التردد (s⁻¹).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.103Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(133, 1, 'E = hν = (6.626×10⁻³⁴ J·s)(5.00×10¹⁴ s⁻¹) = 3.31×10⁻¹⁹ J (ثلاثة أرقام معنوية).', '["ناتج قسمة التردد على ثابت بلانك (ν ÷ h) — خطأ في العلاقة.","","ناتج قسمة ثابت بلانك على التردد (h ÷ ν) — خطأ في العلاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.104Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(134, 2, 'أولًا نحسب التردد: ν = c ÷ λ = (3.00×10⁸) ÷ (4.00×10⁻⁷) = 7.50×10¹⁴ s⁻¹، ثم E = hν = (6.626×10⁻³⁴)(7.50×10¹⁴) = 4.97×10⁻¹⁹ J.', '["ناتج h ÷ λ دون استخدام سرعة الضوء.","ناتج h × λ — استُخدم الطول الموجي بدل التردد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.104Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(135, 0, 'E = hν وثابت بلانك ثابت، فالطاقة تتناسب طرديًا مع التردد؛ مضاعفة التردد تضاعف طاقة الفوتون.', '["","هذا يحدث لو كانت العلاقة عكسية، أي عند مضاعفة الطول الموجي لا التردد.","الطاقة تعتمد على التردد مباشرة فلا يمكن أن تبقى ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.104Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(136, 1, 'طاقة الفوتون تتناسب طرديًا مع التردد (E = hν)، وأعلى تردد في الجدول للأشعة فوق البنفسجية (1×10¹⁶ s⁻¹)، فطاقة فوتونها هي الأكبر.', '["ترددها أقل من الأشعة فوق البنفسجية بعشرة آلاف مرة، فطاقة فوتونها أقل.","","لها أقل تردد في الجدول، فطاقة فوتونها هي الأقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.104Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(137, 2, 'تردد الضوء البنفسجي أكبر من تردد الأحمر، وبما أن E = hν فطاقة فوتون البنفسجي أكبر. قِصر الطول الموجي يعني ترددًا أكبر لا طاقة أقل، وتساوي السرعة في الفراغ لا يعني تساوي الطاقة.', '["الطول الموجي الأقصر يقابله تردد أكبر وبالتالي طاقة أكبر، لا أقل.","جميع الموجات الكهرومغناطيسية تسير بالسرعة نفسها في الفراغ لكنها تختلف في التردد والطاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.105Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(138, null, null, null, 'المعطيات: ν = 2.45×10⁹ Hz = 2.45×10⁹ s⁻¹ ، h = 6.626×10⁻³⁴ J·s. المطلوب: E. العلاقة: E = hν. التعويض: E = (6.626×10⁻³⁴ J·s)(2.45×10⁹ s⁻¹) = 1.62×10⁻²⁴ J.', '["تحديد المعطيات والمطلوب","تحويل Hz إلى s⁻¹ أو إدراك تكافؤهما","كتابة العلاقة E = hν","التعويض الصحيح","الناتج 1.62×10⁻²⁴ J بالوحدة الصحيحة"]'::jsonb, '["كتابة المعطيات: ν = 2.45×10⁹ s⁻¹ ، h = 6.626×10⁻³⁴ J·s","كتابة العلاقة: E = hν","التعويض: E = 6.626×10⁻³⁴ × 2.45×10⁹","الناتج: E = 1.62×10⁻²⁴ J"]'::jsonb, '[{"element":"المعطيات والعلاقة","marks":1},{"element":"التعويض الصحيح","marks":1},{"element":"الناتج العددي","marks":1},{"element":"الوحدة (J) والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة وناتج صحيح 1.62×10⁻²⁴ J بالوحدة الصحيحة"},{"level":"3 درجات","description":"خطوات صحيحة مع خطأ في الوحدة أو الأرقام المعنوية"},{"level":"2 درجتان","description":"العلاقة والتعويض صحيحان مع خطأ حسابي في الأسس"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة فقط"},{"level":"صفر","description":"علاقة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على التردد بدل الضرب","خطأ في جمع الأسس: (−34) + 9 = −25 ثم تعديل المعامل 16.2 إلى 1.62 ورفع الأس إلى −24","كتابة الوحدة J·s أو Hz للطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.106Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(139, null, null, null, '(أ) ν = c ÷ λ = (3.00×10⁸ m/s) ÷ (5.20×10⁻⁷ m) = 5.77×10¹⁴ s⁻¹. (ب) E = hν = (6.626×10⁻³⁴ J·s)(5.77×10¹⁴ s⁻¹) = 3.82×10⁻¹⁹ J. (ج) أقل؛ لأن الطول الموجي للضوء الأحمر أكبر من الأخضر فتردده أقل، وبما أن E = hν فطاقة فوتونه أقل.', '["استخدام c = λν لحساب التردد","التردد 5.77×10¹⁴ s⁻¹","استخدام E = hν","الطاقة 3.82×10⁻¹⁹ J","الاستنتاج: طاقة الأحمر أقل","التعليل بالعلاقة بين الطول الموجي والتردد والطاقة"]'::jsonb, '["ν = c ÷ λ = 3.00×10⁸ ÷ 5.20×10⁻⁷ = 5.77×10¹⁴ s⁻¹","E = hν = 6.626×10⁻³⁴ × 5.77×10¹⁴ = 3.82×10⁻¹⁹ J","الأحمر: λ أكبر ← ν أصغر ← E أصغر"]'::jsonb, '[{"element":"(أ) العلاقة والتعويض والناتج","marks":2},{"element":"(ب) العلاقة والتعويض والناتج","marks":2},{"element":"(ج) الاستنتاج مع التعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأجزاء الثلاثة صحيحة بالوحدات والتعليل"},{"level":"4–5 درجات","description":"الحسابات صحيحة مع تعليل ناقص أو خطأ في وحدة"},{"level":"2–3 درجات","description":"جزء حسابي واحد صحيح أو استنتاج صحيح دون تعليل"},{"level":"1 درجة","description":"كتابة إحدى العلاقتين فقط"},{"level":"صفر","description":"لا إجابة أو علاقات خاطئة"}]'::jsonb, '["ضرب c في λ بدل القسمة","استخدام الطول الموجي مباشرة في E = hν","الاعتقاد بأن الطول الموجي الأكبر يعني طاقة أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.106Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(140, null, null, null, '(أ) الأحمر: E = (6.626×10⁻³⁴)(4.3×10¹⁴) = 2.8×10⁻¹⁹ J. البنفسجي: E = (6.626×10⁻³⁴)(7.5×10¹⁴) = 5.0×10⁻¹⁹ J. (ب) هذه ظاهرة التأثير الكهروضوئي: الضوء يتكون من فوتونات، وطاقة الفوتون تعتمد على تردده (E = hν). لا ينبعث الإلكترون إلا إذا كانت طاقة الفوتون الساقط كافية لتحريره من سطح الفلز (أي أن تردد الضوء يساوي ترددًا معينًا أو يزيد عليه). فوتون الضوء البنفسجي ذو التردد الأعلى يحمل طاقة كافية، أما فوتون الأحمر فطاقته أقل من اللازم مهما زادت شدة الضوء.', '["حساب طاقة فوتون الأحمر 2.8×10⁻¹⁹ J","حساب طاقة فوتون البنفسجي 5.0×10⁻¹⁹ J","تسمية الظاهرة: التأثير الكهروضوئي","ربط انبعاث الإلكترون بطاقة الفوتون الواحد","توضيح أن طاقة فوتون الأحمر غير كافية لتحرير الإلكترون"]'::jsonb, '["E(أحمر) = 6.626×10⁻³⁴ × 4.3×10¹⁴ = 2.8×10⁻¹⁹ J","E(بنفسجي) = 6.626×10⁻³⁴ × 7.5×10¹⁴ = 5.0×10⁻¹⁹ J","المقارنة: طاقة فوتون البنفسجي أكبر بنحو 1.7 مرة"]'::jsonb, '[{"element":"(أ) طاقة فوتون الأحمر","marks":1},{"element":"(أ) طاقة فوتون البنفسجي","marks":1},{"element":"(ب) تسمية الظاهرة","marks":1},{"element":"(ب) التفسير بطاقة الفوتون الواحد والتردد","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان وتفسير كامل يربط الانبعاث بطاقة الفوتون الواحد"},{"level":"3–4 درجات","description":"حسابان صحيحان مع تفسير ناقص، أو تفسير كامل مع خطأ حسابي"},{"level":"1–2 درجة","description":"حساب واحد صحيح أو تفسير عام دون ربط بالطاقة"},{"level":"صفر","description":"لا إجابة أو تفسير خاطئ علميًا"}]'::jsonb, '["تفسير الانبعاث بشدة الضوء بدل تردده","الاعتقاد بأن الضوء الأحمر يحمل طاقة أكبر لأنه «ساخن»","إهمال الأرقام المعنوية (المعطيات برقمين معنويين)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.107Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(141, 0, 'الفوتون جسيم لا كتلة له يحمل كمًا من الطاقة، طاقته E = hν.', '["","هذا وصف للإلكترون.","الفوتون ليس موجة ميكانيكية، والصوت لا يتكون من فوتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.108Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(142, 2, 'الفوتون جسيم عديم الكتلة يحمل كمًا من الطاقة.', '["الإلكترون جسيم له كتلة، والفوتون لا كتلة له.","مفهوم خاطئ شائع؛ الفوتون عديم الكتلة تمامًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.109Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(143, 1, 'ν = c ÷ λ = 3.00×10⁸ ÷ 0.125 = 2.40×10⁹ s⁻¹، ثم E = hν = 6.626×10⁻³⁴ × 2.40×10⁹ = 1.59×10⁻²⁴ J.', '["ناتج h ÷ λ دون استخدام سرعة الضوء.","","ناتج h × λ؛ استُخدم الطول الموجي بدل التردد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:01.109Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(144, 2, 'E = hν = 6.626×10⁻³⁴ × 2.00×10¹⁵ = 13.25×10⁻¹⁹ = 1.33×10⁻¹⁸ J (بالصيغة العلمية الصحيحة).', '["ناتج قسمة h على ν.","ناتج قسمة ν على h.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:01.109Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(145, 0, 'طاقة الفوتون الواحد E = hν تعتمد على التردد (اللون) فقط، أما زيادة الشدة فتعني زيادة عدد الفوتونات.', '["","مفهوم خاطئ شائع؛ الشدة لا تغير طاقة الفوتون الواحد.","لم يتغير اللون، فالتردد ثابت وطاقة الفوتون ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T11:15:01.109Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(146, 2, 'طاقة الفوتون تتناسب عكسيًا مع الطول الموجي (E = hc/λ)، فالفوتون الأقل طاقة (ج: 2.0×10⁻²¹ J) له أطول طول موجي.', '["طاقته أكبر من (ج) فطوله الموجي أقصر.","طاقته أكبر ما في الجدول فطوله الموجي الأقصر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.109Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(147, 1, 'E = hν وν = c ÷ λ، فبالتعويض E = hc ÷ λ.', '["ضُرب الطول الموجي بدل القسمة عليه، فتصبح الطاقة طردية مع λ.","","علاقة مقلوبة لا تعطي وحدة الجول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.110Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(148, null, null, null, 'الفوتون: جسيم لا كتلة له يحمل كمًا من الطاقة. طاقته E(الفوتون) = hν، حيث h ثابت بلانك وν التردد. اقترح أينشتاين أن الضوء سيل من الفوتونات، ولا يتحرر الإلكترون من سطح الفلز إلا إذا امتلك الفوتون الساقط حدًا أدنى من الطاقة (ترددًا أدنى معينًا)، مهما كانت شدة الضوء.', '["التعريف: جسيم لا كتلة له","يحمل كمًا من الطاقة","E = hν","الضوء سيل من الفوتونات","الحد الأدنى من طاقة الفوتون لتحرير الإلكترون"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الفوتون","marks":2},{"element":"العلاقة E = hν","marks":1},{"element":"تفسير التأثير الكهروضوئي","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة"},{"level":"3–4 درجات","description":"تعريف وعلاقة صحيحان مع تفسير ناقص"},{"level":"1–2 درجة","description":"التعريف أو العلاقة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن للفوتون كتلة صغيرة","تفسير الانبعاث بشدة الضوء","الخلط بين الفوتون والإلكترون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.110Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(149, null, null, null, 'التحويل: λ = 4.50×10² nm = 4.50×10⁻⁷ m. التردد: ν = c ÷ λ = 3.00×10⁸ ÷ 4.50×10⁻⁷ = 6.67×10¹⁴ s⁻¹. الطاقة: E = hν = 6.626×10⁻³⁴ × 6.67×10¹⁴ = 4.42×10⁻¹⁹ J. (أو مباشرة E = hc/λ = 4.42×10⁻¹⁹ J).', '["تحويل nm إلى m","ν = 6.67×10¹⁴ s⁻¹","E = hν","E = 4.42×10⁻¹⁹ J"]'::jsonb, '["λ = 4.50×10² × 10⁻⁹ = 4.50×10⁻⁷ m","ν = 3.00×10⁸ ÷ 4.50×10⁻⁷ = 6.67×10¹⁴ s⁻¹","E = 6.626×10⁻³⁴ × 6.67×10¹⁴ = 4.42×10⁻¹⁹ J"]'::jsonb, '[{"element":"تحويل الوحدة","marks":1},{"element":"حساب التردد","marks":1},{"element":"حساب الطاقة","marks":1},{"element":"الوحدة والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ في الوحدة أو الأرقام المعنوية"},{"level":"2 درجتان","description":"نسيان التحويل مع طريقة صحيحة"},{"level":"1 درجة","description":"كتابة العلاقات فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان تحويل nm إلى m فيكون الناتج 4.42×10⁻²⁸ J","التعويض بالطول الموجي في E = hν","قسمة h على ν"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.110Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(150, null, null, null, '(أ) E = hν = 6.626×10⁻³⁴ × 2×10¹⁵ = 13.252×10⁻¹⁹ J، فالقيمة صحيحة عدديًا. (ب) لا؛ لأن معامل الصيغة العلمية يجب أن يكون بين 1 و10، والصحيح 1.3252×10⁻¹⁸ J. (ج) التردد المعطى (2×10¹⁵) برقم معنوي واحد، فيُقرّب الناتج إلى رقم معنوي واحد: 1×10⁻¹⁸ J تقريبًا (ولو أُعطي التردد 2.00×10¹⁵ لكان الناتج 1.33×10⁻¹⁸ J).', '["التحقق: 13.252×10⁻¹⁹ صحيحة عدديًا","شرط المعامل بين 1 و10","الصيغة الصحيحة 1.3252×10⁻¹⁸ J","رقم معنوي واحد ← 1×10⁻¹⁸ J"]'::jsonb, '["6.626×10⁻³⁴ × 2×10¹⁵ = 13.252×10⁻¹⁹","13.252×10⁻¹⁹ = 1.3252×10⁻¹⁸ J","التقريب لرقم معنوي واحد: 1×10⁻¹⁸ J"]'::jsonb, '[{"element":"(أ) التحقق العددي","marks":1},{"element":"(ب) التصحيح إلى الصيغة العلمية","marks":2},{"element":"(ج) الأرقام المعنوية مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"3–4 درجات","description":"التحقق والتصحيح صحيحان مع خلل في الأرقام المعنوية"},{"level":"1–2 درجة","description":"التحقق العددي فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تحريك الفاصلة دون تعديل الأس","كتابة 1.3252×10⁻²⁰","تجاهل الأرقام المعنوية للمعطيات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.111Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(151, 0, 'طيف الانبعاث الذري لعنصر هو مجموعة ترددات الموجات الكهرومغناطيسية المنبعثة من ذرات ذلك العنصر.', '["","هذا وصف للطيف المستمر للضوء الأبيض.","هذه طاقة التأين ولا علاقة لها بتعريف الطيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.113Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(152, 1, 'يتكون طيف الانبعاث الذري من خطوط ملونة منفصلة لكل منها تردد محدد، ولذلك يسمى طيفًا خطيًا.', '["الحزمة المتصلة وصف للطيف المستمر.","","لكل عنصر طيف مميز يختلف عن غيره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.113Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(153, 2, 'تمتص الذرات طاقة (بالتسخين أو التفريغ الكهربائي) فتصبح مثارة، ثم تفقد الطاقة الزائدة على شكل ضوء بترددات محددة.', '["التبريد لا يثير الذرات ولا يجعلها تبعث طيفها.","الطيف الذري لا ينتج عن تفكك النواة، بل عن تغير طاقة الإلكترونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.113Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(154, 1, 'لكل عنصر طيف انبعاث خطي مميز لا يتكرر في عنصر آخر، فيستخدم كبصمة الإصبع للتعرف عليه.', '["لو تشابهت الخطوط لما أمكن التمييز بين العناصر.","","الطيف يدل على هوية العنصر لا على كتلته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.113Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(155, 2, 'حسب الجدول، مركبات الصوديوم تعطي اللهب لونًا أصفر، فالعنصر المرجح هو الصوديوم.', '["مركبات الليثيوم تعطي لونًا أحمر.","مركبات البوتاسيوم تعطي لونًا بنفسجيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T11:15:01.114Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(156, 1, 'الخطوط المرئية لطيف الهيدروجين أربعة: 410 و434 و486 و656 nm، و589 nm ليس منها.', '["410 nm أحد الخطوط الأربعة المرئية للهيدروجين.","","656 nm أحد الخطوط الأربعة المرئية للهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.114Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(157, 0, 'طيف الضوء الأبيض مستمر يضم جميع ترددات الضوء المرئي دون فجوات، أما طيف انبعاث الهيدروجين فخطي يضم ترددات محددة فقط.', '["","عكس للصحيح؛ الأبيض مستمر والهيدروجين خطي.","الفرق جوهري في طبيعة الطيف (مستمر/خطي) لا في الشدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.114Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(158, null, null, null, 'طيف الانبعاث الذري: مجموعة ترددات الموجات الكهرومغناطيسية المنبعثة من ذرات العنصر. ينتج عندما تمتص الذرات طاقة بالتسخين أو التفريغ الكهربائي فتصبح مثارة، ثم تفقد الطاقة الزائدة على شكل ضوء. يسمى خطيًا لأنه عند إمرار هذا الضوء في منشور لا يظهر طيف متصل، بل خطوط ملونة منفصلة لكل منها تردد محدد.', '["التعريف","امتصاص الطاقة والإثارة","فقد الطاقة الزائدة على شكل ضوء","خطوط منفصلة بترددات محددة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"آلية النشوء","marks":2},{"element":"سبب التسمية بالخطي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"التعريف وسبب التسمية فقط"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["وصف طيف الانبعاث بأنه مستمر","القول إن الذرة تبعث الضوء عند امتصاص الطاقة لا عند فقدها","الخلط مع الطيف الكهرومغناطيسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.115Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(159, null, null, null, 'شكل الطيف: الضوء الأبيض طيف مستمر (ألوان متدرجة دون فجوات)، والهيدروجين طيف خطي (خطوط ملونة منفصلة). الترددات: الأبيض يحوي جميع ترددات الضوء المرئي، والهيدروجين ترددات محددة فقط (في المرئي أربعة خطوط: 410، 434، 486، 656 nm). التعرف على العناصر: الطيف المستمر لا يميز عنصرًا، أما طيف الانبعاث الخطي فمميز لكل عنصر كبصمة الإصبع فيستخدم للتعرف عليه.', '["مستمر مقابل خطي","جميع الترددات مقابل ترددات محددة","الخطوط الأربعة للهيدروجين","الخطي يستخدم للتعرف على العناصر"]'::jsonb, '[]'::jsonb, '[{"element":"شكل الطيف","marks":2},{"element":"الترددات","marks":2},{"element":"الاستخدام في التعرف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المقارنة كاملة في الجوانب الثلاثة"},{"level":"3–4 درجات","description":"جانبان صحيحان"},{"level":"1–2 درجة","description":"جانب واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس الطيفين","القول إن الطيف المستمر يميز العناصر","ذكر أطوال موجية خاطئة للهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.116Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(160, null, null, null, 'العينة تحتوي على الهيدروجين لظهور خطوطه الأربعة جميعًا (410، 434، 486، 656 nm)، وعلى الصوديوم لظهور خطه 589 nm. لا تحتوي على الليثيوم لعدم ظهور خطه 671 nm. والتعليل أن لكل عنصر طيف انبعاث خطي مميز كبصمة الإصبع، فظهور جميع خطوط عنصر في الطيف دليل على وجوده.', '["الهيدروجين موجود (خطوطه الأربعة)","الصوديوم موجود (589 nm)","الليثيوم غير موجود (غياب 671 nm)","التعليل بأن لكل عنصر طيفًا مميزًا"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الهيدروجين","marks":1},{"element":"تحديد الصوديوم","marks":1},{"element":"استبعاد الليثيوم","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للعناصر مع التعليل"},{"level":"3–4 درجات","description":"تحديد صحيح دون تعليل كافٍ"},{"level":"1–2 درجة","description":"تحديد عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الاكتفاء بخط واحد للحكم على الهيدروجين","عد 589 nm خطًا من خطوط الهيدروجين","استنتاج وجود الليثيوم دون خطه المميز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.116Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(161, 1, 'يتوهج الحديد أولًا باللون الأحمر الداكن، ثم البرتقالي المصفر، ثم الأبيض المائل للزرقة عند درجات الحرارة العالية جدًا.', '["هذا الترتيب معكوس (يمثل التبريد لا التسخين).","","الأحمر الداكن يظهر أولًا عند أقل درجة توهج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.118Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(162, 2, 'الجسم الأسخن يمتلك طاقة أكبر فيبعث إشعاعًا أعلى ترددًا (أقصر طولًا موجيًا)، فيتحول لونه من الأحمر نحو الأزرق.', '["نقص التردد يعني الاتجاه نحو الأحمر، وهذا يحدث عند التبريد.","تغير اللون دليل على تغير التردد الغالب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.118Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(163, 0, 'ارتفاع درجة الحرارة يزيد طاقة الجسم فيبعث إشعاعًا بتردد أعلى، وبما أن طاقة الإشعاع تزداد بزيادة التردد ينتقل اللون من الأحمر (تردد منخفض) نحو الأزرق (تردد مرتفع).', '["","الطول الموجي الغالب يقصر لا يزداد عند التسخين.","سرعة الضوء ثابتة في الفراغ ولا تعتمد على حرارة المصدر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.118Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(164, 0, 'عجز النموذج الموجي للضوء عن تفسير الظاهرة، ففسرها بلانك بافتراض تكميم الطاقة (E = hν).', '["","فرضية بلانك هي التي فسّرت الظاهرة.","هذه العلاقة جزء من تفسير بلانك الناجح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.119Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(165, 1, 'اللون الأبيض المزرق يدل على أعلى درجة حرارة؛ لأنه يعني انبعاث إشعاع بأعلى تردد وطاقة.', '["الأحمر الداكن يدل على أقل درجة حرارة بين القطع الثلاث.","","البرتقالي المصفر يدل على حرارة متوسطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.119Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(166, 1, 'اللون البرتقالي المصفر أعلى ترددًا من الأحمر، فالقطعة البرتقالية تبعث إشعاعًا أعلى طاقة، أي أنها أسخن.', '["مفهوم خاطئ شائع؛ الأحمر يدل على أقل درجات التوهج.","","اختلاف اللون يدل على اختلاف درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.119Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(167, 2, 'افترض بلانك أن المادة لا تكتسب الطاقة أو تفقدها بصورة متصلة، بل على شكل كمات طاقة كل منها E = hν.', '["هذه فكرة قديمة لا علاقة لها بتفسير بلانك.","هذا من فرضيات نموذج بور للذرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.119Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(168, null, null, null, 'الوصف: تتوهج أولًا باللون الأحمر الداكن، ثم البرتقالي المصفر، ثم الأبيض المائل للزرقة عند درجات الحرارة العالية جدًا. التفسير: كلما ارتفعت درجة الحرارة امتلك الجسم طاقة أكبر فيبعث إشعاعًا أعلى ترددًا (أقصر طولًا موجيًا)، وبما أن طاقة الإشعاع تزداد بزيادة التردد (E = hν) ينتقل اللون من الأحمر (تردد منخفض) نحو الأزرق (تردد مرتفع).', '["تسلسل الألوان الصحيح","زيادة الحرارة تزيد الطاقة","إشعاع أعلى ترددًا","E = hν والربط بين التردد واللون"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تسلسل الألوان","marks":2},{"element":"التفسير بالتردد والطاقة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"وصف وتفسير كاملان"},{"level":"2–3 درجات","description":"وصف صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"وصف ناقص دون تفسير"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس تسلسل الألوان","القول إن الطول الموجي يزداد بالتسخين","الاعتقاد بأن الأحمر يدل على أعلى حرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.120Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(169, null, null, null, 'النموذج الموجي يعامل الطاقة على أنها تُكتسب وتُفقد بصورة متصلة بأي مقدار، ولم يستطع تفسير توزع الألوان المنبعثة من الأجسام الساخنة وتغيرها مع الحرارة. افترض بلانك أن المادة تكتسب الطاقة أو تفقدها على شكل كمات محددة فقط، طاقة كل منها E = hν، أي بأعداد صحيحة من الكمات. أهميتها: أسست لمفهوم تكميم الطاقة الذي فسّر الظاهرة، وبُني عليه لاحقًا تفسير التأثير الكهروضوئي ونموذج بور.', '["النموذج الموجي يفترض اتصال الطاقة","عجزه عن تفسير الظاهرة","فرضية بلانك: كمات E = hν","أعداد صحيحة من الكمات","أهمية الفرضية (تكميم الطاقة)"]'::jsonb, '[]'::jsonb, '[{"element":"سبب عجز النموذج الموجي","marks":2},{"element":"فرضية بلانك","marks":2},{"element":"أهمية الفرضية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة"},{"level":"3–4 درجات","description":"فرضية صحيحة مع نقص في سبب العجز أو الأهمية"},{"level":"1–2 درجة","description":"ذكر بلانك والتكميم بشكل عام"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسبة الفرضية إلى بور أو أينشتاين","القول إن الطاقة تُكتسب بأي مقدار","عدم ذكر العلاقة E = hν"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.120Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(170, null, null, null, '(أ) الأحمر: E = hc/λ = (6.626×10⁻³⁴ × 3.00×10⁸) ÷ 7.00×10⁻⁷ = 2.84×10⁻¹⁹ J. الأزرق: E = (6.626×10⁻³⁴ × 3.00×10⁸) ÷ 4.50×10⁻⁷ = 4.42×10⁻¹⁹ J. (ب) فوتون الضوء الأزرق أعلى طاقة (نحو 1.56 مرة)، والجسم الأسخن يمتلك طاقة أكبر فيبعث فوتونات أعلى طاقة وترددًا، لذا يتحول لونه من الأحمر نحو الأزرق بارتفاع حرارته.', '["E = hc/λ أو حساب ν أولًا","E(أحمر) = 2.84×10⁻¹⁹ J","E(أزرق) = 4.42×10⁻¹⁹ J","الربط: الأسخن يبعث فوتونات أعلى طاقة"]'::jsonb, '["ν(أحمر) = 3.00×10⁸ ÷ 7.00×10⁻⁷ = 4.29×10¹⁴ s⁻¹ ، E = 2.84×10⁻¹⁹ J","ν(أزرق) = 3.00×10⁸ ÷ 4.50×10⁻⁷ = 6.67×10¹⁴ s⁻¹ ، E = 4.42×10⁻¹⁹ J","4.42 ÷ 2.84 ≈ 1.56"]'::jsonb, '[{"element":"(أ) طاقة الفوتون الأحمر","marks":1},{"element":"(أ) طاقة الفوتون الأزرق","marks":1},{"element":"(ب) التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وتفسير مترابط"},{"level":"3 درجات","description":"حسابان صحيحان مع تفسير ناقص"},{"level":"2 درجتان","description":"حساب واحد صحيح مع تفسير"},{"level":"1 درجة","description":"علاقة صحيحة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["التعويض بالطول الموجي في E = hν","استنتاج أن الأحمر أعلى طاقة","أخطاء في الأسس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.120Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(171, 1, 'حالة الاستقرار هي أقل حالة طاقة مسموح بها للذرة، ويكون فيها الإلكترون في أقل مستوى طاقة، ولا تشع الذرة طاقة.', '["أعلى الحالات طاقة حالات إثارة غير مستقرة.","","الذرة في حالة الاستقرار لا تشع طاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.122Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(172, 2, 'حالة الاستقرار لذرة الهيدروجين يكون فيها الإلكترون في المستوى الأول n = 1، وهو أقل المستويات طاقة وأقربها إلى النواة.', '["n = 2 مستوى أعلى طاقة، ووجود الإلكترون فيه يعني أن الذرة مثارة.","n = 7 أعلى المستويات طاقة وأبعدها عن النواة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.122Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(173, 0, 'افترض بور أن الإلكترون يتحرك في مداره المحدد حركة دائرية دون أن يفقد طاقة، فالذرة في حالة الاستقرار لا تشع طاقة.', '["","هذا ما توقعته الفيزياء التقليدية، ورفضه بور.","الذرة لا تمتص طاقة إلا إذا زُوّدت بها بمقدار مناسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(174, 0, 'الذرة (ب) إلكترونها في n = 1 وهو أقل مستوى طاقة، فهي في حالة الاستقرار، أما (أ) و(ج) فمثارتان.', '["","إلكترونها في n = 3 فهي مثارة.","إلكترونها في n = 2 فهي مثارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(175, 1, 'لا تغادر الذرة حالة الاستقرار إلا إذا امتصت طاقة تساوي الفرق بين مستوى الاستقرار ومستوى أعلى، فينتقل الإلكترون إلى ذلك المستوى.', '["الذرة في حالة الاستقرار لا يوجد مستوى أقل تنتقل إليه لتبعث فوتونًا.","","الإلكترون في n = 1 في أقرب مستوى إلى النواة، ولا يوجد مستوى أقرب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(176, 1, 'طاقة المستوى تزداد بالبعد عن النواة، فالإلكترون في حالة الاستقرار يشغل أقرب مستوى إلى النواة (n = 1) وأقلها طاقة.', '["أبعد المستويات أعلاها طاقة، وهذا ينافي حالة الاستقرار.","","الانتقال إلى مستوى أعلى يتطلب امتصاص طاقة محددة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(177, 2, 'انبعاث الفوتون يتطلب انتقال الإلكترون من مستوى أعلى إلى أدنى، والإلكترون في حالة الاستقرار في أدنى مستوى، فلا يمكن أن تبعث الذرة فوتونًا.', '["وفق بور لا تشع الذرة وهي في حالة الاستقرار.","لا يوجد مستوى n = 0؛ فأدنى مستوى هو n = 1.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.124Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(178, null, null, null, 'حالة الاستقرار: أقل حالة طاقة مسموح بها للذرة. في ذرة الهيدروجين يكون الإلكترون في المستوى الأول n = 1 (أقرب المستويات إلى النواة وأقلها طاقة). ووفق بور يتحرك الإلكترون في مداره حركة دائرية دون أن يفقد طاقة، فلا تشع الذرة طاقة وهي في حالة الاستقرار.', '["أقل حالة طاقة مسموح بها","الإلكترون في n = 1","أقرب مستوى إلى النواة","لا تشع الذرة طاقة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف حالة الاستقرار","marks":2},{"element":"موقع الإلكترون n = 1","marks":1},{"element":"عدم إشعاع الطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"التعريف فقط"},{"level":"1 درجة","description":"عبارة عامة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الذرة تشع باستمرار","وضع الإلكترون في أبعد مستوى","الخلط بين حالة الاستقرار وحالة الإثارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.125Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(179, null, null, null, '(أ) الامتصاص يعني انتقال الإلكترون من n = 1 إلى مستوى أعلى وهذا ممكن، أما الانبعاث فيتطلب انتقال الإلكترون إلى مستوى أدنى، ولا يوجد مستوى أدنى من n = 1، فلا تبعث الذرة فوتونًا وهي في حالة الاستقرار. (ب) لأن مستويات الطاقة محددة (مكمّاة)، فلا يمتص الإلكترون إلا طاقة تساوي تمامًا الفرق بين مستواه ومستوى أعلى مسموح به.', '["الامتصاص: انتقال إلى مستوى أعلى ممكن","الانبعاث يتطلب مستوى أدنى غير موجود","مستويات الطاقة محددة","الطاقة الممتصة = فرق الطاقة بين مستويين"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تعليل إمكان الامتصاص","marks":1},{"element":"(أ) تعليل عدم الانبعاث","marks":2},{"element":"(ب) التعليل بتكميم المستويات","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعليلان كاملان"},{"level":"3–4 درجات","description":"تعليل كامل وآخر ناقص"},{"level":"1–2 درجة","description":"تعليل واحد ناقص"},{"level":"صفر","description":"لا إجابة أو تعليل خاطئ"}]'::jsonb, '["افتراض وجود مستوى n = 0","القول إن الذرة تمتص أي مقدار من الطاقة","الخلط بين الامتصاص والانبعاث"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.125Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(180, null, null, null, 'الذرة في حالة الاستقرار في المرحلتين (1) و(4) لأن الإلكترون في n = 1 أقل مستوى طاقة؛ وفي (2) و(3) تكون مثارة. الانتقال 1 → 3: امتصاص طاقة لأن الإلكترون انتقل إلى مستوى أعلى. الانتقال 3 → 2: انبعاث فوتون لأن الإلكترون انتقل إلى مستوى أدنى. الانتقال 2 → 1: انبعاث فوتون وعودة الذرة إلى حالة الاستقرار.', '["حالة الاستقرار في (1) و(4)","1 → 3 امتصاص","3 → 2 انبعاث","2 → 1 انبعاث وعودة للاستقرار","التعليل بالانتقال لأعلى/لأدنى"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد مراحل الاستقرار","marks":2},{"element":"تحديد نوع كل انتقال","marks":2},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح كامل مع التعليل"},{"level":"3–4 درجات","description":"خطأ واحد أو تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد مراحل الاستقرار فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عد المرحلة (3) حالة استقرار لأن الإلكترون في مستوى أقل من (2)","الخلط بين الامتصاص والانبعاث","عدم ربط الاستقرار بالمستوى n = 1"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.125Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(181, 0, 'حالة الإثارة: الحالة التي تكتسب فيها الذرة طاقة فتصبح طاقتها أعلى من طاقة حالة الاستقرار، وينتقل إلكترونها إلى مستوى أعلى.', '["","هذا تعريف حالة الاستقرار.","فقد الإلكترونات تأين لا إثارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.128Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(182, 1, 'تمتص الذرة طاقة (بالتسخين أو التفريغ الكهربائي مثلًا) فينتقل الإلكترون إلى مستوى طاقة أعلى وتصبح مثارة.', '["بعث الفوتون يحدث عند عودة الذرة إلى مستوى أدنى، لا عند إثارتها.","","الانتقال إلى مستوى أقرب للنواة يعني فقد طاقة لا إثارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.128Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(183, 0, 'حالة الاستقرار لذرة الهيدروجين n = 1، فوجود الإلكترون في n = 4 يعني أن الذرة مثارة.', '["","حالة الاستقرار تكون والإلكترون في n = 1.","في التأين يُنزع الإلكترون من الذرة كليًا، وهنا ما زال في مستوى n = 4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.128Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(184, 1, 'عند انتقال الإلكترون من مستوى أعلى إلى أدنى تفقد الذرة طاقة على شكل فوتون طاقته تساوي فرق الطاقة بين المستويين، فينتج طيف الانبعاث.', '["العودة إلى مستوى أقل تعني فقد طاقة لا امتصاصها.","","الإلكترون يبقى في الذرة وينتقل إلى مستوى أدنى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.128Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(185, 2, 'الانتقال من n = 1 (حالة الاستقرار) إلى n = 3 يتطلب امتصاص طاقة، فتصبح الذرة مثارة.', '["انتقال من مستوى أعلى إلى أدنى بين حالتي إثارة، يصاحبه انبعاث فوتون.","انتقال من n = 3 إلى n = 1 يعيد الذرة إلى حالة الاستقرار مع انبعاث فوتون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.129Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(186, 0, 'امتصاص الذرات لطاقات محددة لتصبح مثارة ينتج طيف امتصاص خطي (خطوط معتمة عند الترددات الممتصة).', '["","الانبعاث يحدث عند العودة إلى مستويات أدنى، وطيف الذرات خطي لا مستمر.","الذرات تمتص ترددات محددة فتظهر خطوط في الطيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.129Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(187, 1, 'الذرة المثارة طاقتها أعلى من طاقة حالة الاستقرار، وهي غير مستقرة فتميل إلى العودة لمستوى أدنى بانبعاث فوتون.', '["الذرة المثارة امتصت طاقة فطاقتها أعلى.","","الإثارة تعني اكتساب طاقة إضافية فالطاقتان مختلفتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.129Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(188, null, null, null, 'حالة الإثارة: الحالة التي تكون فيها طاقة الذرة أعلى من طاقة حالة الاستقرار. تصل إليها الذرة عندما تمتص طاقة (بالتسخين أو التفريغ الكهربائي أو الضوء) فينتقل إلكترونها إلى مستوى طاقة أعلى. وعند خروجها منها ينتقل الإلكترون إلى مستوى أدنى وتبعث الذرة فوتونًا طاقته تساوي فرق الطاقة بين المستويين.', '["تعريف حالة الإثارة","الوصول إليها بامتصاص طاقة","انتقال الإلكترون لمستوى أعلى","الخروج منها بانبعاث فوتون = فرق الطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"كيفية الوصول","marks":1},{"element":"ما يحدث عند الخروج","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص في عنصر"},{"level":"2 درجتان","description":"التعريف وطريقة الوصول فقط"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الذرة المثارة تبعث فوتونًا عند صعود الإلكترون","الخلط بين الإثارة والتأين","عدم ربط طاقة الفوتون بفرق المستويين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.129Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(189, null, null, null, 'طاقة الذرة: الاستقرار أقل طاقة مسموح بها، والإثارة أعلى منها. المستوى: في الاستقرار n = 1، وفي الإثارة n ≥ 2. الاستقرار: حالة الاستقرار مستقرة، وحالة الإثارة غير مستقرة. بعث الفوتون: الذرة في حالة الاستقرار لا تشع، أما المثارة فتبعث فوتونًا عند عودة الإلكترون إلى مستوى أدنى.', '["الطاقة","المستوى n = 1 مقابل n ≥ 2","الاستقرار","بعث الفوتون"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في الطاقة","marks":1},{"element":"المقارنة في المستوى","marks":1},{"element":"المقارنة في الاستقرار","marks":1},{"element":"المقارنة في بعث الفوتون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المقارنة كاملة"},{"level":"3 درجات","description":"ثلاثة جوانب صحيحة"},{"level":"2 درجتان","description":"جانبان صحيحان"},{"level":"1 درجة","description":"جانب واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الذرة المستقرة تشع","تحديد مستوى الإثارة بـ n = 2 فقط","عكس الطاقة بين الحالتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.129Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(190, null, null, null, 'حرارة اللهب تمد ذرات الصوديوم بالطاقة، فتمتص الذرات هذه الطاقة وينتقل بعض إلكتروناتها إلى مستويات طاقة أعلى فتصبح مثارة. الذرة المثارة غير مستقرة، فتعود إلكتروناتها إلى مستويات أدنى (نحو حالة الاستقرار) وتبعث الطاقة الزائدة على شكل فوتونات طاقتها تساوي فرق الطاقة بين المستويات، وتقع ترددات هذه الفوتونات في منطقة اللون الأصفر.', '["اللهب يمد الذرات بالطاقة","امتصاص الطاقة والانتقال لمستوى أعلى (إثارة)","عدم استقرار الحالة المثارة","العودة وبعث فوتونات = فرق الطاقة","تردد الفوتونات يقابل اللون الأصفر"]'::jsonb, '[]'::jsonb, '[{"element":"الإثارة بامتصاص طاقة اللهب","marks":2},{"element":"العودة وانبعاث الفوتونات","marks":2},{"element":"ربط اللون بطاقة الفوتونات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل مترابط"},{"level":"3–4 درجات","description":"تفسير صحيح مع نقص في الربط باللون"},{"level":"1–2 درجة","description":"ذكر الإثارة أو الانبعاث فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن اللون ينتج أثناء امتصاص الطاقة","تفسير اللون بلون اللهب نفسه","عدم ذكر عودة الإلكترون إلى مستوى أدنى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.130Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(191, 0, 'نجح نموذج بور في تفسير طيف الهيدروجين، لكنه عجز عن تفسير أطياف العناصر الأعقد (التي تحتوي على أكثر من إلكترون).', '["","تفسير طيف الهيدروجين من نجاحات النموذج لا عيوبه.","تكميم طاقة الإلكترون فكرة صحيحة أقرها النموذج الكمي أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-11T11:15:01.132Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(192, 2, 'تفسير خطوط طيف الهيدروجين نجاح لنموذج بور، أما إهمال الخاصية الموجية وافتراض المسار الدائري المستوي فمن عيوبه.', '["إهمال الخاصية الموجية للإلكترون من عيوب النموذج.","افتراض المسار الدائري المستوي (الذرة المسطحة) من عيوبه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-11T11:15:01.132Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(193, 1, 'مبدأ هايزنبرج للشك ينص على استحالة تحديد سرعة الإلكترون ومكانه معًا بدقة في الوقت نفسه، وهذا يتعارض مع افتراض بور.', '["مبدأ أوفباو يتعلق بترتيب ملء المستويات بالإلكترونات.","","قاعدة هوند تتعلق بتوزيع الإلكترونات في المجالات المتساوية الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.132Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(194, 0, 'اقترح دي برولي أن الإلكترون يتحرك حركة موجية حول النواة (λ = h/mv)، وهذا ما أهمله نموذج بور.', '["","أينشتاين اقترح الطبيعة الجسيمية للضوء (الفوتونات).","بلانك افترض تكميم الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.132Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(195, 2, 'افترض بور أن الإلكترون يتحرك في مدار دائري مستوٍ (ثنائي الأبعاد)، بينما الذرة ثلاثية الأبعاد ويُحتمل وجود الإلكترون في الفراغ حول النواة من جميع الجهات.', '["النواة في نموذج بور في مركز الذرة.","افترض بور عدة مستويات طاقة (n = 1 إلى 7).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(196, 1, 'فسّر النموذج طيف الهيدروجين (إلكترون واحد) فقط، وعجز عن الهيليوم والليثيوم والصوديوم وهي ذرات متعددة الإلكترونات.', '["عجز عن تفسير طيف الهيليوم وهو عنصر غازي.","","الهيدروجين الذي نجح معه ليس فلزًا، وعجز مع الليثيوم والصوديوم الفلزيين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(197, 1, 'عامل بور الإلكترون جسيمًا يدور في مدار محدد يمكن معرفة مكانه وسرعته فيه، متجاهلًا طبيعته الموجية (دي برولي) ومبدأ الشك (هايزنبرج)، وعجز عن تفسير أطياف الذرات المتعددة الإلكترونات، فظهر النموذج الميكانيكي الكمي.', '["بور هو من اقترح مستويات الطاقة المحددة.","","افترض بور أن الإلكترونات تدور حول النواة لا داخلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(198, null, null, null, '1) لم يفسر أطياف العناصر الأعقد من الهيدروجين (ذات الإلكترونات المتعددة). 2) افترض إمكان تحديد مكان الإلكترون وسرعته معًا. 3) افترض أن الإلكترون يتحرك في مسار دائري مستوٍ، فجعل الذرة مسطحة. 4) أهمل الخاصية الموجية للإلكترون.', '["عدم تفسير أطياف العناصر الأعقد","تحديد المكان والسرعة معًا","المسار الدائري المستوي (ذرة مسطحة)","إهمال الخاصية الموجية"]'::jsonb, '[]'::jsonb, '[{"element":"العيب الأول","marks":1},{"element":"العيب الثاني","marks":1},{"element":"العيب الثالث","marks":1},{"element":"العيب الرابع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربعة عيوب صحيحة"},{"level":"3 درجات","description":"ثلاثة عيوب"},{"level":"2 درجتان","description":"عيبان"},{"level":"1 درجة","description":"عيب واحد"},{"level":"صفر","description":"لا إجابة أو عيوب خاطئة"}]'::jsonb, '["ذكر عدم تفسير طيف الهيدروجين عيبًا","ذكر تكميم الطاقة عيبًا","تكرار العيب نفسه بصياغتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(199, null, null, null, 'دي برولي: اقترح أن للإلكترون خاصية موجية، فهو يتحرك حركة موجية حول النواة (λ = h/mv)، فكشف عيب إهمال بور للخاصية الموجية للإلكترون ومعاملته جسيمًا فقط. هايزنبرج: نص مبدؤه على استحالة تحديد مكان الإلكترون وسرعته معًا بدقة في الوقت نفسه، فكشف خطأ افتراض بور بأن للإلكترون مدارًا محددًا يمكن فيه معرفة مكانه وسرعته معًا.', '["فكرة دي برولي: الطبيعة الموجية للإلكترون","العيب المقابل: إهمال الخاصية الموجية","مبدأ هايزنبرج","العيب المقابل: تحديد المكان والسرعة معًا (مدار محدد)"]'::jsonb, '[]'::jsonb, '[{"element":"فكرة دي برولي والعيب المرتبط","marks":2},{"element":"مبدأ هايزنبرج والعيب المرتبط","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"ربط صحيح للفكرتين بعيبيهما"},{"level":"2–3 درجات","description":"ربط صحيح لفكرة واحدة وجزئي للأخرى"},{"level":"1 درجة","description":"ذكر الفكرتين دون ربط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسبة مبدأ الشك إلى دي برولي","عدم ذكر العيب المرتبط بكل فكرة","الخلط بين الطبيعة الموجية للإلكترون وللضوء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(200, null, null, null, 'العبارة غير دقيقة. من نجاحات النموذج: (1) فسّر طيف الانبعاث الخطي لذرة الهيدروجين، (2) أدخل فكرة مستويات الطاقة المحددة (المكمّاة) وحالتي الاستقرار والإثارة، وهي فكرة أبقى عليها النموذج الكمي. ومن عيوبه: (1) لم يفسر أطياف العناصر الأعقد من الهيدروجين، (2) أهمل الخاصية الموجية للإلكترون (أو افترض تحديد مكانه وسرعته معًا، أو جعل الذرة مسطحة). فالنموذج خطوة مهمة لكنه محدود.', '["الحكم: العبارة غير دقيقة","نجاح: تفسير طيف الهيدروجين","نجاح: مستويات الطاقة المكماة","عيبان صحيحان","استنتاج متوازن"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة","marks":1},{"element":"نجاحان صحيحان","marks":2},{"element":"عيبان صحيحان","marks":2},{"element":"الاستنتاج المتوازن","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"حكم صحيح مع نجاحين وعيبين واستنتاج"},{"level":"4–5 درجات","description":"نقص في عنصر واحد"},{"level":"2–3 درجات","description":"عيبان فقط أو نجاحان فقط"},{"level":"1 درجة","description":"حكم دون دعم"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الموافقة على العبارة دون نقد","ذكر عيوب غير صحيحة","نسبة إنجازات النموذج الكمي إلى بور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.134Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(201, 1, 'سلسلة بالمر تنتج عند عودة الإلكترون من مستويات أعلى إلى n = 2، وتقع في منطقة الضوء المرئي.', '["العودة إلى n = 1 تعطي سلسلة ليمان.","","العودة إلى n = 3 تعطي سلسلة باشن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.137Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(202, 2, 'سلسلة ليمان تنتج عند العودة إلى n = 1، وهي أكبر فروق طاقة، فتقع في منطقة الأشعة فوق البنفسجية.', '["تحت الحمراء منطقة سلسلة باشن.","المرئي منطقة سلسلة بالمر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.137Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(203, 0, 'السلسلة تحدد بالمستوى الذي يعود إليه الإلكترون، والعودة إلى n = 2 تعني سلسلة بالمر في منطقة الضوء المرئي (الخط 486 nm).', '["","باشن عند العودة إلى n = 3 لا إلى n = 2.","ليمان عند العودة إلى n = 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T11:15:01.137Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(204, 1, 'العودة إلى n = 3 تعطي سلسلة باشن، وتقع في منطقة الأشعة تحت الحمراء.', '["ليمان عند العودة إلى n = 1.","","بالمر عند العودة إلى n = 2؛ والسلسلة لا تحدد بالمستوى الذي بدأ منه الإلكترون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T11:15:01.137Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(205, 2, 'طاقة الفوتون تساوي فرق الطاقة بين المستويين، والعودة إلى n = 1 تقابل أكبر الفروق، فتكون فوتونات ليمان (فوق البنفسجية) الأعلى طاقة.', '["العودة إلى n = 3 تقابل فروقًا صغيرة، فباشن (تحت الحمراء) أقل طاقة.","كونها مرئية لا يعني أنها الأعلى طاقة؛ ففوق البنفسجية أعلى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.138Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(206, 1, 'الانتقال 6 → 2 يعطي أقصر طول موجي (410 nm)، وطاقة الفوتون تتناسب عكسيًا مع الطول الموجي، فهو الأعلى طاقة؛ كما أنه يقابل أكبر فرق طاقة بين المستويات في الجدول.', '["يعطي أطول طول موجي (656 nm) فهو الأقل طاقة.","","طوله الموجي 486 nm أطول من 410 nm فطاقته أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.138Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(207, 0, 'مستويات الطاقة في الذرة محددة (مكمّاة)، وطاقة الفوتون المنبعث تساوي فرق الطاقة بين مستويين، فلا تنبعث إلا ترددات معينة تظهر خطوطًا منفصلة.', '["","وفق بور لا يشع الإلكترون وهو في مداره، ولو أشع باستمرار لكان الطيف مستمرًا.","الذرة تمتص ترددات محددة لا جميع الترددات، وهذا لا يفسر الانبعاث الخطي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.138Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(208, null, null, null, 'عندما تمتص ذرة الهيدروجين طاقة ينتقل إلكترونها إلى مستوى أعلى فتصبح مثارة، ثم يعود إلى مستوى أدنى ويبعث فوتونًا طاقته تساوي فرق الطاقة بين المستويين: E(الفوتون) = E(الأعلى) − E(الأدنى) = hν. ولأن المستويات محددة تنبعث ترددات معينة تظهر خطوطًا. تُصنّف الخطوط حسب المستوى الذي يعود إليه الإلكترون: ليمان إلى n = 1 (فوق البنفسجية)، وبالمر إلى n = 2 (الضوء المرئي)، وباشن إلى n = 3 (تحت الحمراء).', '["الإثارة بامتصاص الطاقة","العودة لمستوى أدنى وانبعاث فوتون","طاقة الفوتون = فرق الطاقة","التصنيف حسب المستوى النهائي","ليمان n=1 فوق بنفسجية، بالمر n=2 مرئي، باشن n=3 تحت حمراء"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير نشوء الخطوط","marks":2},{"element":"أساس التصنيف","marks":1},{"element":"السلاسل الثلاث ومناطقها","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"تفسير كامل وتصنيف صحيح للسلاسل الثلاث"},{"level":"4–5 درجات","description":"تفسير صحيح مع خطأ في سلسلة واحدة"},{"level":"2–3 درجات","description":"تصنيف السلاسل فقط أو تفسير فقط"},{"level":"1 درجة","description":"معلومة صحيحة واحدة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تصنيف السلسلة حسب مستوى البداية","القول إن الإلكترون يبعث فوتونًا عند صعوده","الخلط بين مناطق ليمان وباشن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.138Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(209, null, null, null, '(أ) 6 → 1: ليمان، فوق البنفسجية؛ لأن الإلكترون عاد إلى n = 1. (ب) 3 → 2: بالمر، الضوء المرئي (الخط 656 nm)؛ لعودته إلى n = 2. (ج) 4 → 3: باشن، تحت الحمراء؛ لعودته إلى n = 3. (د) 2 → 1: ليمان، فوق البنفسجية؛ لعودته إلى n = 1.', '["(أ) ليمان، فوق بنفسجية","(ب) بالمر، مرئي","(ج) باشن، تحت حمراء","(د) ليمان، فوق بنفسجية","التعليل بالمستوى النهائي"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف كل انتقال (درجة لكل انتقال)","marks":4},{"element":"التعليل بالمستوى النهائي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للأربعة مع التعليل"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة صحيحة دون تعليل كافٍ"},{"level":"1–2 درجة","description":"انتقال أو اثنان صحيحان"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تصنيف (ج) بالمر لأن الإلكترون بدأ من n = 4","عد (د) بالمر لأنه بدأ من n = 2","الخلط بين المناطق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.139Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(210, null, null, null, '(أ) E(656) = hc/λ = (6.626×10⁻³⁴ × 3.00×10⁸) ÷ 6.56×10⁻⁷ = 3.03×10⁻¹⁹ J. E(486) = (6.626×10⁻³⁴ × 3.00×10⁸) ÷ 4.86×10⁻⁷ = 4.09×10⁻¹⁹ J. (ب) الانتقال 4 → 2 يقابل فرق طاقة أكبر (4.09×10⁻¹⁹ J)؛ لأن طاقة المستوى تزداد بالبعد عن النواة، فالمستوى n = 4 أعلى طاقة من n = 3، والفرق بينه وبين n = 2 أكبر، لذا يكون الفوتون المنبعث أعلى طاقة وأقصر طولًا موجيًا.', '["تحويل nm إلى m","E(656) = 3.03×10⁻¹⁹ J","E(486) = 4.09×10⁻¹⁹ J","4 → 2 فرق أكبر","التفسير بزيادة طاقة المستوى بالبعد عن النواة"]'::jsonb, '["E = hc/λ","E(656) = 1.988×10⁻²⁵ ÷ 6.56×10⁻⁷ = 3.03×10⁻¹⁹ J","E(486) = 1.988×10⁻²⁵ ÷ 4.86×10⁻⁷ = 4.09×10⁻¹⁹ J"]'::jsonb, '[{"element":"(أ) طاقة الخط 656 nm","marks":1},{"element":"(أ) طاقة الخط 486 nm","marks":1},{"element":"(ب) تحديد الانتقال الأكبر","marks":1},{"element":"(ب) التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان وتفسير كامل"},{"level":"3–4 درجات","description":"حسابان صحيحان مع تفسير ناقص"},{"level":"1–2 درجة","description":"حساب واحد أو استنتاج دون حساب"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسيان تحويل nm","استنتاج أن الطول الموجي الأكبر يعني طاقة أكبر","عدم ربط طاقة الفوتون بفرق المستويين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.139Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(211, 1, 'افترض دي برولي أن للجسيمات المتحركة كالإلكترون خصائص موجية، فالإلكترون يتحرك حول النواة حركة موجية.', '["هذه فكرة أينشتاين عن الطبيعة الجسيمية للضوء.","","هذا من فرضيات نموذج بور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.141Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(212, 0, 'معادلة دي برولي: λ = h ÷ (mv)، حيث h ثابت بلانك وm كتلة الجسيم وv سرعته.', '["","علاقة مقلوبة؛ الطول الموجي يتناسب عكسيًا مع كمية الحركة mv.","الضرب يجعل الطول الموجي طرديًا مع الكتلة والسرعة وهذا خطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.141Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(213, 1, 'الرمز v يمثل سرعة الجسيم بوحدة m/s، وليس التردد (الذي يرمز له بـ ν).', '["خطأ شائع (ورد في المذكرة)؛ التردد رمزه ν، أما v في المعادلة فهي السرعة.","","الحجم لا يظهر في المعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.142Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(214, 2, 'λ = h ÷ (mv)، فالطول الموجي يتناسب عكسيًا مع السرعة؛ مضاعفة السرعة تقلل الطول الموجي إلى النصف.', '["هذا يحدث لو كانت العلاقة طردية.","الطول الموجي يعتمد على السرعة وفق المعادلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.142Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(215, 2, 'λ = h ÷ (mv) = 6.626×10⁻³⁴ ÷ (9.11×10⁻³¹ × 2.2×10⁶) = 3.3×10⁻¹⁰ m.', '["ناتج ضرب h في m وv بدل القسمة.","ناتج (mv) ÷ h، أي مقلوب العلاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-11T11:15:01.142Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(216, 0, 'الطول الموجي يتناسب عكسيًا مع حاصل ضرب الكتلة في السرعة (mv). أصغر قيمة لـ mv للجسيم (أ): 9.11×10⁻³¹ × 1.0×10⁶ = 9.1×10⁻²⁵، فطوله الموجي الأطول.', '["","كتلته (بروتون) أكبر كثيرًا فحاصل mv أكبر وطوله الموجي أقصر.","سرعته أكبر من (أ) بالكتلة نفسها، فطوله الموجي أقصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.142Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(217, 0, 'λ = h ÷ (mv)، وكتلة الكرة كبيرة جدًا مقارنة بالإلكترون فيكون طولها الموجي ضئيلًا جدًا (نحو 10⁻³⁴ m) لا يمكن ملاحظته، أما الإلكترون فطوله الموجي يقارب حجم الذرة.', '["","أي جسيم متحرك له طول موجي مصاحب مهما كانت سرعته؛ والسرعة الأقل تعطي طولًا موجيًا أكبر لا أصغر.","فرضية دي برولي تخص الجسيمات المادية المتحركة كالإلكترون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.143Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(218, null, null, null, 'الفرضية: للجسيمات المتحركة (كالإلكترون) خصائص موجية، فالإلكترون يتحرك حول النواة حركة موجية. المعادلة: λ = h ÷ (mv)؛ λ الطول الموجي المصاحب (m)، وh ثابت بلانك 6.626×10⁻³⁴ J·s، وm كتلة الجسيم (kg)، وv سرعته (m/s). التصحيح: v في المعادلة هي سرعة الجسيم بوحدة m/s، وليست التردد الذي يرمز له بالحرف ν ويقاس بـ s⁻¹.', '["الإلكترون يتحرك حركة موجية","λ = h/(mv)","تعريف الرموز ووحداتها","تصحيح الخطأ: v السرعة لا التردد"]'::jsonb, '[]'::jsonb, '[{"element":"توضيح الفرضية","marks":1},{"element":"المعادلة","marks":1},{"element":"الرموز والوحدات","marks":1},{"element":"تصحيح الخطأ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"الفرضية والمعادلة فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قبول أن v هي التردد","كتابة λ = mv/h","الخلط بين فرضية دي برولي وفكرة الفوتون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.143Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(219, null, null, null, '(أ) λ = h ÷ (mv) = 6.626×10⁻³⁴ ÷ (9.11×10⁻³¹ × 1.0×10⁷) = 7.3×10⁻¹¹ m. (ب) الطول الموجي (7.3×10⁻¹¹ m) قريب من حجم الذرة (1×10⁻¹⁰ m)، أي من رتبة الحجم نفسها؛ ولذلك لا يمكن إهمال الخاصية الموجية للإلكترون داخل الذرة، وهذا ما أهمله نموذج بور.', '["λ = h/(mv)","التعويض الصحيح","λ = 7.3×10⁻¹¹ m","المقارنة: من رتبة حجم الذرة","الدلالة: لا يمكن إهمال الخاصية الموجية"]'::jsonb, '["mv = 9.11×10⁻³¹ × 1.0×10⁷ = 9.11×10⁻²⁴ kg·m/s","λ = 6.626×10⁻³⁴ ÷ 9.11×10⁻²⁴ = 7.3×10⁻¹¹ m"]'::jsonb, '[{"element":"(أ) العلاقة والتعويض","marks":1},{"element":"(أ) الناتج والوحدة","marks":1},{"element":"(ب) المقارنة","marks":1},{"element":"(ب) الدلالة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح ومقارنة ودلالة"},{"level":"3–4 درجات","description":"حساب صحيح مع مقارنة أو دلالة ناقصة"},{"level":"1–2 درجة","description":"علاقة صحيحة مع خطأ حسابي"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب h في mv","الخطأ في جمع الأسس","عدم الربط بنموذج بور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-11T11:15:01.144Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(220, null, null, null, '(أ) λ = h ÷ (mv) = 6.626×10⁻³⁴ ÷ (0.15 × 40) = 1.1×10⁻³⁴ m. (ب) لأن الطول الموجي يتناسب عكسيًا مع الكتلة والسرعة؛ فكتلة الكرة الكبيرة تجعل طولها الموجي ضئيلًا جدًا (أصغر من الذرة بنحو 10²⁴ مرة) فلا يمكن ملاحظته، أما الإلكترون فكتلته صغيرة جدًا فيكون طوله الموجي من رتبة حجم الذرة فيظهر سلوكه الموجي.', '["λ = h/(mv)","λ = 1.1×10⁻³⁴ m","التناسب العكسي مع الكتلة","الكرة: طول موجي ضئيل غير ملحوظ","الإلكترون: طول موجي من رتبة حجم الذرة"]'::jsonb, '["mv = 0.15 × 40 = 6.0 kg·m/s","λ = 6.626×10⁻³⁴ ÷ 6.0 = 1.1×10⁻³⁴ m"]'::jsonb, '[{"element":"(أ) الحساب","marks":2},{"element":"(ب) التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح وتفسير كامل"},{"level":"3 درجات","description":"حساب صحيح مع تفسير ناقص"},{"level":"2 درجتان","description":"تفسير صحيح دون حساب أو العكس"},{"level":"1 درجة","description":"العلاقة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الأجسام الكبيرة ليس لها طول موجي إطلاقًا","ضرب بدل القسمة","تفسير الفرق بالسرعة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.145Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(221, 0, 'ينص مبدأ هايزنبرج للشك على أنه من المستحيل معرفة سرعة جسيم (كالإلكترون) ومكانه في الوقت نفسه بدقة.', '["","هذا مبدأ باولي للاستبعاد.","هذا مبدأ أوفباو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.147Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(222, 1, 'لرصد الإلكترون يجب أن يصطدم به فوتون، وطاقة الفوتون كافية لتغيير سرعة الإلكترون واتجاهه، فيتغير ما نحاول قياسه.', '["الإلكترون جسيم متحرك له سرعة.","","الإلكترون لا يختفي، لكن حركته تتأثر بعملية القياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.147Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(223, 1, 'لا يمكن تحديد مسار ثابت للإلكترون، بل يمكن فقط تحديد المنطقة التي يحتمل وجوده فيها، وعلى ذلك بُني النموذج الميكانيكي الكمي.', '["المدار الثابت فكرة بور التي يتعارض معها المبدأ.","","هذا عكس نص المبدأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.147Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(224, 2, 'افترض بور مدارًا محددًا يمكن فيه معرفة مكان الإلكترون وسرعته معًا، وهذا يتعارض مع مبدأ الشك.', '["تكميم الطاقة لا يتعارض مع مبدأ الشك، وقد أبقى عليه النموذج الكمي.","وجود النواة الموجبة لا يتعارض مع المبدأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.147Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(225, 1, 'عدم الدقة ليس سببه ضعف الأجهزة؛ فعملية القياس نفسها تتطلب فوتونًا يغيّر سرعة الإلكترون واتجاهه، فالشك جزء من طبيعة القياس.', '["مفهوم خاطئ شائع؛ تحسين الأجهزة لا يزيل الشك.","","زيادة شدة الضوء تعني فوتونات أكثر، وكل فوتون يغير حركة الإلكترون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.148Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(226, 2, 'ادعاء (ج) يزعم تحديد المكان والسرعة معًا بدقة تامة في اللحظة نفسها، وهذا ما ينفيه مبدأ الشك. أما وصف المنطقة المحتملة أو تغير الحركة عند القياس فيتفقان معه.', '["وصف المنطقة المحتملة لوجود الإلكترون يتفق مع المبدأ.","تأثير القياس في حركة الإلكترون هو أساس المبدأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.148Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(227, 0, 'مبدأ هايزنبرج للشك بيّن استحالة تحديد مكان الإلكترون وسرعته معًا، فوصف النموذج الكمي الموقع المحتمل للإلكترون.', '["","باولي صاحب مبدأ الاستبعاد (لا يتسع المجال لأكثر من إلكترونين).","هوند صاحب قاعدة توزيع الإلكترونات في المجالات المتساوية الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.148Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(228, null, null, null, 'النص: من المستحيل معرفة سرعة جسيم (كالإلكترون) ومكانه في الوقت نفسه بدقة. السبب: رصد الإلكترون يتطلب أن يصطدم به فوتون، وطاقة هذا الفوتون كافية لتغيير سرعة الإلكترون واتجاهه، فيتغير ما نحاول قياسه في أثناء القياس نفسه.', '["النص: استحالة معرفة السرعة والمكان معًا بدقة","الرصد يتطلب فوتونًا","الفوتون يغير سرعة الإلكترون واتجاهه"]'::jsonb, '[]'::jsonb, '[{"element":"نص المبدأ","marks":2},{"element":"توضيح السبب","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"نص دقيق وسبب واضح"},{"level":"3 درجات","description":"نص دقيق وسبب ناقص"},{"level":"2 درجتان","description":"نص دقيق فقط"},{"level":"1 درجة","description":"نص ناقص"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ذكر المكان فقط دون السرعة","تعليل الشك بضعف الأجهزة","الخلط مع مبدأ باولي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.148Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(229, null, null, null, 'افترض نموذج بور أن الإلكترون يدور في مدار دائري محدد يمكن فيه معرفة مكانه وسرعته معًا. أما مبدأ هايزنبرج فبيّن استحالة ذلك، فلا يمكن تحديد مسار ثابت للإلكترون، وإنما يمكن تحديد المنطقة التي يحتمل وجوده فيها. وعلى هذا بُني النموذج الميكانيكي الكمي الذي يصف الإلكترون بمنطقة احتمالية ثلاثية الأبعاد (المجال/السحابة الإلكترونية) بدل المدار.', '["بور: مدار محدد يعرف فيه المكان والسرعة","هايزنبرج: استحالة ذلك","لا مسار ثابت بل منطقة احتمالية","النموذج الكمي: مجال/سحابة إلكترونية"]'::jsonb, '[]'::jsonb, '[{"element":"وصف بور","marks":1},{"element":"ما بيّنه المبدأ","marks":1},{"element":"الوصف الجديد (المنطقة الاحتمالية)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة"},{"level":"3 درجات","description":"نقص في عنصر"},{"level":"2 درجتان","description":"ذكر المنطقة الاحتمالية فقط"},{"level":"1 درجة","description":"عبارة عامة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن هايزنبرج حدد مدارًا جديدًا للإلكترون","الخلط بين المدار والمجال","إغفال فكرة الاحتمال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.148Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(230, null, null, null, 'العبارة خاطئة؛ فالشك ليس سببه ضعف الأجهزة، بل طبيعة القياس نفسها: لرصد الإلكترون يجب أن يصطدم به فوتون يغيّر سرعته واتجاهه، فمهما تطورت الأجهزة يبقى هذا التأثير. ولا يعني المبدأ أننا نجهل موقع الإلكترون كليًا؛ فيمكن تحديد المنطقة التي يحتمل وجوده فيها (المجال)، وهو ما يصفه النموذج الميكانيكي الكمي.', '["الحكم: العبارة خاطئة","السبب: عملية القياس تغير حركة الإلكترون","تطوير الأجهزة لا يزيل الشك","يمكن تحديد المنطقة المحتملة لوجود الإلكترون"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"تعليل الحكم","marks":2},{"element":"توضيح ما يمكن معرفته","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حكم وتعليل وتوضيح كامل"},{"level":"3–4 درجات","description":"حكم وتعليل دون التوضيح"},{"level":"1–2 درجة","description":"حكم دون تعليل كافٍ"},{"level":"صفر","description":"لا إجابة أو موافقة على العبارة"}]'::jsonb, '["الموافقة على العبارة","القول إن موقع الإلكترون مجهول تمامًا","عدم ذكر دور الفوتون في القياس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.149Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(231, 0, 'مستوى الطاقة الرئيس يحدده عدد الكم الرئيس n (1، 2، 3، ...)، ويشير إلى الحجم النسبي للمستوى وطاقته.', '["","عدد البروتونات هو العدد الذري ولا يحدد مستوى الإلكترون.","شكل المجال يتعلق بنوع المستوى الثانوي لا بالمستوى الرئيس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.151Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(232, 2, 'كلما زادت قيمة n زاد الحجم النسبي للمستوى وبعده عن النواة، وزادت طاقته.', '["الحجم يزداد بزيادة n لا يقل.","الطاقة تزداد بالبعد عن النواة لا تقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.151Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(233, 1, 'أقصى عدد للإلكترونات في المستوى الرئيس = 2n² = 2 × 3² = 18 إلكترونًا.', '["9 هو n² أي عدد المجالات في المستوى الثالث لا عدد الإلكترونات.","","ناتج 2n بدل 2n²."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.151Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(234, 1, 'الإلكترون (ب) في المستوى n = 3 وهو أبعد المستويات عن النواة في الجدول، وطاقة المستوى تزداد بزيادة n.', '["في n = 1 أقرب المستويات إلى النواة وأقلها طاقة.","","في n = 2 وهو أقل طاقة من n = 3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.151Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(235, 0, 'عدد مستويات الطاقة الرئيسة في الذرات المعروفة سبعة (n = 1 إلى 7).', '["","4 هو عدد المستويات الرئيسة التي تطبق عليها قاعدة 2n².","18 هو أقصى عدد للإلكترونات في المستوى الثالث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.152Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(236, 2, 'قاعدة 2n² تطبق على المستويات من 1 إلى 4 فقط، أما المستويات من 4 إلى 7 فأقصى ما تحتويه في العناصر المعروفة 32 إلكترونًا.', '["ناتج تطبيق 2n² على المستوى الخامس، والقاعدة لا تطبق عليه في العناصر المعروفة.","25 هو n² للمستوى الخامس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.152Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(237, 0, 'المستوى الرئيس يحدده عدد الكم الرئيس n ويضم n² من المجالات، أما المجال فمنطقة احتمالية يتسع لإلكترونين على الأكثر.', '["","عكس للصحيح؛ المجال هو الذي يتسع لإلكترونين، والمستوى الرئيس يحدده n.","المجال ليس مدارًا دائريًا، وللمستوى الرئيس عدة مجالات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.152Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(238, null, null, null, 'مستوى الطاقة الرئيس: مستوى الطاقة الذي يحدده عدد الكم الرئيس n (من 1 إلى 7 في الذرات المعروفة). يدل n على الحجم النسبي للمستوى وطاقته. وبزيادة n يزداد حجم المستوى وبعده عن النواة، وتزداد طاقته، ويزداد عدد ما يحتويه من مستويات ثانوية ومجالات وإلكترونات.', '["يحدده عدد الكم الرئيس n","n من 1 إلى 7","n يدل على الحجم النسبي والطاقة","بزيادة n يزداد الحجم والطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"المقصود بالمستوى الرئيس","marks":1},{"element":"دلالة n","marks":1},{"element":"أثر زيادة n","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"تعريف ودلالة n فقط"},{"level":"1 درجة","description":"عبارة صحيحة واحدة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الطاقة تقل بزيادة n","الخلط بين المستوى الرئيس والمستوى الثانوي","وصف المستوى بأنه مدار دائري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.152Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(239, null, null, null, '(أ) n = 1: 2 × 1² = 2 ، n = 2: 2 × 2² = 8 ، n = 3: 2 × 3² = 18 ، n = 4: 2 × 4² = 32. (ب) لأن العلاقة تُطبق على المستويات الأربعة الأولى فقط؛ فالمستويات من الخامس إلى السابع لا تمتلئ كليًا في ذرات العناصر المعروفة، وأقصى ما ورد لها 32 إلكترونًا (وليس 50 أو 72 أو 98).', '["سعة n=1 إلى 4: 2، 8، 18، 32","العلاقة تطبق على المستويات 1–4","سعة المستويات 5–7 في الجدول 32"]'::jsonb, '["2(1)² = 2","2(2)² = 8","2(3)² = 18","2(4)² = 32"]'::jsonb, '[{"element":"(أ) الحسابات الأربعة","marks":2},{"element":"(ب) سبب عدم التطبيق","marks":1},{"element":"(ب) السعة 32","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة وتفسير وسعة صحيحة"},{"level":"3 درجات","description":"حسابات صحيحة مع نقص في (ب)"},{"level":"2 درجتان","description":"الحسابات فقط"},{"level":"1 درجة","description":"حسابان صحيحان"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["حساب (2n)² بدل 2n²","تطبيق القاعدة على المستوى الخامس فيكون 50","الخلط بين n² و2n²"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.153Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(240, null, null, null, 'المستوى الرئيس: يحدده عدد الكم الرئيس n ويدل على الحجم والطاقة. المستوى الثانوي: أقسام داخل المستوى الرئيس عددها يساوي n (s، p، d، f). المجال: منطقة ثلاثية الأبعاد يحتمل وجود الإلكترون فيها، يتسع لإلكترونين على الأكثر. العلاقة: المستوى الرئيس يضم مستويات ثانوية، وكل مستوى ثانوي يضم مجالًا أو أكثر. مثال n = 2: يضم مستويين ثانويين (2s و2p)؛ 2s فيه مجال واحد و2p فيه ثلاثة مجالات، فالمجموع 4 مجالات (n²) تتسع لـ 8 إلكترونات (2n²).', '["تعريف المستوى الرئيس","تعريف المستوى الثانوي","تعريف المجال وسعته","العلاقة الهرمية بينها","مثال n = 2: 2s و2p، 4 مجالات، 8 إلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المفاهيم الثلاثة","marks":3},{"element":"العلاقة بينها","marks":1},{"element":"المثال","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة دقيقة ومثال صحيح"},{"level":"4–5 درجات","description":"مقارنة صحيحة مع خطأ في المثال"},{"level":"2–3 درجات","description":"تعريف مفهومين فقط"},{"level":"1 درجة","description":"تعريف مفهوم واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ذكر 2d ضمن المستوى الثاني","عد المجال مسارًا دائريًا","الخلط بين عدد المجالات وعدد الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.153Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(241, 1, 'في نموذج بور يدور الإلكترون في مدار دائري محدد، أما في النموذج الميكانيكي الكمي فلا يُحدد له مسار، بل منطقة ثلاثية الأبعاد (مجال) يُحتمل وجوده فيها.', '["عكس للنموذجين.","","النموذج الكمي لا يحدد مدارًا للإلكترون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.156Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(242, 0, 'يتفق النموذجان في أن طاقة الإلكترون مكمّاة، أي محددة بمستويات طاقة معينة.', '["","هذا خاص بنموذج بور؛ فالنموذج الكمي يعامل الإلكترون موجة.","هذا افتراض بور الذي نقضه مبدأ هايزنبرج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.156Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(243, 1, 'النموذج الكمي المبني على أفكار دي برولي وشرودنجر يعامل الإلكترون موجة، بينما عامله بور جسيمًا يدور في مدار.', '["النموذج الكمي أخذ الخاصية الموجية للإلكترون في الحسبان.","","الإلكترون سالب الشحنة ويوجد خارج النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.156Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(244, 2, 'نموذج بور فسر طيف الهيدروجين فقط، أما النموذج الميكانيكي الكمي فيمكن تطبيقه على ذرات جميع العناصر.', '["عجز نموذج بور عن تفسير أطياف العناصر الأعقد من الهيدروجين.","النموذج الكمي ينطبق على جميع الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-10-11T11:15:01.156Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(245, 0, 'النموذج الميكانيكي الكمي مبني على الطبيعة الموجية للإلكترون (دي برولي)، ومبدأ الشك (هايزنبرج)، ومعادلة شرودنجر.', '["","هؤلاء أصحاب نماذج ذرية سابقة لنموذج بور.","أفكارهم مهدت للنموذج، لكن أساسه دي برولي وهايزنبرج وشرودنجر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.157Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(246, 1, 'الصف (1) صحيح: الذرة المستوية (المسطحة) من صفات نموذج بور. أما الصف (2) فخاطئ لأن تحديد المكان والسرعة معًا افتراض بور، والصف (3) خاطئ لأن السحابة الإلكترونية من صفات النموذج الكمي.', '["تحديد مكان الإلكترون وسرعته معًا افتراض نموذج بور لا النموذج الكمي.","","السحابة الإلكترونية من صفات النموذج الكمي لا نموذج بور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.157Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(247, 2, 'النموذج الكمي أبقى على مستويات الطاقة المحددة (يحددها n)، لكنه استبدل المدارات المحددة بمجالات احتمالية.', '["الطاقة في النموذج الكمي مكمّاة أيضًا.","النموذج الكمي يستخدم عدد الكم الرئيس n لتحديد مستويات الطاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.157Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(248, null, null, null, 'طبيعة الإلكترون: بور جسيم ، الكمي موجة. مكانه: بور مدار دائري محدد نصف قطره ثابت ، الكمي مجال (سحابة إلكترونية) يحتمل وجوده فيه. تحديد المكان والسرعة: بور ممكن معًا ، الكمي غير ممكن (مبدأ هايزنبرج) ويحدد الموقع المحتمل فقط. شكل الذرة: بور مستوية (مسطحة) ، الكمي ثلاثية الأبعاد. مجال التطبيق: بور ذرة الهيدروجين فقط ، الكمي جميع الذرات.', '["طبيعة الإلكترون","مكانه: مدار/مجال","تحديد المكان والسرعة","شكل الذرة","مجال التطبيق"]'::jsonb, '[]'::jsonb, '[{"element":"طبيعة الإلكترون","marks":1},{"element":"مكان الإلكترون","marks":1},{"element":"تحديد المكان والسرعة","marks":1},{"element":"شكل الذرة","marks":1},{"element":"مجال التطبيق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المقارنة صحيحة في الجوانب الخمسة"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة جوانب صحيحة"},{"level":"1–2 درجة","description":"جانب أو جانبان"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس الصفات بين النموذجين","القول إن النموذج الكمي يحدد مدارًا","إغفال مجال التطبيق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.157Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
