(249, null, null, null, 'وجه الشبه: كلاهما يقر بأن طاقة الإلكترون في الذرة مكمّاة (محددة بمستويات طاقة معينة). النموذج الكمي أدق لأنه: (1) يأخذ في الحسبان الطبيعة الموجية للإلكترون (دي برولي) ومبدأ الشك (هايزنبرج)، فيصف الموقع المحتمل للإلكترون بدل مدار محدد. (2) يمكن تطبيقه على ذرات جميع العناصر لا الهيدروجين فقط، ويصف الذرة ثلاثية الأبعاد.', '["وجه الشبه: تكميم الطاقة","سبب: الطبيعة الموجية ومبدأ الشك","سبب: التطبيق على جميع الذرات أو ثلاثية الأبعاد"]'::jsonb, '[]'::jsonb, '[{"element":"وجه الشبه","marks":1},{"element":"السبب الأول","marks":1},{"element":"السبب الثاني","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"وجه شبه وسببان صحيحان"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ذكر المدار الدائري وجه شبه","القول إن النموذج الكمي ألغى المستويات","ذكر سببين متكررين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.158Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(250, null, null, null, '(أ) الرسم (1) نموذج بور (إلكترون جسيم في مدار دائري محدد)، والرسم (2) النموذج الميكانيكي الكمي (السحابة الإلكترونية). (ب) كثافة النقاط تمثل احتمال وجود الإلكترون؛ فالمنطقة الأكثف هي الأعلى احتمالًا لوجوده. (ج) لأنه لا يمكن تحديد مكان الإلكترون بدقة (مبدأ هايزنبرج)، وإنما يُحدد احتمال وجوده، فليس للمجال حدود قاطعة.', '["الرسم (1): بور","الرسم (2): الكمي","الكثافة = احتمال وجود الإلكترون","لا حدود حادة لعدم إمكان تحديد المكان بدقة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تحديد النموذجين","marks":2},{"element":"(ب) دلالة الكثافة","marks":1},{"element":"(ج) تعليل غياب الحدود","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"3–4 درجات","description":"تحديد صحيح مع نقص في التفسير"},{"level":"1–2 درجة","description":"تحديد النموذجين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن السحابة تعني انتشار الإلكترون كالغاز","عكس الرسمين","تفسير الكثافة بعدد الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.158Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(251, 1, 'عدد المستويات الثانوية يساوي n، فالمستوى الثالث يضم ثلاثة مستويات ثانوية: 3s و3p و3d.', '["هذه مستويات المستوى الرئيس الثاني.","","هذه مستويات المستوى الرئيس الرابع؛ و3f غير موجود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.160Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(252, 0, 'عدد المستويات الثانوية = n = 4 وهي: 4s و4p و4d و4f.', '["","16 هو عدد المجالات (n²) في المستوى الرابع.","32 هو أقصى عدد للإلكترونات (2n²) في المستوى الرابع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T11:15:01.160Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(253, 2, 'المستوى الثانوي d يتكون من 5 مجالات، وكل مجال يتسع لإلكترونين، فسعته 10 إلكترونات.', '["5 هو عدد مجالات d لا عدد إلكتروناته.","14 سعة المستوى الثانوي f.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(254, 1, 'المستوى الرئيس الثاني يضم مستويين ثانويين فقط (2s و2p)، فالمستوى 2d غير موجود. أما 3d فموجود لأن المستوى الثالث يضم s وp وd.', '["المستوى الثالث يضم s وp وd، فـ 3d موجود.","","المستوى الثاني يضم s وp، فـ 2p موجود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(255, 1, 'المستوى الثانوي f يتكون من 7 مجالات، وكل مجال يتسع لإلكترونين، فسعته 14 إلكترونًا.', '["هاتان قيمتا المستوى الثانوي d.","","بُدّل بين عدد المجالات وعدد الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(256, 2, 'عدد المجالات = n² = 3² = 9 (مجال واحد في 3s، وثلاثة في 3p، وخمسة في 3d).', '["3 هو عدد المستويات الثانوية في المستوى الثالث.","18 هو أقصى عدد للإلكترونات في المستوى الثالث.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T11:15:01.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(257, 0, 'المستوى الثانوي p يتكون من 3 مجالات، وكل مجال يتسع لإلكترونين، فعندما يمتلئ يحتوي 6 إلكترونات.', '["","3 هو عدد مجالات p لا عدد إلكتروناته.","2 سعة المستوى الثانوي s أو المجال الواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(258, null, null, null, 'n = 1: 1s. n = 2: 2s، 2p. n = 3: 3s، 3p، 3d. n = 4: 4s، 4p، 4d، 4f. عدد المجالات وأقصى عدد للإلكترونات: s مجال واحد و2 إلكترون، p ثلاثة مجالات و6 إلكترونات، d خمسة مجالات و10 إلكترونات، f سبعة مجالات و14 إلكترونًا.', '["مستويات n = 1 و2","مستويات n = 3 و4","عدد مجالات s وp وd وf","سعة s وp وd وf من الإلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"المستويات الثانوية للمستويات الأربعة","marks":2},{"element":"عدد المجالات لكل نوع","marks":2},{"element":"أقصى عدد للإلكترونات لكل نوع","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"جميع العناصر صحيحة"},{"level":"4–5 درجات","description":"خطأ أو خطآن"},{"level":"2–3 درجات","description":"جزء واحد صحيح كاملًا"},{"level":"1 درجة","description":"معلومات متفرقة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ذكر 2d أو 3f","الخلط بين عدد المجالات وعدد الإلكترونات","عد سعة d تساوي 5"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.162Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(259, null, null, null, 'عدد المستويات الثانوية = n ، عدد المجالات = n² ، أقصى عدد للإلكترونات = 2n². التحقق لـ n = 3: المستويات الثانوية 3s و3p و3d أي 3 = n. المجالات: 1 + 3 + 5 = 9 = 3². الإلكترونات: 2 + 6 + 10 = 18 = 2 × 3².', '["عدد المستويات الثانوية = n","عدد المجالات = n²","أقصى عدد للإلكترونات = 2n²","التحقق: 3 مستويات، 9 مجالات، 18 إلكترونًا"]'::jsonb, '["المستويات الثانوية: 3s، 3p، 3d ← 3","المجالات: 1 + 3 + 5 = 9 = 3²","الإلكترونات: 2 + 6 + 10 = 18 = 2(3)²"]'::jsonb, '[{"element":"العلاقات الثلاث","marks":3},{"element":"التحقق للمستوى الثالث","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"علاقات صحيحة وتحقق مفصل"},{"level":"3–4 درجات","description":"علاقات صحيحة مع تحقق ناقص"},{"level":"1–2 درجة","description":"علاقة أو اثنتان"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين n² و2n²","جمع عدد المجالات بشكل خاطئ (1 + 3 + 5)","إضافة 3f إلى المستوى الثالث"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.162Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(260, null, null, null, '(1) خاطئة: المستوى الثاني يضم مستويين ثانويين فقط (2s و2p)؛ لأن عدد المستويات الثانوية يساوي n = 2، فلا يوجد 2d. (2) خاطئة: 7 هو عدد مجالات f، وكل مجال يتسع لإلكترونين، فسعته 14 إلكترونًا. (3) صحيحة: n = 1 يضم مستوى ثانويًا واحدًا هو 1s.', '["(1) خاطئة مع التصحيح: 2s و2p فقط","تعليل (1): عدد المستويات الثانوية = n","(2) خاطئة: السعة 14","تعليل (2): 7 مجالات × 2","(3) صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم العبارة (1) وتصحيحها","marks":2},{"element":"تقويم العبارة (2) وتصحيحها","marks":2},{"element":"تقويم العبارة (3)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم صحيح للثلاث مع التصحيح والتعليل"},{"level":"3–4 درجات","description":"تقويم صحيح مع نقص في التعليل"},{"level":"1–2 درجة","description":"تقويم عبارة واحدة صحيحًا"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قبول وجود 2d","قبول أن سعة f سبعة إلكترونات","عد العبارة (3) خاطئة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.162Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(261, 1, 'المجال s كروي الشكل حول النواة.', '["هذا شكل المجال p.","","ليس للمجال s شكل حلقي، فهو منطقة ثلاثية الأبعاد كروية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.164Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(262, 2, 'كل مجال من مجالات p على شكل فصين متقابلين (يشبه الدمبل) تقع النواة بينهما.', '["الشكل الكروي للمجال s.","المجالات مناطق ثلاثية الأبعاد لا دوائر مستوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.165Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(263, 0, 'للمستوى الثانوي p ثلاثة مجالات (px وpy وpz) يتجه كل منها على أحد المحاور الثلاثة x وy وz.', '["","هذا وصف المستوى الثانوي s.","خمسة مجالات بأشكال معقدة وصف المستوى الثانوي d."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.166Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(264, 0, 'جميع مجالات s كروية، ويزداد حجم المجال بزيادة رقم المستوى الرئيس n، فالمجال 2s أكبر من 1s.', '["","جميع مجالات s كروية مهما كان n.","الحجم يزداد بزيادة n، فـ 1s أصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.166Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
