(266, 1, 'المجال منطقة ثلاثية الأبعاد حول النواة تصف الموقع المحتمل للإلكترون، ويمثل شكله المنطقة التي يكون احتمال وجود الإلكترون فيها أكبر.', '["المجال ليس مسارًا؛ فلا يمكن تحديد مسار للإلكترون (مبدأ هايزنبرج).","","المجال يصف منطقة وجود الإلكترون لا حجمه ولا شكله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.166Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(267, 2, 'مجالات 2p الثلاثة متساوية في الطاقة والشكل والحجم، وتختلف فقط في اتجاهها على المحاور x وy وz.', '["مجالات المستوى الثانوي الواحد متساوية في الطاقة.","جميعها على شكل فصين وبالحجم نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.166Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(268, null, null, null, 'المجال s: كروي الشكل حول النواة، وللمستوى الثانوي s مجال واحد يتسع لإلكترونين. المجال p: على شكل فصين متقابلين تقع النواة بينهما، وللمستوى الثانوي p ثلاثة مجالات (px وpy وpz) متجهة على المحاور x وy وz، وتتسع لـ 6 إلكترونات.', '["s كروي","s: مجال واحد، 2 إلكترون","p فصّان","p: ثلاثة مجالات على المحاور، 6 إلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"شكل s","marks":1},{"element":"عدد مجالات s وسعته","marks":1},{"element":"شكل p","marks":1},{"element":"عدد مجالات p واتجاهاتها وسعته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"الشكلان فقط"},{"level":"1 درجة","description":"شكل واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["وصف s بأنه دائرة مستوية","ذكر أن لـ p مجالًا واحدًا","الخلط بين عدد المجالات والإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.166Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(269, null, null, null, 'الشكل: 1s و2s كرويان، و2px على شكل فصين. الحجم: 2s أكبر من 1s لأن الحجم يزداد بزيادة n، و2px في المستوى الرئيس الثاني نفسه مع 2s. الاتجاه: المجالان 1s و2s كرويان متماثلان حول النواة فليس لهما اتجاه محدد، أما 2px فيتجه على امتداد المحور x.', '["1s و2s كرويان، 2px فصّان","2s أكبر من 1s (زيادة n)","s بلا اتجاه محدد","2px على المحور x"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في الشكل","marks":2},{"element":"المقارنة في الحجم","marks":1},{"element":"المقارنة في الاتجاه","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة"},{"level":"3–4 درجات","description":"خطأ في جانب واحد"},{"level":"1–2 درجة","description":"جانب واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن 1s أكبر من 2s","إعطاء المجال s اتجاهًا محددًا","وصف 2px بأنه كروي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.167Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(270, null, null, null, 'يُرمز لها بذلك لأن مجالات p الثلاثة متماثلة الشكل (فصّان)، ويتجه كل منها على أحد المحاور الثلاثة المتعامدة x وy وz، فيدل الرمز السفلي على المحور. لا تختلف في الطاقة؛ فمجالات المستوى الثانوي الواحد متساوية الطاقة وتختلف في الاتجاه فقط. ويمثل شكل كل مجال المنطقة ثلاثية الأبعاد التي يكون احتمال وجود الإلكترون فيها كبيرًا.', '["الرمز يدل على المحور x أو y أو z","المجالات الثلاثة متساوية الطاقة","الاختلاف في الاتجاه فقط","الشكل يمثل منطقة احتمال وجود الإلكترون"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل الرموز","marks":2},{"element":"تساوي الطاقة","marks":1},{"element":"دلالة الشكل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"تعليل الرموز فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن pz أعلى طاقة","عد الشكل مسارًا للإلكترون","ربط الرموز بعدد الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.167Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
