(272, 2, 'المستوى الثانوي p فيه ثلاثة مجالات (فصية الشكل)، وكل مجال يتسع لإلكترونين على الأكثر، فالسعة 3 × 2 = 6.', '["عدد مجالات p ثلاثة لا ستة، والمجال الواحد يتسع لإلكترونين.","المجال الواحد لا يتسع لأكثر من إلكترونين، وعدد مجالات p ثلاثة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.169Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(273, 0, 'المستوى الثانوي f يتكون من 7 مجالات، وسعته 7 × 2 = 14 إلكترونًا لا 12؛ أما بقية الصفوف فصحيحة (p: 3 مجالات و6 إلكترونات، d: 5 مجالات و10 إلكترونات).', '["","صف d صحيح: 5 مجالات × 2 = 10 إلكترونات.","صف p صحيح: 3 مجالات × 2 = 6 إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.169Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(274, 1, 'نجمع سعات المستويات الثانوية: 3s (2) + 3p (6) + 3d (10) = 18 إلكترونًا، وهو ما يتفق مع العلاقة 2n² = 2 × 3² = 18.', '["8 هي مجموع سعتي s وp فقط (2 + 6) بإهمال المستوى الثانوي d.","","32 هي سعة المستوى الرابع الذي يحتوي إضافة إلى ذلك على المستوى f."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.170Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(275, 1, 'سعة المستوى الثانوي p القصوى 6 إلكترونات، فالرمز 3p⁷ مستحيل. أما 4f¹⁴ و3d¹⁰ فيمثلان مستويين ممتلئين تمامًا.', '["4f¹⁴ ممكن؛ سعة f القصوى 14 إلكترونًا.","","3d¹⁰ ممكن؛ سعة d القصوى 10 إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.170Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(276, 0, 'كل مجال يتسع لإلكترونين، فعدد المجالات = 14 ÷ 2 = 7 مجالات، وهذا هو المستوى الثانوي f.', '["","عُدّ كل إلكترون مجالًا مستقلًا، مع أن المجال يتسع لإلكترونين.","5 مجالات هي عدد مجالات المستوى d الذي سعته 10 إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.170Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(277, 2, 'سعة f = 14 إلكترونًا وسعة s = 2 إلكترونان، و14 ÷ 2 = 7 مرات (وهو أيضًا نسبة عدد المجالات 7 : 1).', '["3 هي نسبة سعة p إلى سعة s (6 ÷ 2).","5 هي نسبة سعة d إلى سعة s (10 ÷ 2).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.170Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(278, null, null, null, 's: مجال واحد، 2 إلكترون. p: 3 مجالات، 6 إلكترونات. d: 5 مجالات، 10 إلكترونات. f: 7 مجالات، 14 إلكترونًا. العلاقة: السعة القصوى للمستوى الثانوي = 2 × عدد مجالاته؛ لأن المجال الواحد يتسع لإلكترونين على الأكثر.', '["عدد مجالات s وp وd وf: 1، 3، 5، 7","السعات القصوى: 2، 6، 10، 14","العلاقة: السعة = 2 × عدد المجالات","التعليل: المجال يتسع لإلكترونين"]'::jsonb, '[]'::jsonb, '[{"element":"عدد المجالات الصحيح للمستويات الأربعة","marks":1},{"element":"السعات القصوى الصحيحة للمستويات الأربعة","marks":2},{"element":"كتابة العلاقة مع تعليلها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الجدول كامل صحيح والعلاقة مكتوبة ومعللة"},{"level":"3 درجات","description":"الجدول صحيح والعلاقة دون تعليل، أو خطأ في خلية واحدة"},{"level":"2 درجتان","description":"السعات صحيحة فقط أو المجالات صحيحة فقط"},{"level":"1 درجة","description":"سعة مستويين صحيحة فقط"},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة كليًا"}]'::jsonb, '["كتابة سعة f = 12 أو 16","الخلط بين عدد المجالات والسعة (كأن يكتب لـ p ستة مجالات)","كتابة السعة = عدد المجالات بدل ضعفه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.171Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(279, null, null, null, '(أ) الخطأ أن الطالب جعل عدد المجالات مساويًا لعدد الإلكترونات، مع أن المستوى d يحتوي على 5 مجالات فقط. (ب) العبارة الصحيحة: المستوى الثانوي d يتسع لعشرة إلكترونات لأنه يحتوي على خمسة مجالات يتسع كل منها لإلكترونين (5 × 2 = 10). (ج) المستوى p يحتوي على 3 مجالات، فسعته القصوى 3 × 2 = 6 إلكترونات.', '["تحديد الخطأ: الخلط بين عدد المجالات وعدد الإلكترونات","عدد مجالات d = 5","المجال يتسع لإلكترونين: 5 × 2 = 10","سعة p = 3 × 2 = 6"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تحديد الخطأ","marks":1},{"element":"(ب) التصحيح بعدد المجالات وسعة المجال","marks":2},{"element":"(ج) استنتاج سعة p","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ والتصحيح والاستنتاج كلها صحيحة"},{"level":"3 درجات","description":"التصحيح والاستنتاج صحيحان مع تحديد غير دقيق للخطأ"},{"level":"2 درجتان","description":"التصحيح صحيح فقط"},{"level":"1 درجة","description":"ذكر أن d يحتوي 5 مجالات دون تعليل"},{"level":"صفر","description":"لا إجابة أو تأييد عبارة الطالب"}]'::jsonb, '["تأييد عبارة الطالب","ذكر أن المجال الواحد يتسع لعدد غير محدد من الإلكترونات","كتابة سعة p = 3"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.171Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(280, null, null, null, '(أ) 4s (2) + 4p (6) + 4d (10) + 4f (14) = 32 إلكترونًا. (ب) 2n² = 2 × 4² = 2 × 16 = 32 إلكترونًا، وهي النتيجة نفسها. (ج) عدد المجالات = 1 + 3 + 5 + 7 = 16 مجالًا (= n² = 16)، وهو يساوي 32 ÷ 2.', '["سعات المستويات الثانوية 2، 6، 10، 14","المجموع 32 إلكترونًا","2n² = 32","عدد المجالات 16"]'::jsonb, '["4s + 4p + 4d + 4f = 2 + 6 + 10 + 14 = 32 إلكترونًا","2n² = 2 × (4)² = 32 إلكترونًا","عدد المجالات = 1 + 3 + 5 + 7 = 16 = n²"]'::jsonb, '[{"element":"(أ) الجمع الصحيح والناتج 32","marks":2},{"element":"(ب) التحقق بالعلاقة 2n²","marks":1},{"element":"(ج) عدد المجالات 16","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"3 درجات","description":"جزءان صحيحان وخطأ بسيط في الثالث"},{"level":"2 درجتان","description":"الجزء (أ) صحيح فقط"},{"level":"1 درجة","description":"كتابة سعات بعض المستويات الثانوية فقط"},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة"}]'::jsonb, '["حساب 2n² على أنها (2n)² = 64","إهمال المستوى الثانوي 4f والحصول على 18","كتابة عدد المجالات 32 بدل 16"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.171Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(281, 2, 'التوزيع الإلكتروني هو طريقة ترتيب الإلكترونات في مستويات الطاقة الرئيسية والثانوية والمجالات حول نواة الذرة.', '["هذا وصف لترتيب الجدول الدوري الحديث، لا لتوزيع الإلكترونات داخل الذرة.","هذا وصف لمكونات النواة؛ التوزيع الإلكتروني يخص الإلكترونات خارج النواة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.173Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(282, 0, 'تميل الإلكترونات إلى الترتيب الذي يجعل طاقة الذرة أقل ما يمكن، وهذا الترتيب الأكثر استقرارًا يسمى التوزيع الإلكتروني في الحالة المستقرة.', '["","الطاقة الأكبر تعني ذرة غير مستقرة (مثارة)، لا الحالة المستقرة.","مستويات الطاقة تختلف في طاقتها، فلا تكون الطاقة متساوية فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.174Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(283, 1, 'يتم التوزيع الإلكتروني وفق ثلاث قواعد: مبدأ أوفباو، ومبدأ باولي للاستبعاد، وقاعدة هوند.', '["هؤلاء العلماء أسهموا في تطور النموذج الذري، لا في قواعد توزيع الإلكترونات.","","هؤلاء العلماء أسهموا في تطور الجدول الدوري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.174Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(284, 1, 'عدد إلكترونات Na أحد عشر إلكترونًا، وتملأ المستويات الثانوية بالترتيب 1s ثم 2s ثم 2p ثم 3s، فيكون التوزيع 1s² 2s² 2p⁶ 3s¹.', '["المستوى 2p لم يمتلئ قبل الانتقال إلى 3s، فهذا توزيع لذرة مثارة.","","الإلكترون الأخير وُضع في 3p الأعلى طاقة بدل 3s، فهذا توزيع لذرة مثارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.175Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(285, 2, 'في الحالة المستقرة تكون طاقة الذرة أقل ما يمكن، فيُملأ 1s ثم 2s قبل 2p: 1s² 2s² 2p² (توزيع الطالب 3).', '["المستوى 2s لم يمتلئ (2s¹) مع وجود إلكترونات في 2p الأعلى طاقة، فهي ذرة مثارة.","تُرك المستوى 2s فارغًا ووُضعت الإلكترونات في 2p، وهذا لا يجعل الطاقة أقل ما يمكن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.175Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(286, 0, 'تشغل الإلكترونات المستويات الأقل طاقة أولًا، و4s أقل طاقة من 3d، فيُملأ 4s قبل 3d: K: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹.', '["","المستوى الثالث يتسع لـ 18 إلكترونًا، ولم يمتلئ بعد؛ المستوى 3d فارغ.","الرقم الأكبر للمستوى الرئيسي يعني عادة طاقة أكبر، فهذا لا يفسر ملء 4s أولًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.175Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(287, 1, 'مجموع الأسس 2 + 2 + 6 + 2 + 4 = 16 إلكترونًا، والأرقام 1 و2 و3 تعني أن ثلاثة مستويات رئيسية مشغولة.', '["المستوى الثالث يحتوي 3s² 3p⁴ أي 6 إلكترونات لا 4.","","خمسة هو عدد المستويات الثانوية المشغولة، أما الرئيسية فثلاثة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.176Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(288, null, null, null, '(أ) التوزيع الإلكتروني: ترتيب الإلكترونات في مستويات الطاقة الرئيسية والثانوية والمجالات حول نواة الذرة. (ب) هو الترتيب الأكثر استقرارًا الذي تكون فيه طاقة الذرة أقل ما يمكن، ويتم وفق قواعد أوفباو وباولي وهوند. (ج) Na₁₁: 1s² 2s² 2p⁶ 3s¹.', '["تعريف التوزيع الإلكتروني","ربط الحالة المستقرة بأقل طاقة ممكنة","ذكر القواعد الثلاث (إضافة)","توزيع Na الصحيح"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التعريف","marks":1},{"element":"(ب) الحالة المستقرة وأقل طاقة","marks":1},{"element":"(ج) توزيع الصوديوم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تعريف التوزيع الإلكتروني بأنه ترتيب العناصر في الجدول الدوري","ربط الحالة المستقرة بأكبر طاقة","كتابة 2p⁵ 3s² لذرة الصوديوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.176Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(289, null, null, null, '(أ) التوزيع (1): 2 + 2 + 6 + 2 = 12، والتوزيع (2): 2 + 2 + 6 + 1 + 1 = 12، فكلاهما يحتوي 12 إلكترونًا. (ب) التوزيع (1) هو الحالة المستقرة؛ لأن الإلكترونات تشغل المستويات الأقل طاقة أولًا، و3s أقل طاقة من 3p، فيجب أن يمتلئ 3s قبل وضع إلكترون في 3p، فتكون طاقة الذرة أقل ما يمكن. (ج) التوزيع (2) يمثل ذرة مثارة؛ انتقل فيها إلكترون من 3s إلى 3p الأعلى طاقة.', '["عدّ الإلكترونات في التوزيعين = 12","تحديد التوزيع (1) حالة مستقرة","التعليل بأن 3s أقل طاقة من 3p (أقل طاقة للذرة)","التوزيع (2) ذرة مثارة"]'::jsonb, '["(1): 2+2+6+2 = 12","(2): 2+2+6+1+1 = 12","المقارنة: 3s أقل طاقة من 3p"]'::jsonb, '[{"element":"(أ) التحقق من العدد","marks":1},{"element":"(ب) الاختيار الصحيح","marks":1},{"element":"(ب) التعليل","marks":1},{"element":"(ج) تسمية الذرة المثارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة مع تعليل سليم"},{"level":"3 درجات","description":"اختيار صحيح وتعليل ناقص"},{"level":"2 درجتان","description":"اختيار صحيح دون تعليل مع عدّ صحيح"},{"level":"1 درجة","description":"عدّ الإلكترونات فقط"},{"level":"صفر","description":"اختيار خاطئ دون مبرر أو لا إجابة"}]'::jsonb, '["اعتبار التوزيعين متكافئين لأن عدد الإلكترونات متساوٍ","الاعتقاد بأن توزيع الإلكترونات على مستويات أكثر يجعل الذرة أكثر استقرارًا","عدم معرفة مفهوم الذرة المثارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.176Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(290, null, null, null, '(أ) 2 + 2 + 6 + 2 + 5 = 17 إلكترونًا. (ب) ثلاثة مستويات رئيسية (n = 1، 2، 3). (ج) خمسة مستويات ثانوية (1s، 2s، 2p، 3s، 3p). (د) المستوى الخارجي n = 3 فيه 3s² 3p⁵ أي 7 إلكترونات.', '["العدد الكلي 17","3 مستويات رئيسية","5 مستويات ثانوية","7 إلكترونات في المستوى الخارجي"]'::jsonb, '["جمع الأسس: 2+2+6+2+5 = 17","المستويات الرئيسية: الأرقام المختلفة 1، 2، 3","المستويات الثانوية: عدد الرموز = 5","الخارجي: 3s² + 3p⁵ = 2 + 5 = 7"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة أجزاء صحيحة"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عدّ إلكترونات 3p فقط (5) في الجزء (د)","الخلط بين عدد المستويات الرئيسية والثانوية","جمع أرقام المستويات بدل الأسس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.176Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(291, 1, 'ينص مبدأ أوفباو على أن كل إلكترون يشغل المجال ذا الطاقة الأقل أولًا، فتملأ المستويات الثانوية بالترتيب التصاعدي لطاقتها.', '["هذا نص مبدأ باولي للاستبعاد.","","هذا نص قاعدة هوند."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.178Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(292, 0, 'حسب مبدأ أوفباو ومخطط الأقطار تملأ المستويات بالترتيب التصاعدي للطاقة: 1s 2s 2p 3s 3p 4s 3d، و4s أقل طاقة من 3d.', '["","وُضع 3d قبل 4s، مع أن 4s أقل طاقة من 3d فيُملأ قبله.","وُضع 3s قبل 2p، مع أن 2p أقل طاقة من 3s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.179Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(293, 2, 'ترتيب الملء: ... 3p ثم 4s ثم 3d ثم 4p؛ فبعد امتلاء 4s يبدأ ملء 3d لأنه التالي في الطاقة.', '["4p يأتي بعد 3d في ترتيب الطاقة.","4d أعلى طاقة بكثير، ويأتي بعد 5s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.179Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(294, 0, 'كلمة «أوفباو» تعني البناء التصاعدي، لأن الإلكترونات تبني التوزيع بدءًا من المستوى الأقل طاقة صعودًا.', '["","«الاستبعاد» هو اسم مبدأ باولي.","«عدم التأكد» هو مبدأ هايزنبرج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.179Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(295, 1, 'جميع مجالات المستوى الثانوي الواحد متساوية في الطاقة، فمجالات 2p الثلاثة لها الطاقة نفسها.', '["مجالات المستوى الثانوي الواحد لا تختلف في الطاقة.","","مجالات المستوى الثانوي الواحد لا تختلف في الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.179Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(296, 2, 'في التوزيع الثالث وُضع إلكترونان في 3d مع بقاء 4s الأقل طاقة فارغًا، وهذا يخالف مبدأ أوفباو. التوزيعان الآخران يتبعان ترتيب الملء الصحيح (4s قبل 3d).', '["توزيع صحيح (Ca₂₀): امتلأ 4s بعد 3p.","توزيع صحيح (Sc₂₁): امتلأ 4s قبل البدء في 3d.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.179Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(297, 1, 'الترتيب حسب مخطط الأقطار: 1s، 2s، 2p، 3s، 3p، 4s، 3d، 4p، 5s، 4d؛ فالمستوى السابع هو 3d.', '["4d يأتي بعد 5s (الترتيب العاشر).","","5p يأتي بعد 4d، فهو بعد الترتيب العاشر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.180Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(298, null, null, null, '(أ) ينص مبدأ أوفباو على أن كل إلكترون يشغل المجال ذا الطاقة الأقل أولًا. (ب) تملأ المستويات بالترتيب 1s ثم 2s ثم 2p ثم 3s ثم 3p: Ar₁₈: 1s² 2s² 2p⁶ 3s² 3p⁶ (مجموع الإلكترونات 2 + 2 + 6 + 2 + 6 = 18).', '["نص المبدأ: الإلكترون يشغل المجال الأقل طاقة أولًا","ترتيب الملء 1s 2s 2p 3s 3p","التوزيع الصحيح لـ Ar","التحقق من مجموع 18 إلكترونًا"]'::jsonb, '["الترتيب: 1s → 2s → 2p → 3s → 3p","الملء: 1s² 2s² 2p⁶ 3s² 3p⁶","المجموع = 18"]'::jsonb, '[{"element":"(أ) نص المبدأ","marks":2},{"element":"(ب) ترتيب الملء","marks":1},{"element":"(ب) التوزيع الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص صحيح وتوزيع صحيح بترتيب سليم"},{"level":"3 درجات","description":"نص صحيح وتوزيع فيه خطأ بسيط في الأسس"},{"level":"2 درجتان","description":"نص صحيح فقط أو توزيع صحيح فقط"},{"level":"1 درجة","description":"نص ناقص (مثل «الإلكترونات تملأ المستويات بالترتيب» دون ذكر الطاقة)"},{"level":"صفر","description":"لا إجابة أو نص مبدأ آخر"}]'::jsonb, '["كتابة نص مبدأ باولي أو قاعدة هوند بدل أوفباو","إهمال ذكر «الطاقة الأقل» في النص","كتابة 3p⁸ بتجاوز سعة p"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.180Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(299, null, null, null, 'الترتيب: 3p ثم 4s ثم 3d ثم 4p ثم 5s. التفسير: يعتمد ترتيب الملء على طاقة المستوى الثانوي لا على رقم المستوى الرئيسي وحده، وطاقة 4s أقل من طاقة 3d، فيشغله الإلكترون أولًا حسب مبدأ أوفباو (الإلكترون يشغل المجال الأقل طاقة أولًا).', '["الترتيب الصحيح 3p، 4s، 3d، 4p، 5s","طاقة 4s أقل من 3d","الربط بنص مبدأ أوفباو","ترتيب الملء يعتمد على الطاقة لا على رقم n وحده"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":2},{"element":"التفسير بالطاقة ومبدأ أوفباو","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتفسير كامل"},{"level":"3 درجات","description":"ترتيب صحيح وتفسير ناقص، أو خطأ في موضع واحد مع تفسير كامل"},{"level":"2 درجتان","description":"ترتيب صحيح دون تفسير"},{"level":"1 درجة","description":"ترتيب فيه أكثر من خطأ مع ذكر أن 4s أقل طاقة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الترتيب حسب رقم المستوى الرئيسي (3p، 3d، 4s، 4p، 5s)","تفسير الأسبقية بأن 4s أقرب إلى النواة","وضع 5s قبل 4p"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.180Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(300, null, null, null, '(أ) غير صحيح. (ب) خالف مبدأ أوفباو؛ لأنه وضع الإلكترون الأخير في 3d مع أن المستوى 4s أقل طاقة منه ولم يُشغل بعد، والإلكترون يشغل المجال الأقل طاقة أولًا. (ج) K₁₉: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹.', '["الحكم بعدم الصحة","تسمية مبدأ أوفباو","التوضيح: 4s أقل طاقة من 3d","التوزيع الصحيح 4s¹"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الحكم","marks":1},{"element":"(ب) تسمية المبدأ مع التوضيح","marks":2},{"element":"(ج) التوزيع الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم وتسمية وتوضيح وتصحيح كاملة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"الحكم والتصحيح دون تسمية المبدأ"},{"level":"1 درجة","description":"الحكم فقط"},{"level":"صفر","description":"تأييد توزيع الطالب"}]'::jsonb, '["تسمية مبدأ باولي أو قاعدة هوند","الاعتقاد بأن 3d يُملأ قبل 4s لأن رقمه الرئيسي أصغر","كتابة 4s² بزيادة عدد الإلكترونات إلى 20"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.180Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(301, 2, 'ينص مبدأ باولي على أن المجال الواحد لا يتسع لأكثر من إلكترونين، ويجب أن يكون اتجاها دورانهما متعاكسين.', '["هذا نص مبدأ أوفباو.","هذا نص قاعدة هوند.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.182Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(302, 0, 'حسب مبدأ باولي لا يتسع أي مجال لأكثر من إلكترونين مهما كان نوعه؛ أما الرقم 6 فهو سعة المستوى الثانوي p كاملًا (3 مجالات).', '["","6 هي سعة المستوى الثانوي p كله، لا المجال الواحد (خلط بين المجال والمستوى الثانوي).","3 هو عدد مجالات p، لا سعة المجال الواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.183Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(303, 1, 'يجب أن يكون الإلكترونان في المجال الواحد متعاكسين في اتجاه الدوران (↑↓)، فالسهمان في الاتجاه نفسه (↑↑) يخالفان مبدأ باولي.', '["مجال بإلكترون مفرد لا يخالف المبدأ؛ فالمجال يتسع لإلكترون أو إلكترونين.","","هذا هو التمثيل الصحيح لمجال ممتلئ حسب مبدأ باولي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.183Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(304, 0, 'كل مجال يتسع لإلكترونين على الأكثر، فالسعة = 7 × 2 = 14 إلكترونًا (المستوى الثانوي f).', '["","افتُرض أن المجال يتسع لإلكترون واحد فقط.","افتُرض أن المجال يتسع لأربعة إلكترونات، وهذا يخالف مبدأ باولي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.183Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(305, 2, 'التمثيل (1) فيه إلكترونان متعاكسان في الدوران (↑↓)، وهو ما يشترطه مبدأ باولي.', '["الإلكترونان في الاتجاه نفسه (↑↑)، وهذا يخالف مبدأ باولي.","الإلكترونان في الاتجاه نفسه (↓↓)، وهذا يخالف مبدأ باولي أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.184Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(306, 0, 'أقصى ما يتسع له المجال إلكترونان، فأقل عدد من المجالات = 8 ÷ 2 = 4 مجالات (مثل 2s وثلاثة مجالات 2p في المستوى الثاني).', '["","افتُرض أن كل مجال يحمل إلكترونًا واحدًا فقط.","افتُرض أن المجال يتسع لأربعة إلكترونات، وهذا يخالف مبدأ باولي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.184Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(307, 1, 'وُضع في المجال الواحد ثلاثة إلكترونات، ومبدأ باولي لا يسمح بأكثر من إلكترونين في المجال الواحد؛ والصحيح 1s [↑↓] 2s [↑].', '["قاعدة هوند تخص توزيع الإلكترونات على مجالات متعددة متساوية الطاقة، والمقصود هنا مجال واحد.","","المخالفة الأساسية هي تجاوز سعة المجال (إلكترونان)، وهذا ما يحدده مبدأ باولي لا مبدأ أوفباو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.185Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(308, null, null, null, '(أ) لا يتسع المجال الواحد لأكثر من إلكترونين، ويجب أن يكون اتجاها دورانهما متعاكسين (↑↓). (ب) بما أن المجال يتسع لإلكترونين على الأكثر فسعة المستوى الثانوي = 2 × عدد مجالاته: s (مجال واحد) = 2، p (3 مجالات) = 6، d (5 مجالات) = 10، f (7 مجالات) = 14.', '["المجال يتسع لإلكترونين على الأكثر","الإلكترونان متعاكسان في الدوران","عدد مجالات s وp وd وf: 1، 3، 5، 7","السعة = 2 × عدد المجالات"]'::jsonb, '["s: 1 × 2 = 2","p: 3 × 2 = 6","d: 5 × 2 = 10","f: 7 × 2 = 14"]'::jsonb, '[{"element":"(أ) الحد الأقصى إلكترونان","marks":1},{"element":"(أ) تعاكس الدوران","marks":1},{"element":"(ب) الاستنتاج بعدد المجالات","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"نص كامل واستنتاج صحيح للسعات الأربع"},{"level":"3 درجات","description":"نص ناقص (دون تعاكس الدوران) واستنتاج صحيح"},{"level":"2 درجتان","description":"نص كامل دون استنتاج، أو استنتاج صحيح دون نص"},{"level":"1 درجة","description":"ذكر أن المجال يتسع لإلكترونين فقط"},{"level":"صفر","description":"لا إجابة أو نص قاعدة أخرى"}]'::jsonb, '["إغفال شرط تعاكس الدوران","الخلط بين المجال والمستوى الثانوي","كتابة نص قاعدة هوند"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.185Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(309, null, null, null, '(أ) مبدأ باولي للاستبعاد. (ب) وضع الطالب في كل مجال إلكترونين لهما اتجاه الدوران نفسه، والمبدأ يشترط أن يكون الإلكترونان في المجال الواحد متعاكسين في الدوران. (ج) 1s [↑↓]  2s [↑↓].', '["تسمية مبدأ باولي","الإلكترونان في المجال يجب أن يكونا متعاكسين","الرسم الصحيح ↑↓ في كل مجال"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تسمية المبدأ","marks":1},{"element":"(ب) التوضيح","marks":1},{"element":"(ج) الرسم الصحيح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تسمية قاعدة هوند","الاعتقاد بأن العدد هو المشكلة لا اتجاه الدوران","رسم ↑ ↓ في مجالين مختلفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.185Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(310, null, null, null, '(أ) المجالات: 1s (1) + 2s (1) + 2p (3) = 5 مجالات ممتلئة. (ب) 5 مجالات × 2 إلكترون = 10 إلكترونات، وهو العدد الذري للنيون، فكل مجال يحتوي على إلكترونين متعاكسين فقط. (ج) 10 ÷ 3 ≈ 3.3، أي يلزم 4 مجالات (ثلاثة ممتلئة ورابع فيه إلكترون واحد)، وهذا يغير توزيع الذرة كله؛ فمبدأ باولي هو الذي يحدد سعة المجالات والمستويات وبالتالي التوزيع الإلكتروني.', '["عدد المجالات 5","5 × 2 = 10","حساب 4 مجالات في الحالة الافتراضية","استنتاج أن المبدأ يحدد السعات والتوزيع"]'::jsonb, '["عدد المجالات = 1 + 1 + 3 = 5","الإلكترونات = 5 × 2 = 10","افتراضيًا: 10 ÷ 3 = 3.3 → 4 مجالات"]'::jsonb, '[{"element":"(أ) عدد المجالات","marks":1},{"element":"(ب) التحقق","marks":1},{"element":"(ج) الحساب","marks":1},{"element":"(ج) الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة مع استنتاج سليم"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"(أ) و(ب) فقط"},{"level":"1 درجة","description":"عدد المجالات فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عدّ المستويات الثانوية (3) بدل المجالات (5)","عدّ 2p مجالًا واحدًا","تقريب 3.3 إلى 3 مجالات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.185Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(311, 0, 'تنص قاعدة هوند على أن الإلكترونات المفردة ذات اتجاه الدوران المتماثل تشغل المجالات المتساوية في الطاقة كلًا على حدة قبل أن تبدأ الإلكترونات ذات الدوران المعاكس في الازدواج.', '["","هذا نص مبدأ باولي.","هذا نص مبدأ أوفباو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.187Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(312, 2, 'حسب قاعدة هوند يوضع إلكترون مفرد في كل مجال من المجالات الثلاثة أولًا، وتكون الإلكترونات المفردة متماثلة في اتجاه الدوران: [↑][↑][↑].', '["بدأ الازدواج في المجال الأول قبل أن يحصل كل مجال على إلكترون.","الإلكترونات المفردة يجب أن تكون متماثلة في اتجاه الدوران، وهنا أحدها معاكس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.188Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(313, 1, 'الإلكترونات سالبة الشحنة يتنافر بعضها مع بعض، فتتوزع على المجالات المتساوية الطاقة أولًا لتقليل التنافر.', '["الإلكترونات متشابهة الشحنة فتتنافر ولا تتجاذب.","","مجالات المستوى الثانوي الواحد متساوية في الطاقة، فلا يوجد مجال أقل طاقة من الآخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.188Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(314, 2, 'يوضع إلكترون في كل مجال أولًا (3 إلكترونات بالدوران نفسه)، ثم يزدوج الرابع في المجال الأول: [↑↓][↑][↑].', '["تُرك مجال فارغًا مع ازدواج مجالين، وهذا يخالف قاعدة هوند.","الإلكترونان المفردان يجب أن يكونا متماثلين في الدوران.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.188Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(315, 0, '2p⁴: [↑↓][↑][↑]؛ مجال واحد ممتلئ ومجالان في كل منهما إلكترون مفرد، فعدد الإلكترونات المفردة 2.', '["","عُدّت الإلكترونات الأربعة كلها مفردة، مع أن المجال يتسع لثلاثة فقط منفردة ثم يبدأ الازدواج.","افتُرض ازدواج كل الإلكترونات في مجالين، وهذا يخالف قاعدة هوند."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.188Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(316, 2, 'قاعدة هوند تقتضي وضع كل إلكترون في مجال مستقل مع تماثل اتجاه الدوران: [↑][↑][  ] وهو تمثيل الطالب (3).', '["ازدوج الإلكترونان في مجال واحد مع وجود مجالات فارغة متساوية الطاقة.","الإلكترونان في مجالين مختلفين لكن باتجاهي دوران متعاكسين، والقاعدة تشترط تماثل الدوران.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.189Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(317, 1, 'مجالات d خمسة؛ توضع 5 إلكترونات منفردة أولًا، ثم تزدوج الثلاثة الباقية في ثلاثة مجالات: [↑↓][↑↓][↑↓][↑][↑]، فيبقى إلكترونان مفردان.', '["4 إلكترونات مفردة تناسب d⁶ لا d⁸.","","افتُرض ازدواج الإلكترونات الثمانية في أربعة مجالات وترك مجال فارغ، وهذا يخالف قاعدة هوند."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.189Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(318, null, null, null, '(أ) الإلكترونات المفردة ذات اتجاه الدوران المتماثل تشغل المجالات المتساوية في الطاقة كلًا على حدة قبل أن تبدأ الإلكترونات ذات الدوران المعاكس في الازدواج في المجالات نفسها. (ب) لأن الإلكترونات سالبة الشحنة يتنافر بعضها مع بعض، فتوزعها على مجالات منفصلة يقلل التنافر. (ج) 2p³: [↑][↑][↑].', '["نص القاعدة: الإلكترونات المفردة تشغل المجالات المتساوية الطاقة أولًا","تماثل اتجاه الدوران للإلكترونات المفردة","التفسير بالتنافر","الرسم الصحيح ↑ ↑ ↑"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) نص القاعدة","marks":2},{"element":"(ب) التفسير","marks":1},{"element":"(ج) الرسم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص كامل وتفسير صحيح ورسم صحيح"},{"level":"3 درجات","description":"نص دون ذكر تماثل الدوران مع تفسير ورسم صحيحين"},{"level":"2 درجتان","description":"رسم صحيح مع نص ناقص"},{"level":"1 درجة","description":"رسم صحيح فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة نص مبدأ باولي","رسم [↑↓][↑][  ]","رسم الإلكترونات المفردة باتجاهات مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.189Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(319, null, null, null, '(أ) رسم الطالب (ب) صحيح. (ب) حسب قاعدة هوند تشغل الإلكترونات المفردة المتماثلة الدوران المجالات المتساوية الطاقة كلًا على حدة قبل الازدواج؛ والطالب (أ) جعل إلكترونين يزدوجان مع بقاء مجال فارغ مساوٍ في الطاقة. (ج) 3 إلكترونات مفردة.', '["اختيار رسم الطالب (ب)","التعليل: لا ازدواج قبل أن يشغل كل مجال إلكترونًا","تماثل الدوران","3 إلكترونات مفردة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الاختيار","marks":1},{"element":"(ب) التعليل","marks":2},{"element":"(ج) عدد الإلكترونات المفردة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اختيار صحيح وتعليل كامل وعدد صحيح"},{"level":"3 درجات","description":"اختيار صحيح وتعليل ناقص"},{"level":"2 درجتان","description":"اختيار صحيح وعدد صحيح دون تعليل"},{"level":"1 درجة","description":"اختيار صحيح فقط"},{"level":"صفر","description":"اختيار خاطئ"}]'::jsonb, '["اختيار رسم (أ) لأنه «يملأ المجال الأول أولًا»","تسمية مبدأ باولي بدل قاعدة هوند","عدّ إلكترون مفرد واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.189Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(320, null, null, null, '(أ) d⁶: توضع 5 إلكترونات منفردة متماثلة الدوران في المجالات الخمسة، ثم يزدوج السادس في المجال الأول: [↑↓][↑][↑][↑][↑]، عدد الإلكترونات المفردة = 4. (ب) f¹²: توضع 7 إلكترونات منفردة، ثم تزدوج 5 إلكترونات في خمسة مجالات: [↑↓][↑↓][↑↓][↑↓][↑↓][↑][↑]، عدد الإلكترونات المفردة = 2.', '["رسم d⁶ الصحيح","4 إلكترونات مفردة في d⁶","رسم f¹² الصحيح","إلكترونان مفردان في f¹²"]'::jsonb, '["d⁶: 5 منفردة + 1 مزدوج ← مفردة = 5 − 1 = 4","f¹²: 7 منفردة + 5 مزدوجة ← مفردة = 7 − 5 = 2"]'::jsonb, '[{"element":"(أ) الرسم","marks":1},{"element":"(أ) عدد المفردة","marks":1},{"element":"(ب) الرسم","marks":1},{"element":"(ب) عدد المفردة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الرسمان والعددان صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"حالة واحدة كاملة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ملء المجالات أزواجًا من البداية","رسم 6 مجالات لـ d أو 6 لـ f","إهمال تماثل اتجاه الدوران"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.190Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(321, 0, 'عدد إلكترونات B خمسة: 1s² (2) ثم 2s² (2) ثم 2p¹ (1).', '["","المستوى s لا يتسع لأكثر من إلكترونين، فلا يمكن كتابة 2s³.","تُرك المستوى 2s الأقل طاقة فارغًا، وهذا يخالف ترتيب الملء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:01.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(322, 1, 'عدد الإلكترونات 15: 1s² 2s² 2p⁶ 3s² 3p³ (2 + 2 + 6 + 2 + 3 = 15).', '["مجموع الإلكترونات 17، وهذا توزيع الكلور.","","أُهمل المستوى 3s الذي يُملأ قبل 3p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:01.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(323, 2, 'بعد 3p⁶ (18 إلكترونًا) يُملأ 4s² لأنه أقل طاقة من 3d، ثم توضع الإلكترونات الستة الباقية في 3d: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d⁶.', '["أُهمل 4s ووُضعت ثمانية إلكترونات في 3d.","وُضع إلكترونان في 4p قبل امتلاء 4s و3d.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:01.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(324, 0, 'مجموع الأسس: 2 + 2 + 6 + 2 + 6 + 2 + 10 + 5 = 35، فالعنصر عدده الذري 35 وهو البروم.', '["","الكلور له 17 إلكترونًا وينتهي توزيعه بـ 3p⁵.","الكريبتون له 36 إلكترونًا وينتهي توزيعه بـ 4p⁶."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(325, 2, 'توزيع الكبريت المكتوب يحتوي 2 + 2 + 6 + 2 + 6 = 18 إلكترونًا، والصحيح 1s² 2s² 2p⁶ 3s² 3p⁴ (16 إلكترونًا).', '["توزيع Mg صحيح: 2 + 2 + 6 + 2 = 12.","توزيع Ni صحيح: 18 + 2 + 8 = 28 مع ملء 4s قبل 3d.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(326, 1, 'Ni₂₈: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d⁸؛ بعد 20 إلكترونًا حتى 4s² يبقى 28 − 20 = 8 إلكترونات في 3d.', '["10 سعة 3d القصوى، ولا يمتلئ في النيكل.","","2 عدد إلكترونات 4s لا 3d."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.193Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(327, 0, 'في الترميز الإلكتروني: الرقم الأول (2) رقم المستوى الرئيسي، والحرف (p) نوع المستوى الثانوي، والأس (6) عدد الإلكترونات فيه.', '["","عدد مجالات p ثلاثة، والأس يعبر عن الإلكترونات.","رقم المستوى الرئيسي هو الرقم 2 المكتوب قبل الحرف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.194Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(328, null, null, null, '(أ) Mg₁₂: 1s² 2s² 2p⁶ 3s² ، المجموع 2 + 2 + 6 + 2 = 12. (ب) P₁₅: 1s² 2s² 2p⁶ 3s² 3p³ ، المجموع 2 + 2 + 6 + 2 + 3 = 15.', '["توزيع Mg الصحيح","توزيع P الصحيح","التحقق بالجمع"]'::jsonb, '["Mg: 1s² 2s² 2p⁶ 3s² ← 12","P: 1s² 2s² 2p⁶ 3s² 3p³ ← 15"]'::jsonb, '[{"element":"توزيع Mg","marks":1},{"element":"توزيع P","marks":1},{"element":"التحقق بالجمع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التوزيعان صحيحان مع التحقق"},{"level":"2 درجتان","description":"التوزيعان صحيحان دون تحقق"},{"level":"1 درجة","description":"توزيع واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة 2p⁸ بتجاوز سعة p","وضع الإلكترونات في 3p قبل امتلاء 3s","الخطأ في الجمع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.194Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(329, null, null, null, '(أ) Fe₂₆: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d⁶. (ب) لأن طاقة 4s أقل من طاقة 3d، والإلكترونات تشغل المستويات الأقل طاقة أولًا (مبدأ أوفباو). (ج) المستوى الثالث: 3s² 3p⁶ 3d⁶ = 2 + 6 + 6 = 14 إلكترونًا.', '["التوزيع الصحيح لـ Fe","التفسير بطاقة 4s الأقل","14 إلكترونًا في المستوى الثالث"]'::jsonb, '["التوزيع حتى 3p⁶ = 18 إلكترونًا، ثم 4s² = 20، ثم 3d⁶ = 26","n = 3: 3s² + 3p⁶ + 3d⁶ = 14"]'::jsonb, '[{"element":"(أ) التوزيع","marks":2},{"element":"(ب) التفسير","marks":1},{"element":"(ج) العدد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة"},{"level":"3 درجات","description":"التوزيع صحيح مع خطأ في (ب) أو (ج)"},{"level":"2 درجتان","description":"التوزيع صحيح فقط"},{"level":"1 درجة","description":"توزيع فيه خطأ واحد مع تفسير صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة 3d⁸ دون 4s","نسيان 3d عند عدّ إلكترونات المستوى الثالث (8 بدل 14)","تفسير الترتيب برقم المستوى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.194Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(330, null, null, null, '(أ) 2 + 2 + 6 + 2 + 6 + 1 = 19 (البوتاسيوم). (ب) 6 مستويات ثانوية: 1s، 2s، 2p، 3s، 3p، 4s. (ج) Y₂₀: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s². (د) Z = 21: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹.', '["العدد الذري 19","6 مستويات ثانوية","توزيع العنصر 20","توزيع العنصر 21 بإضافة 3d¹"]'::jsonb, '["جمع الأسس = 19","عدّ الرموز = 6","Z = 20: إكمال 4s²","Z = 21: الإلكترون التالي في 3d"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة أجزاء صحيحة"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة 4p¹ للعنصر 21 بدل 3d¹","عدّ المستويات الرئيسية (4) بدل الثانوية","الخطأ في جمع الأسس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.195Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(331, 2, 'النيون Ne₁₀ توزيعه 1s² 2s² 2p⁶، فالرمز [Ne] يختصر هذه الإلكترونات العشرة.', '["هذا توزيع المغنيسيوم (12 إلكترونًا) لا النيون.","هذا توزيع الأكسجين (8 إلكترونات).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.196Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(332, 1, 'Al₁₃: 1s² 2s² 2p⁶ 3s² 3p¹؛ الإلكترونات العشرة الأولى تُختصر بـ [Ne] فيصبح [Ne] 3s² 3p¹.', '["الأرجون (18 إلكترونًا) أكبر من العدد الذري للألومنيوم، فلا يمكن استخدامه.","","أُهمل المستوى 3s الذي يُملأ قبل 3p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(333, 0, 'يُستخدم الغاز النبيل الذي يسبق العنصر مباشرة في الجدول الدوري؛ قبل الكالسيوم (20) يأتي الأرجون (18): Ca: [Ar] 4s².', '["","النيون يسبق الكالسيوم لكنه ليس الأقرب؛ فيبقى جزء من الإلكترونات الداخلية غير مختصر.","الكريبتون (36) عدده الذري أكبر من الكالسيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(334, 2, 'Zn₃₀: بعد الأرجون (18) يُملأ 4s² ثم 3d¹⁰: 18 + 2 + 10 = 30، فالتوزيع [Ar] 4s² 3d¹⁰.', '["الكريبتون (36) أكبر من العدد الذري للخارصين.","وُضع إلكترونان في 4p قبل ملء 4s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(335, 1, 'أقرب غاز نبيل يسبق Sr (38) هو الكريبتون (36)، ويتبقى إلكترونان يدخلان 5s لأنه أقل طاقة من 4d: [Kr] 5s².', '["[Ar] يختصر 18 إلكترونًا فقط، و5s² لا يكمل العدد إلى 38.","","5s أقل طاقة من 4d فيُملأ قبله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(336, 0, 'طريقة الغاز النبيل (المختصرة) تستبدل بالإلكترونات الداخلية رمز الغاز النبيل السابق للعنصر بين قوسين، فيختصر التوزيع ويُبرز الإلكترونات الخارجية.', '["","الغازات النبيلة مستقرة ولا تفقد إلكتروناتها بسهولة.","عدد البروتونات هو العدد الذري، ولا يُعرض بهذه الطريقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.198Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
