(338, null, null, null, 'Na₁₁: [Ne] 3s¹. Cl₁₇: [Ne] 3s² 3p⁵. K₁₉: [Ar] 4s¹. نختار الغاز النبيل الذي يسبق العنصر مباشرة (عدده الذري أقل من العدد الذري للعنصر وأقرب إليه)، ونكتب رمزه بين قوسين ثم نكمل توزيع الإلكترونات الباقية.', '["Na: [Ne] 3s¹","Cl: [Ne] 3s² 3p⁵","K: [Ar] 4s¹","قاعدة اختيار الغاز النبيل السابق"]'::jsonb, '["Na: 11 − 10 = 1 ← 3s¹","Cl: 17 − 10 = 7 ← 3s² 3p⁵","K: 19 − 18 = 1 ← 4s¹"]'::jsonb, '[{"element":"توزيع Na","marks":1},{"element":"توزيع Cl","marks":1},{"element":"توزيع K","marks":1},{"element":"توضيح طريقة الاختيار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التوزيعات الثلاثة صحيحة مع توضيح الطريقة"},{"level":"3 درجات","description":"التوزيعات صحيحة دون توضيح"},{"level":"2 درجتان","description":"توزيعان صحيحان"},{"level":"1 درجة","description":"توزيع واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام [Ar] للكلور","كتابة K: [Ne] 3s¹","نسيان القوسين حول رمز الغاز النبيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.198Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(339, null, null, null, '(أ) الغاز النبيل الذي يسبق الجاليوم هو الأرجون Ar₁₈ وتوزيعه 1s² 2s² 2p⁶ 3s² 3p⁶، فنستبدل به هذا الجزء: Ga: [Ar] 4s² 3d¹⁰ 4p¹. (ب) [Ar] يمثل 18 إلكترونًا، ويكتب بعده 31 − 18 = 13 إلكترونًا (2 + 10 + 1).', '["تحديد الأرجون","الاستبدال الصحيح","التوزيع [Ar] 4s² 3d¹⁰ 4p¹","18 و13 إلكترونًا"]'::jsonb, '["الغاز النبيل السابق: Ar (18)","استبدال 1s² 2s² 2p⁶ 3s² 3p⁶ بـ [Ar]","الباقي: 31 − 18 = 13 = 4s² 3d¹⁰ 4p¹"]'::jsonb, '[{"element":"(أ) تحديد الغاز النبيل","marks":1},{"element":"(أ) التوزيع المختصر","marks":2},{"element":"(ب) الأعداد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة"},{"level":"3 درجات","description":"التوزيع صحيح مع خطأ في (ب)"},{"level":"2 درجتان","description":"تحديد Ar مع توزيع ناقص"},{"level":"1 درجة","description":"تحديد الغاز النبيل فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام [Kr]","حذف 3d¹⁰ ظنًا أنه ضمن [Ar]","كتابة 13 إلكترونًا في 4p"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.198Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(340, null, null, null, '(1) خاطئ؛ الأرجون (18) عدده الذري أكبر من المغنيسيوم (12)، والصحيح [Ne] 3s². (2) صحيح؛ 18 + 2 + 10 + 4 = 34. (3) عدد الإلكترونات صحيح (10 + 2 + 6 + 2 + 6 = 26) لكنه غير مختصر بالشكل الأمثل؛ لأن الغاز النبيل السابق مباشرة هو الأرجون، والأفضل [Ar] 4s² 3d⁶.', '["(1) خاطئ مع التصحيح [Ne] 3s²","(2) صحيح مع التحقق","(3) غير أمثل مع التصحيح [Ar] 4s² 3d⁶"]'::jsonb, '["(1): 18 > 12 ← [Ne] 3s²","(2): 18 + 2 + 10 + 4 = 34","(3): 10 + 2 + 6 + 2 + 6 = 26 ← [Ar] 4s² 3d⁶"]'::jsonb, '[{"element":"تقويم (1) وتصحيحه","marks":2},{"element":"تقويم (2)","marks":1},{"element":"تقويم (3) وتصحيحه","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تقويم صحيح للثلاثة مع التعليل والتصحيح"},{"level":"3–4 درجات","description":"تقويم صحيح لاثنين مع تعليل"},{"level":"1–2 درجة","description":"تقويم صحيح لواحد"},{"level":"صفر","description":"لا إجابة أو تقويمات خاطئة"}]'::jsonb, '["قبول التوزيع (1) لأن الأسس صحيحة","اعتبار التوزيع (3) خاطئًا علميًا بدل غير مختصر","عدم التحقق بجمع الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.199Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(341, 1, 'Li₃: 1s² 2s¹؛ يمتلئ 1s بإلكترونين متعاكسين (↑↓) ثم يوضع الإلكترون الثالث في 2s.', '["الإلكترونان في 1s في الاتجاه نفسه، وهذا يخالف مبدأ باولي.","","المستوى 1s الأقل طاقة يجب أن يمتلئ قبل 2s (مبدأ أوفباو)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.200Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(342, 2, 'F₉: 1s² 2s² 2p⁵؛ يمتلئ 1s و2s، ثم توزع خمسة إلكترونات على ثلاثة مجالات 2p: [↑↓][↑↓][↑].', '["لم يمتلئ 2s قبل 2p، وهذا يخالف مبدأ أوفباو.","رُسمت أربعة مربعات للمستوى 2p مع أنه ثلاثة مجالات فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.201Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(343, 0, 'Al₁₃: 1s² 2s² 2p⁶ 3s² 3p¹؛ المجالات المشغولة: 1s (1) + 2s (1) + 2p (3) + 3s (1) + 3p (1) = 7 مجالات.', '["","5 هو عدد المستويات الثانوية المشغولة لا المجالات.","13 هو عدد الإلكترونات؛ المجال يتسع لإلكترونين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.201Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(344, 1, 'Cl₁₇: ... 3s [↑↓] 3p [↑↓][↑↓][↑]؛ جميع المجالات ممتلئة عدا مجال واحد في 3p فيه إلكترون مفرد.', '["3 إلكترونات مفردة توافق p³ (مثل الفوسفور) لا p⁵.","","5 هو عدد إلكترونات 3p، وأربعة منها مزدوجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.201Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(345, 0, 'في النيتروجين ثلاثة مجالات في كل منها إلكترون مفرد (3 إلكترونات مفردة)، بينما للكربون والأكسجين إلكترونان مفردان فقط.', '["","للكربون إلكترونان مفردان ومجال فارغ.","للأكسجين مجال مزدوج وإلكترونان مفردان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.201Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(346, 2, 'الذرة تكون أكثر استقرارًا إذا كان المستوى الثانوي ممتلئًا أو نصف ممتلئ؛ في 4s¹ 3d⁵ يصبح كل من 4s و3d نصف ممتلئ: 4s [↑] 3d [↑][↑][↑][↑][↑].', '["المستوى 4s يتسع لإلكترونين.","4s أقل طاقة من 3d ويُملأ قبله في التوزيع المعتاد؛ الاستثناء سببه الاستقرار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.202Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(347, 1, 'عدد الأسهم = 2 + 2 + 2 = 6 إلكترونات، فهي ذرة الكربون (1s² 2s² 2p²).', '["البورون له إلكترون واحد فقط في 2p.","","النيتروجين له ثلاثة إلكترونات في 2p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.202Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(348, null, null, null, 'C₆ (1s² 2s² 2p²): 1s [↑↓] 2s [↑↓] 2p [↑][↑][  ]. F₉ (1s² 2s² 2p⁵): 1s [↑↓] 2s [↑↓] 2p [↑↓][↑↓][↑]. القواعد: أوفباو (ملء المجالات الأقل طاقة أولًا)، وباولي (إلكترونان متعاكسان على الأكثر في المجال)، وهوند (توزيع الإلكترونات منفردة متماثلة الدوران على مجالات 2p قبل الازدواج).', '["رسم الكربون الصحيح (إلكترونان منفردان في 2p)","رسم الفلور الصحيح","ذكر القواعد الثلاث وتطبيقها"]'::jsonb, '[]'::jsonb, '[{"element":"رسم C","marks":1},{"element":"رسم F","marks":1},{"element":"ذكر القواعد","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"رسمان صحيحان مع ذكر القواعد الثلاث"},{"level":"3 درجات","description":"رسمان صحيحان وذكر قاعدتين"},{"level":"2 درجتان","description":"رسمان صحيحان دون قواعد"},{"level":"1 درجة","description":"رسم واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["رسم 2p² للكربون مزدوجًا في مجال واحد","رسم سهمين متماثلين في مجال واحد","رسم مربع واحد للمستوى 2p"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.203Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(349, null, null, null, '(أ) Al: 1s [↑↓] 2s [↑↓] 2p [↑↓][↑↓][↑↓] 3s [↑↓] 3p [↑][  ][  ]. Cl: 1s [↑↓] 2s [↑↓] 2p [↑↓][↑↓][↑↓] 3s [↑↓] 3p [↑↓][↑↓][↑]. (ب) Al: المجالات المشغولة 7، الإلكترونات المفردة 1. Cl: المجالات المشغولة 9، الإلكترونات المفردة 1.', '["رسم Al الصحيح","رسم Cl الصحيح","Al: 7 مجالات وإلكترون مفرد","Cl: 9 مجالات وإلكترون مفرد"]'::jsonb, '["Al: 1 + 1 + 3 + 1 + 1 = 7 مجالات","Cl: 1 + 1 + 3 + 1 + 3 = 9 مجالات"]'::jsonb, '[{"element":"رسم Al","marks":1},{"element":"رسم Cl","marks":1},{"element":"أعداد Al","marks":1},{"element":"أعداد Cl","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الرسمان والأعداد صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"الرسمان فقط"},{"level":"1 درجة","description":"رسم واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عدّ المستويات الثانوية بدل المجالات","عدّ المربع الفارغ في 3p للألومنيوم مجالًا مشغولًا","وضع إلكترون 3p للألومنيوم في 3s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.203Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(350, null, null, null, '(أ) المتوقع: 4s [↑↓] 3d [↑↓][↑↓][↑↓][↑↓][↑]. الفعلي: 4s [↑] 3d [↑↓][↑↓][↑↓][↑↓][↑↓]. (ب) الذرة تكون أكثر استقرارًا عندما يكون المستوى الثانوي ممتلئًا أو نصف ممتلئ؛ بانتقال إلكترون من 4s إلى 3d يصبح 3d ممتلئًا (d¹⁰) و4s نصف ممتلئ (s¹)، فيكون التوزيع الفعلي أكثر استقرارًا.', '["رسم التوزيع المتوقع","رسم التوزيع الفعلي","التفسير بالاستقرار عند الامتلاء أو نصف الامتلاء"]'::jsonb, '[]'::jsonb, '[{"element":"رسم المتوقع","marks":1},{"element":"رسم الفعلي","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"رسمان صحيحان وتفسير كامل"},{"level":"3 درجات","description":"رسمان صحيحان وتفسير ناقص"},{"level":"2 درجتان","description":"رسمان صحيحان فقط أو تفسير كامل فقط"},{"level":"1 درجة","description":"رسم واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["رسم 3d بأربعة مربعات","تفسير الاستثناء بأن 3d أقل طاقة من 4s","إغفال أن 4s يصبح نصف ممتلئ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.203Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(351, 0, 'إلكترونات التكافؤ هي الإلكترونات الموجودة في المستوى الرئيسي الخارجي للذرة (أعلى مستوى طاقة رئيسي مشغول).', '["","إلكترونات المستوى الأقرب إلى النواة إلكترونات داخلية لا تشارك في التفاعلات عادة.","إلكترونات المستويات الداخلية الممتلئة ليست إلكترونات تكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.205Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(352, 2, 'إلكترونات التكافؤ هي التي تشارك في تكوين الروابط الكيميائية، فهي المسؤولة عن الخواص الكيميائية للعنصر.', '["كتلة الذرة تتركز في النواة (البروتونات والنيوترونات)، وكتلة الإلكترونات صغيرة جدًا.","العدد الذري يساوي عدد البروتونات، لا عدد إلكترونات التكافؤ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.205Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(353, 1, 'المستوى الرئيسي الخارجي هو الثالث: 3s² 3p⁵، فعدد إلكترونات التكافؤ 2 + 5 = 7.', '["عُدّت إلكترونات آخر مستوى ثانوي (3p⁵) فقط، والصحيح عدّ المستوى الرئيسي كله.","","17 هو العدد الكلي للإلكترونات لا إلكترونات التكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T11:15:01.205Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(354, 2, 'المستوى الخارجي n = 3 يحتوي على 3s² 3p⁴، فعدد إلكترونات التكافؤ 2 + 4 = 6.', '["عُدّت إلكترونات 3p فقط.","16 هو العدد الكلي للإلكترونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.206Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(355, 0, 'ينتهي توزيع كل منها بـ ns¹، فلكل منها إلكترون تكافؤ واحد، ولذلك تتشابه في خواصها الكيميائية (وهي عناصر مجموعة واحدة).', '["","عدد المستويات المشغولة مختلف: 2 و3 و4.","أعدادها الكلية مختلفة: 3 و11 و19."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.206Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(356, 1, 'المستوى الرئيسي الخارجي هو الرابع: 4s² 4p⁵، فعدد إلكترونات التكافؤ 2 + 5 = 7، ولا تُحسب إلكترونات 3d لأنها في المستوى الثالث الداخلي.', '["حُسبت إلكترونات 3d¹⁰ ضمن إلكترونات التكافؤ (2 + 10 + 5)، وهي في مستوى داخلي.","","عُدّت إلكترونات 4p فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T11:15:01.206Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(357, 2, 'O₈: 2s² 2p⁴ (6 إلكترونات تكافؤ)، وS₁₆: 3s² 3p⁴ (6 إلكترونات تكافؤ).', '["N له 5 إلكترونات تكافؤ وO له 6.","Na له إلكترون تكافؤ واحد وMg له إلكترونان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.207Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(358, null, null, null, '(أ) إلكترونات التكافؤ هي الإلكترونات الموجودة في المستوى الرئيسي الخارجي للذرة (أعلى مستوى طاقة رئيسي مشغول). (ب) لأنها التي تشارك في تكوين الروابط الكيميائية، فهي المسؤولة عن الخواص الكيميائية للعنصر. (ج) نكتب التوزيع: Mg: 1s² 2s² 2p⁶ 3s²، ثم نحدد آخر مستوى رئيسي (n = 3)، ثم نجمع إلكتروناته: 3s² ← إلكترونا تكافؤ.', '["التعريف","الأهمية: الخواص الكيميائية والروابط","كتابة التوزيع وتحديد آخر مستوى","Mg له إلكترونا تكافؤ"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التعريف","marks":1},{"element":"(ب) الأهمية","marks":1},{"element":"(ج) الخطوات والنتيجة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء كاملة صحيحة"},{"level":"3 درجات","description":"خطأ بسيط في أحد الأجزاء"},{"level":"2 درجتان","description":"تعريف صحيح ونتيجة صحيحة دون خطوات"},{"level":"1 درجة","description":"تعريف صحيح فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تعريفها بأنها إلكترونات آخر مستوى ثانوي","ربطها بكتلة الذرة","عدّ Mg 12 إلكترون تكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.207Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(359, null, null, null, 'K₁₉: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹ ← المستوى الخارجي n = 4 فيه 4s¹ ← إلكترون تكافؤ واحد. N₇: 1s² 2s² 2p³ ← المستوى الخارجي n = 2 فيه 2s² 2p³ ← 5 إلكترونات تكافؤ. Ge₃₂: [Ar] 4s² 3d¹⁰ 4p² ← المستوى الخارجي n = 4 فيه 4s² 4p² ← 4 إلكترونات تكافؤ (لا تُحسب 3d¹⁰ لأنها في المستوى الثالث).', '["توزيع K وتكافؤ 1","توزيع N وتكافؤ 5","توزيع Ge وتكافؤ 4","استبعاد إلكترونات 3d في Ge"]'::jsonb, '["K: n = 4 ← 4s¹ = 1","N: n = 2 ← 2 + 3 = 5","Ge: n = 4 ← 2 + 2 = 4"]'::jsonb, '[{"element":"K","marks":1},{"element":"N","marks":1},{"element":"Ge مع استبعاد 3d","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الثلاثة صحيحة مع التوزيعات"},{"level":"3 درجات","description":"K وN صحيحان وGe بلا توضيح"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عدّ Ge 14 إلكترون تكافؤ بإضافة 3d¹⁰","عدّ N 3 إلكترونات (2p فقط)","عدّ إلكترونات 3s 3p للبوتاسيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.207Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(360, null, null, null, '(أ) العبارة خاطئة؛ لأنه عدّ إلكترونات آخر مستوى ثانوي فقط. (ب) إلكترونات التكافؤ هي إلكترونات المستوى الرئيسي الخارجي كله: Cl: 1s² 2s² 2p⁶ 3s² 3p⁵ ← المستوى الثالث 3s² 3p⁵ ← 7 إلكترونات تكافؤ. (ج) نتوقع تشابه خواصهما الكيميائية؛ لأن لكل منهما 7 إلكترونات تكافؤ (F: 2s² 2p⁵)، وإلكترونات التكافؤ هي المسؤولة عن الخواص الكيميائية.', '["الحكم بخطأ العبارة","التصحيح: 7 إلكترونات بعدّ 3s² 3p⁵","توقع تشابه الخواص","الربط بإلكترونات التكافؤ"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الحكم","marks":1},{"element":"(ب) التصحيح مع التعليل","marks":2},{"element":"(ج) التوقع والتعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"تصحيح صحيح مع نقص في (ج)"},{"level":"1–2 درجة","description":"الحكم فقط أو التوقع دون تعليل"},{"level":"صفر","description":"تأييد الطالب أو لا إجابة"}]'::jsonb, '["تأييد عبارة الطالب","توقع اختلاف الخواص لاختلاف العدد الذري","عدّ الفلور 5 إلكترونات تكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.207Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(361, 2, 'تمثيل لويس: رمز العنصر محاطًا بعدد من النقاط يساوي عدد إلكترونات التكافؤ في ذرته.', '["النقاط تمثل إلكترونات التكافؤ فقط لا جميع الإلكترونات.","النقاط تمثل إلكترونات لا بروتونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.209Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(362, 0, 'Al: 1s² 2s² 2p⁶ 3s² 3p¹؛ المستوى الخارجي 3s² 3p¹ فيه 3 إلكترونات تكافؤ، فتُرسم 3 نقاط.', '["","13 هو عدد جميع إلكترونات الذرة.","عُدّ إلكترون 3p فقط وأُهمل 3s²."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.209Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(363, 1, 'Li: 1s² 2s¹؛ له إلكترون تكافؤ واحد في المستوى الثاني، فتُرسم نقطة واحدة بجانب الرمز.', '["النقطتان تمثلان إلكتروني 1s الداخليين لا إلكترون التكافؤ.","","ثلاث نقاط تمثل جميع إلكترونات الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.210Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(364, 1, 'Ne: 1s² 2s² 2p⁶؛ المستوى الخارجي 2s² 2p⁶ فيه 8 إلكترونات تكافؤ.', '["Na له إلكترون تكافؤ واحد (3s¹).","","Mg له إلكترونا تكافؤ (3s²)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.210Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(365, 0, 'الكلور (3s² 3p⁵) له 7 إلكترونات تكافؤ فيجب أن تُرسم 7 نقاط لا 5. أما N (2s² 2p³ = 5) وS (3s² 3p⁴ = 6) فصحيحان.', '["","النيتروجين له 5 إلكترونات تكافؤ، فخمس نقاط صحيحة.","الكبريت له 6 إلكترونات تكافؤ، فست نقاط صحيحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.210Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(366, 2, 'نكتب التوزيع الإلكتروني أولًا، ثم نحدد آخر مستوى رئيسي، ثم نعدّ إلكترونات التكافؤ فيه، ثم نرسم حول الرمز نقاطًا بعددها.', '["لا يمكن رسم النقاط قبل معرفة عددها من التوزيع.","لا يمكن عدّ إلكترونات التكافؤ قبل كتابة التوزيع وتحديد آخر مستوى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.210Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(367, 0, 'للنيتروجين 5 إلكترونات تكافؤ؛ توضع نقطة على كل جانب من الجوانب الأربعة ثم تزدوج الخامسة مع إحداها، فيظهر زوج واحد و3 نقاط مفردة.', '["","الجوانب أربعة فقط، فلا يمكن أن تبقى خمس نقاط مفردة.","هذا يحدث إذا وُضعت النقاط أزواجًا من البداية، وهو خلاف طريقة الرسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.210Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(368, null, null, null, 'Mg: 1s² 2s² 2p⁶ 3s² ← إلكترونا تكافؤ ← Mg ونقطتان حوله. C: 1s² 2s² 2p² ← 4 إلكترونات تكافؤ ← C وأربع نقاط مفردة على جوانبه الأربعة. S: 1s² 2s² 2p⁶ 3s² 3p⁴ ← 6 إلكترونات تكافؤ ← S وست نقاط (زوجان ونقطتان مفردتان). الخطوات (للكبريت): كتابة التوزيع ← آخر مستوى رئيسي n = 3 ← عدّ 3s² 3p⁴ = 6 ← رسم 6 نقاط حول الرمز.', '["Mg بنقطتين","C بأربع نقاط","S بست نقاط","توضيح الخطوات"]'::jsonb, '["التوزيع","تحديد آخر مستوى رئيسي","عدّ إلكترونات التكافؤ","رسم النقاط"]'::jsonb, '[{"element":"Mg","marks":1},{"element":"C","marks":1},{"element":"S","marks":1},{"element":"الخطوات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التمثيلات الثلاثة صحيحة مع الخطوات"},{"level":"3 درجات","description":"التمثيلات صحيحة دون خطوات"},{"level":"2 درجتان","description":"تمثيلان صحيحان"},{"level":"1 درجة","description":"تمثيل واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["رسم 12 نقطة للمغنيسيوم","رسم نقطتين فقط للكربون (2p²)","رسم 4 نقاط للكبريت (3p⁴)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.211Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(369, null, null, null, 'Li: 1s² 2s¹ — 1 — 1. Al: 1s² 2s² 2p⁶ 3s² 3p¹ — 3 — 3. N: 1s² 2s² 2p³ — 5 — 5. Cl: 1s² 2s² 2p⁶ 3s² 3p⁵ — 7 — 7. Ne: 1s² 2s² 2p⁶ — 8 — 8. الاستنتاج: عدد النقاط في تمثيل لويس يساوي عدد إلكترونات التكافؤ.', '["التوزيعات الصحيحة","أعداد إلكترونات التكافؤ 1، 3، 5، 7، 8","عدد النقاط مساوٍ للتكافؤ","استنتاج العلاقة"]'::jsonb, '["Li: 1","Al: 2 + 1 = 3","N: 2 + 3 = 5","Cl: 2 + 5 = 7","Ne: 2 + 6 = 8"]'::jsonb, '[{"element":"التوزيعات","marks":2},{"element":"أعداد التكافؤ والنقاط","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الجدول كامل صحيح مع الاستنتاج"},{"level":"3–4 درجات","description":"خطأ في خليتين على الأكثر"},{"level":"1–2 درجة","description":"أعداد صحيحة لعنصرين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة إلكترونات آخر مستوى ثانوي (Al = 1، Cl = 5)","عدّ إلكترونات Ne الكلية (10)","عدم استنتاج العلاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.211Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(370, null, null, null, '(أ) 6 إلكترونات تكافؤ. (ب) المستوى الخارجي هو الثالث وفيه 6 إلكترونات: 3s² 3p⁴، فالتوزيع 1s² 2s² 2p⁶ 3s² 3p⁴، والعدد الذري 2 + 2 + 6 + 2 + 4 = 16 وهو الكبريت S. (ج) الأكسجين O₈ (1s² 2s² 2p⁴) له 6 إلكترونات تكافؤ أيضًا، فيرسم حوله ست نقاط.', '["6 إلكترونات تكافؤ","التوزيع 3s² 3p⁴","العدد الذري 16 والكبريت","الأكسجين"]'::jsonb, '["النقاط = إلكترونات التكافؤ = 6","الدورة الثالثة ← n = 3 ← 3s² 3p⁴","Z = 10 + 6 = 16","الدورة الثانية: 2s² 2p⁴ ← O"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) التوزيع والعدد الذري","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ بسيط في جزء"},{"level":"2 درجتان","description":"(أ) و(ج) فقط أو (ب) فقط"},{"level":"1 درجة","description":"(أ) فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار 6 نقاط تعني العدد الذري 6","كتابة 3p⁶ للمستوى الخارجي","اختيار عنصر من دورة مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.211Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(371, 1, 'صنف لافوازييه العناصر المعروفة في عصره في أربع فئات: غازات، وفلزات، ولافلزات، وعناصر أرضية.', '["الترتيب حسب العدد الذري مساهمة موزلي.","","قانون الثمانيات مساهمة نيولاندز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.214Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(372, 2, 'نيولاندز رتب العناصر تصاعديًا حسب كتلها الذرية ولاحظ تكرار الخواص كل ثمانية عناصر، وسمى ذلك قانون الثمانيات.', '["مندليف رتب حسب الكتل الذرية لكنه اشتهر بترك أماكن شاغرة والتنبؤ بخواص العناصر غير المكتشفة.","موزلي رتب العناصر حسب العدد الذري.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.215Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
