(373, 0, 'رتب مندليف العناصر حسب كتلها الذرية وترك في جدوله أماكن شاغرة لعناصر لم تكن قد اكتشفت بعد، وتنبأ بخواصها.', '["","هذا تصنيف لافوازييه.","هذا قانون الثمانيات لنيولاندز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.215Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(374, 2, 'اكتشف موزلي العدد الذري (عدد البروتونات في النواة)، ورتب العناصر تصاعديًا حسبه، وهو أساس الجدول الدوري الحديث.', '["الترتيب حسب الكتل الذرية كان أساس جدولي نيولاندز ومندليف.","عدد النيوترونات لا يُعتمد في ترتيب الجدول الدوري.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.215Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(375, 1, 'مندليف رتب العناصر حسب الكتل الذرية لا الأعداد الذرية؛ والترتيب حسب العدد الذري مساهمة موزلي.', '["موزلي اكتشف العدد الذري فعلًا، فالصف صحيح.","","نيولاندز صاحب قانون الثمانيات، فالصف صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.215Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(376, 0, 'بدأ لافوازييه بالتصنيف إلى أربع فئات، ثم جاء نيولاندز بقانون الثمانيات، ثم مندليف بجدوله ذي الأماكن الشاغرة، وأخيرًا موزلي الذي رتب العناصر حسب العدد الذري.', '["","موزلي آخرهم لأنه بنى على اكتشاف العدد الذري، ولافوازييه أولهم.","مندليف جاء بعد نيولاندز، ولافوازييه أقدمهم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:01.216Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(377, 2, 'تنبأ مندليف بخواص عناصر لم تكن مكتشفة وترك لها أماكن شاغرة، وعند اكتشافها جاءت خواصها مطابقة لتنبؤاته، فزاد ذلك قبول جدوله.', '["نيولاندز أيضًا رتب العناصر حسب كتلها الذرية، فهذا لا يميز مندليف.","الترتيب في أعمدة وصفوف شكل للعرض لا يفسر قبول الجدول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.216Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(378, null, null, null, '(أ) لافوازييه: صنف العناصر في أربع فئات: غازات، وفلزات، ولافلزات، وعناصر أرضية. (ب) نيولاندز: رتب العناصر تصاعديًا حسب كتلها الذرية، ولاحظ تكرار الخواص كل ثمانية عناصر (قانون الثمانيات). (ج) مندليف: رتب العناصر حسب كتلها الذرية، وترك أماكن شاغرة لعناصر لم تكتشف، وتنبأ بخواصها. (د) موزلي: اكتشف العدد الذري (عدد البروتونات)، ورتب العناصر تصاعديًا حسبه.', '["لافوازييه: أربع فئات","نيولاندز: الكتل الذرية وقانون الثمانيات","مندليف: الأماكن الشاغرة والتنبؤ بالخواص","موزلي: العدد الذري"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المساهمات الأربع صحيحة"},{"level":"3 درجات","description":"ثلاث مساهمات صحيحة"},{"level":"2 درجتان","description":"مساهمتان صحيحتان"},{"level":"1 درجة","description":"مساهمة واحدة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسبة الترتيب حسب العدد الذري إلى مندليف","نسبة قانون الثمانيات إلى مندليف","إغفال التنبؤ بالخواص في مساهمة مندليف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.216Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(379, null, null, null, '(أ) مندليف رتب العناصر تصاعديًا حسب كتلها الذرية، أما موزلي فرتبها تصاعديًا حسب أعدادها الذرية. (ب) مندليف ترك أماكن شاغرة لعناصر لم تكتشف وتنبأ بخواصها، وموزلي اكتشف العدد الذري (عدد البروتونات). يُعد ترتيب موزلي أساس الجدول الحديث لأن العدد الذري صفة مميزة لكل عنصر، وبالترتيب حسبه تقع العناصر المتشابهة في الخواص في المجموعة نفسها بانتظام، فعولجت حالات كانت فيها بعض العناصر في غير موضعها المناسب عند الترتيب بالكتلة.', '["أساس مندليف: الكتل الذرية","أساس موزلي: الأعداد الذرية","إضافة مندليف: الأماكن الشاغرة والتنبؤ","إضافة موزلي: اكتشاف العدد الذري","تعليل اعتماد ترتيب موزلي"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) أساس الترتيب لكل منهما","marks":2},{"element":"(ب) الإضافات","marks":2},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة مع تعليل سليم"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع تعليل ناقص"},{"level":"1–2 درجة","description":"ذكر أساس الترتيب فقط"},{"level":"صفر","description":"لا إجابة أو خلط بين العالمين"}]'::jsonb, '["عكس أساسي الترتيب بين العالمين","تعريف العدد الذري بعدد النيوترونات","عدم تعليل اعتماد ترتيب موزلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.216Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(380, null, null, null, '(أ) قانون الثمانيات: عند ترتيب العناصر تصاعديًا حسب كتلها الذرية تتكرر خواصها كل ثمانية عناصر. (ب) نعد ثمانية عناصر بدءًا من Li (يُعد Li الأول): Li، Be، B، C، N، O، F، Na؛ فالعنصر الثامن Na يشبه Li. وبالطريقة نفسها بدءًا من Be: Be، B، C، N، O، F، Na، Mg؛ فالثامن Mg يشبه Be.', '["تسمية قانون الثمانيات","نص القانون: تكرار الخواص كل ثمانية عناصر بالترتيب حسب الكتل الذرية","Na يشبه Li","Mg يشبه Be مع توضيح العد"]'::jsonb, '["العد من Li: Li(1) ... Na(8)","العد من Be: Be(1) ... Mg(8)"]'::jsonb, '[{"element":"(أ) الاسم والنص","marks":2},{"element":"(ب) Na مع العد","marks":1},{"element":"(ب) Mg","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ في أحد العنصرين"},{"level":"2 درجتان","description":"(أ) فقط أو (ب) فقط"},{"level":"1 درجة","description":"تسمية القانون فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["العد ثمانية عناصر بعد Li (فيصل إلى Mg)","نسبة القانون إلى مندليف","ذكر أن الترتيب حسب العدد الذري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.217Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(381, 0, 'الدورة هي الصف الأفقي من العناصر في الجدول الدوري، وعدد الدورات سبع.', '["","العمود الرأسي يسمى المجموعة لا الدورة.","العناصر لا تتطابق في خواصها تمامًا، وتشابه الخواص صفة عناصر المجموعة الواحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(382, 1, 'المجموعة هي العمود الرأسي من العناصر في الجدول الدوري، وعدد المجموعات 18 مجموعة.', '["الدورة هي الصف الأفقي.","","الفئة (s أو p أو d أو f) قطاع من الجدول يضم عدة مجموعات، وليست عمودًا واحدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(383, 2, 'يتكون الجدول الدوري الحديث من 7 دورات (صفوف أفقية) و18 مجموعة (أعمدة رأسية).', '["18 هو عدد المجموعات لا الدورات.","8 قد يُخلط بينه وبين قانون الثمانيات، والدورات سبع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (71%)"}],"at":"2026-10-11T11:15:01.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(384, 1, 'عدد المجموعات (الأعمدة الرأسية) في الجدول الدوري الحديث 18 مجموعة.', '["7 هو عدد الدورات.","","8 هو عدد مجموعات العناصر الممثلة في الترقيم القديم، والجدول الحديث فيه 18 مجموعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (71%)"}],"at":"2026-10-11T11:15:01.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(385, 0, 'Li وNa كلاهما في المجموعة 1 (العمود نفسه)، وإن اختلفت دورتاهما.', '["","Na وMg في الدورة نفسها (الثالثة) لكن في مجموعتين مختلفتين.","Mg وCl في الدورة الثالثة نفسها لكن في المجموعتين 2 و17."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(386, 2, 'عناصر المجموعة الواحدة لها العدد نفسه من إلكترونات التكافؤ، ولذلك تتشابه في خواصها الكيميائية.', '["العدد الكلي للإلكترونات يزداد من دورة إلى التي تليها داخل المجموعة.","لكل عنصر عدد ذري خاص به.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-11T11:15:01.220Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(387, 1, 'رقم الدورة يساوي رقم آخر مستوى رئيسي مشغول بالإلكترونات، وهو 3 للصوديوم، فهو في الدورة الثالثة.', '["الرقم 1 هو عدد إلكترونات التكافؤ ويدل على المجموعة لا الدورة.","","11 هو العدد الذري، وعدد الدورات سبع فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.220Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(388, null, null, null, '(أ) الدورة: الصف الأفقي من العناصر في الجدول الدوري. المجموعة: العمود الرأسي من العناصر في الجدول الدوري. (ب) عدد الدورات 7، وعدد المجموعات 18.', '["تعريف الدورة: صف أفقي","تعريف المجموعة: عمود رأسي","7 دورات","18 مجموعة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الدورة","marks":1},{"element":"تعريف المجموعة","marks":1},{"element":"عدد الدورات","marks":1},{"element":"عدد المجموعات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفان والعددان صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"التعريفان فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة أو عكس التعريفين"}]'::jsonb, '["عكس التعريفين (الدورة عمود والمجموعة صف)","كتابة 8 مجموعات","كتابة 18 دورة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-11T11:15:01.220Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(389, null, null, null, '(أ) عناصر الدورة الواحدة تقع في صف أفقي واحد، وعناصر المجموعة الواحدة تقع في عمود رأسي واحد. (ب) عناصر المجموعة الواحدة متشابهة في خواصها الكيميائية، أما عناصر الدورة الواحدة فتتغير خواصها تدريجيًا من اليسار إلى اليمين. (ج) عناصر الدورة الواحدة لها رقم آخر مستوى رئيسي مشغول نفسه (رقم الدورة)، وعناصر المجموعة الواحدة لها العدد نفسه من إلكترونات التكافؤ.', '["الموقع: صف/عمود","تشابه خواص المجموعة","تدرج خواص الدورة","رقم آخر مستوى رئيسي للدورة","إلكترونات التكافؤ للمجموعة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الموقع","marks":1},{"element":"(ب) الخواص","marks":2},{"element":"(ج) التوزيع الإلكتروني","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة صحيحة"},{"level":"3–4 درجات","description":"مقارنة صحيحة في نقطتين"},{"level":"1–2 درجة","description":"مقارنة صحيحة في نقطة واحدة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن عناصر الدورة متشابهة الخواص","الخلط بين رقم الدورة وعدد إلكترونات التكافؤ","عكس الموقعين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-11T11:15:01.220Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
