(396, 1, 'انتهاء التوزيع بـ np يعني أنه من الفئة p (عنصر ممثل)، ورقم مجموعته = إلكترونات التكافؤ (2 + 4 = 6) + 10 = 16.', '["عدد إلكترونات p لا يعطي رقم المجموعة مباشرة، والعنصر ليس من الفئة d.","","الفئة f ينتهي توزيعها بـ nf."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.225Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(397, 0, 'الفئة s على يسار الجدول (المجموعتان 1 و2)، والفئة p على يمينه (13–18)، فالعناصر الممثلة تشغل طرفيه.', '["","وسط الجدول تشغله العناصر الانتقالية (الفئة d).","أسفل الجدول توجد العناصر الانتقالية الداخلية (اللانثانيدات والأكتينيدات)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:01.226Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(398, null, null, null, '(أ) المجموعتان 1 و2، والمجموعات من 13 إلى 18. (ب) الفئة s (1 و2) والفئة p (13–18). (ج) الفئة s ينتهي توزيعها بـ ns¹ أو ns²، والفئة p بـ np¹ إلى np⁶. (د) عنصران من الفئة s و6 عناصر من الفئة p.', '["المجموعات 1، 2، 13–18","الفئتان s وp","ns¹–ns² وnp¹–np⁶","عنصران و6 عناصر"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة أجزاء"},{"level":"2 درجتان","description":"جزءان"},{"level":"1 درجة","description":"جزء واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إدراج المجموعات 3–12","ذكر الفئة d ضمن العناصر الممثلة","كتابة 8 عناصر للفئة p"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.226Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(399, null, null, null, 'العناصر الممثلة: Na (المجموعة 1)، Ca (2)، Al (13)، S (16)، Br (17)، Ar (18). العناصر غير الممثلة: Fe (المجموعة 8) وCu (المجموعة 11)، وهما عنصران انتقاليان من الفئة d.', '["تصنيف الممثلة الستة","تصنيف Fe وCu غير ممثلة (انتقالية)","أرقام المجموعات الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف العناصر الممثلة","marks":2},{"element":"تصنيف غير الممثلة","marks":1},{"element":"أرقام المجموعات","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"التصنيف وأرقام المجموعات صحيحة كلها"},{"level":"3–4 درجات","description":"خطأ واحد أو اثنان"},{"level":"1–2 درجة","description":"تصنيف صحيح لنصف العناصر"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار الغاز النبيل Ar غير ممثل","إعطاء Al رقم المجموعة 3","تصنيف Cu عنصرًا ممثلًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.227Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(400, null, null, null, '(أ) X وZ ممثلان؛ لأن توزيع X ينتهي بـ np (الفئة p)، وتوزيع Z ينتهي بـ ns (الفئة s). (ب) X: إلكترونات التكافؤ 3 ← المجموعة 3 + 10 = 13. Z: إلكترون تكافؤ واحد ← المجموعة 1. Y: إلكترونات d (5) + 2 = 7 ← المجموعة 7. (ج) Y عنصر انتقالي من الفئة d، يقع في وسط الجدول (المجموعات 3–12)، في الدورة الرابعة المجموعة 7.', '["X وZ ممثلان مع التعليل بالفئة","X: المجموعة 13","Z: المجموعة 1","Y: المجموعة 7 وهو انتقالي"]'::jsonb, '["X: 2 + 1 = 3 ← 3 + 10 = 13","Z: s¹ ← 1","Y: d⁵ + 2 = 7"]'::jsonb, '[{"element":"(أ) التحديد والتعليل","marks":2},{"element":"(ب) أرقام المجموعات","marks":2},{"element":"(ج) موقع Y","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في رقم مجموعة واحدة أو تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد الممثلين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إعطاء X رقم المجموعة 3","اعتبار Y ممثلًا لأن توزيعه يحتوي على 4s²","الخلط بين رقم الدورة ورقم المجموعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.227Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(401, 1, 'العناصر الانتقالية الرئيسة (الفئة d) تشغل المجموعات من 3 إلى 12 في وسط الجدول الدوري.', '["المجموعتان 1 و2 تضمان عناصر الفئة s الممثلة.","","المجموعات 13–18 تضم عناصر الفئة p الممثلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:01.231Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(402, 2, 'العناصر الانتقالية الداخلية (الفئة f) تُكتب في صفين منفصلين أسفل الجدول الدوري هما اللانثانيدات والأكتينيدات.', '["هذا موقع العناصر الانتقالية الرئيسة (الفئة d).","لا توجد عناصر بعد المجموعة 18 في الجدول الدوري.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:01.231Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(403, 0, 'العناصر الانتقالية الرئيسة يمتلئ فيها المستوى الثانوي d (من nd¹ إلى nd¹⁰)، فهي عناصر الفئة d.', '["","الفئة p تضم عناصر ممثلة في المجموعات 13–18.","الفئة s تضم عناصر ممثلة في المجموعتين 1 و2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(404, 1, 'الحديد Fe في المجموعة 8 (الفئة d)، فهو عنصر انتقالي.', '["الصوديوم في المجموعة 1، عنصر ممثل من الفئة s.","","الكبريت في المجموعة 16، عنصر ممثل من الفئة p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(405, 2, 'العنصر A ينتهي توزيعه بالمستوى d (3d⁶)، فهو من الفئة d أي عنصر انتقالي رئيس.', '["B ينتهي توزيعه بـ 3p⁵ فهو عنصر ممثل من الفئة p.","C ينتهي توزيعه بـ 4f فهو عنصر انتقالي داخلي (الفئة f).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(406, 0, 'يمتلئ المستوى 3d في الدورة الرابعة من d¹ إلى d¹⁰، فيوجد 10 عناصر انتقالية (المجموعات 3–12).', '["","14 هو عدد عناصر الفئة f في الدورة الواحدة.","6 هو عدد عناصر الفئة p في الدورة الواحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(407, 1, 'رقم الدورة = رقم آخر مستوى رئيسي = 4، ورقم المجموعة لعناصر d = عدد إلكترونات d + 2 = 6 + 2 = 8.', '["عُدّت إلكترونات d فقط دون إضافة إلكتروني 4s.","","رقم الدورة يحدده آخر مستوى رئيسي (4) لا المستوى 3d."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.233Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(408, null, null, null, '(أ) الانتقالية الرئيسة في وسط الجدول (المجموعات 3–12)، والانتقالية الداخلية في صفين منفصلين أسفل الجدول. (ب) الرئيسة من الفئة d (nd¹ → nd¹⁰)، والداخلية من الفئة f (nf¹ → nf¹⁴). (ج) 10 عناصر للرئيسة و14 عنصرًا للداخلية في الدورة الواحدة. (د) اللانثانيدات والأكتينيدات.', '["الرئيسة: المجموعات 3–12 في الوسط","الداخلية: أسفل الجدول","الفئتان d وf","10 و14 عنصرًا","اللانثانيدات والأكتينيدات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) المكان","marks":2},{"element":"(ب) الفئة","marks":1},{"element":"(ج) العدد","marks":1},{"element":"(د) الأسماء","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في جزء أو جزأين"},{"level":"1–2 درجة","description":"جزء أو جزءان صحيحان فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس الفئتين d وf","كتابة المجموعات 2–13","نسيان أحد الصفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.233Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(409, null, null, null, '(أ) Sc وTi عنصران انتقاليان؛ لأن توزيعهما ينتهي بالمستوى الثانوي d (الفئة d). أما Ga فينتهي توزيعه بـ 4p فهو عنصر ممثل رغم احتوائه على 3d¹⁰. (ب) Sc: الدورة 4، المجموعة 1 + 2 = 3. Ti: الدورة 4، المجموعة 2 + 2 = 4. Ga: الدورة 4، المجموعة (2 + 1) + 10 = 13.', '["Sc وTi انتقاليان","التعليل بانتهاء التوزيع بـ d","Ga ممثل لانتهاء توزيعه بـ p","الدورة 4 للثلاثة","المجموعات 3 و4 و13"]'::jsonb, '["Sc: d¹ + 2 = 3","Ti: d² + 2 = 4","Ga: تكافؤ 3 + 10 = 13","الدورة = 4 للجميع"]'::jsonb, '[{"element":"(أ) التحديد والتعليل","marks":2},{"element":"(ب) الدورات","marks":1},{"element":"(ب) المجموعات","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في مجموعة أو تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد الانتقالية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار Ga انتقاليًا لوجود 3d¹⁰","إعطاء الدورة 3 لأن المستوى d رقمه 3","حساب مجموعة Sc = 1"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.233Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(410, null, null, null, '(أ) المنطقة (2) للعناصر الانتقالية الرئيسة، والمنطقة (4) للعناصر الانتقالية الداخلية. (ب) (1) الفئة s، (2) الفئة d، (3) الفئة p، (4) الفئة f. (ج) لأن المستوى الثانوي d يتسع لعشرة إلكترونات فيمتلئ عبر عشرة عناصر، والمستوى f يتسع لأربعة عشر إلكترونًا فيمتلئ عبر أربعة عشر عنصرًا.', '["(2) انتقالية رئيسة و(4) انتقالية داخلية","الفئات s وd وp وf","الربط بسعة d (10) وf (14)"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"(أ) و(ب) صحيحان مع تعليل ناقص"},{"level":"1–2 درجة","description":"(أ) فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس الفئتين s وp","اعتبار المنطقة (3) انتقالية","عدم الربط بسعة المستويات الثانوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.234Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
