(447, 1, 'إلكترونات التكافؤ 2 + 5 = 7، ورقم المجموعة لعناصر p = 7 + 10 = 17، واسمها الهالوجينات.', '["رقم المجموعة 17 لا 15 (أُخذ عدد إلكترونات p + 10).","","الغازات النبيلة في المجموعة 18 وتنتهي بـ np⁶."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.251Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(448, null, null, null, '(أ) الهالوجينات. (ب) الفلور F، والكلور Cl، والبروم Br، واليود I. (ج) تقع في يمين الجدول الدوري قبل الغازات النبيلة مباشرة (المجموعة 17 من الفئة p)، ومعظمها لافلزات.', '["الاسم: الهالوجينات","أربعة أمثلة","الموقع: يمين الجدول قبل المجموعة 18","لافلزات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج) الموقع","marks":1},{"element":"(ج) التصنيف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ في جزء"},{"level":"2 درجتان","description":"الاسم والأمثلة"},{"level":"1 درجة","description":"الاسم فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تسميتها الغازات النبيلة","ذكر O أو Ne أمثلة","تصنيفها فلزات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.251Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(449, null, null, null, '(أ) Br: [Ar] 4s² 3d¹⁰ 4p⁵. (ب) إلكترونات التكافؤ 2 + 5 = 7 (لا تُحسب 3d)، الدورة 4، المجموعة 7 + 10 = 17. (ج) الهالوجينات، والبروم هو اللافلز الوحيد السائل في درجة حرارة الغرفة.', '["التوزيع الصحيح","7 إلكترونات تكافؤ","الدورة 4 والمجموعة 17","الهالوجينات","سائل"]'::jsonb, '["18 + 2 + 10 + 5 = 35","التكافؤ: 4s² 4p⁵ = 7","المجموعة = 7 + 10 = 17"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في عنصر أو عنصرين"},{"level":"1–2 درجة","description":"التوزيع أو الاسم فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["حساب التكافؤ 17 بإضافة 3d¹⁰","إعطاء المجموعة 7","نسيان أن البروم سائل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.252Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(450, null, null, null, '(أ) الهالوجينات: ns² np⁵ (7 إلكترونات تكافؤ)، والغازات النبيلة: ns² np⁶ (8 إلكترونات تكافؤ، عدا الهيليوم 1s²). (ب) الهالوجينات −1، والغازات النبيلة 0. (ج) الهالوجينات نشطة كيميائيًا لأنها تحتاج إلى إلكترون واحد لإكمال مستواها الخارجي فتكتسبه بسهولة، أما الغازات النبيلة فمستقرة لأن مستواها الخارجي ممتلئ.', '["np⁵/7 مقابل np⁶/8","−1 مقابل 0","الهالوجينات نشطة تكتسب إلكترونًا","الغازات النبيلة مستقرة لامتلاء المستوى الخارجي"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة مع تفسير"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس عددي إلكترونات التكافؤ","كتابة عدد أكسدة +1 للهالوجينات","تفسير الاستقرار بأنها غازات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.252Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(451, 1, 'عناصر المجموعة 18 تسمى الغازات النبيلة، مثل He وNe وAr.', '["الهالوجينات اسم المجموعة 17.","","الفلزات القلوية اسم المجموعة 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.254Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(452, 2, 'تُعرف عناصر المجموعة 18 بالغازات النبيلة، وتسمى أيضًا الغازات الخاملة أو النادرة.', '["القلوية الأرضية اسم المجموعة الثانية.","أشباه الفلزات عناصر على الخط المتدرج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.254Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(453, 0, 'الأرجون في المجموعة 18 (توزيعه [Ne] 3s² 3p⁶)، فهو غاز نبيل.', '["","الكلور غاز لكنه من الهالوجينات (المجموعة 17).","النيتروجين غاز لكنه في المجموعة 15."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.254Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(454, 1, 'للغازات النبيلة (عدا He) ثمانية إلكترونات تكافؤ: ns² np⁶، أي أن مستواها الخارجي ممتلئ.', '["ns² np⁵ نهاية توزيع الهالوجينات.","","ns² نهاية توزيع الفلزات القلوية الأرضية (والهيليوم 1s² حالة خاصة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.255Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(455, 2, 'العنصر B توزيعه 1s² 2s² 2p⁶، مستواه الخارجي ممتلئ (2s² 2p⁶)، فهو غاز نبيل (النيون).', '["A ينتهي بـ 3s¹ فهو فلز قلوي (الصوديوم).","C ينتهي بـ 2p⁵ فهو من الهالوجينات (الفلور).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.255Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(456, 0, 'مستوى الطاقة الخارجي للغازات النبيلة ممتلئ (ns² np⁶، والهيليوم 1s²)، فلا تميل إلى فقد الإلكترونات أو اكتسابها، وعدد أكسدتها 0.', '["","هذا وصف الفلزات القلوية النشطة.","الغازات النبيلة تقع في أقصى يمين الجدول لا في وسطه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.255Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(457, 1, 'يُستخدم النيون في المصابيح ولوحات النيون (الإعلانات المضيئة).', '["رقائق الحاسوب من استخدامات السيليكون أو الجرمانيوم.","","حماية الأسنان من استخدامات الفلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.256Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(458, null, null, null, '(أ) الغازات النبيلة، وتعرف أيضًا بالغازات الخاملة أو النادرة. (ب) مثلًا: He₂، Ne₁₀، Ar₁₈، Kr₃₆ (ومنها أيضًا Xe₅₄ وRn₈₆). (ج) لأن المستوى الأول لا يتسع لأكثر من إلكترونين، فالهيليوم مستواه الخارجي ممتلئ مثل بقية الغازات النبيلة، فيشبهها في استقرارها.', '["الاسم والاسمان الآخران","أربعة عناصر بأعدادها الذرية","تعليل موقع الهيليوم بامتلاء المستوى الأول"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة"},{"level":"3 درجات","description":"تعليل ناقص في (ج)"},{"level":"2 درجتان","description":"(أ) و(ب) فقط"},{"level":"1 درجة","description":"الاسم فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تسميتها الهالوجينات","وضع الهيليوم في المجموعة 2","تفسير موقع الهيليوم بأنه غاز فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.256Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(459, null, null, null, '(أ) Ar: 1s² 2s² 2p⁶ 3s² 3p⁶، وإلكترونات التكافؤ 3s² 3p⁶ = 8. (ب) الرمز Ar محاطًا بثماني نقاط (أربعة أزواج على الجوانب الأربعة). (ج) مستوى الطاقة الخارجي ممتلئ بالإلكترونات، فلا تميل الذرة إلى فقد إلكترونات أو اكتسابها أو مشاركتها، وعدد أكسدتها 0.', '["توزيع Ar الصحيح","8 إلكترونات تكافؤ","لويس بثماني نقاط","الاستقرار لامتلاء المستوى الخارجي","عدد الأكسدة 0"]'::jsonb, '["2 + 2 + 6 + 2 + 6 = 18","التكافؤ: 2 + 6 = 8"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في عنصر أو اثنين"},{"level":"1–2 درجة","description":"التوزيع فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عدّ 6 إلكترونات تكافؤ (3p فقط)","رسم 18 نقطة","ذكر عدد أكسدة −1"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.256Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(460, null, null, null, '(أ) لأن توزيع كل غاز نبيل يمثل مستويات ممتلئة تمامًا (ns² np⁶ أو 1s²)، فيمكن أن يُختصر به جزء الإلكترونات الداخلية لأي عنصر يأتي بعده. (ب) K: [Ar] 4s¹ ، Sr: [Kr] 5s². (ج) الدورة 1: He، الدورة 2: Ne، الدورة 3: Ar، الدورة 4: Kr، الدورة 5: Xe.', '["التفسير بامتلاء مستويات الغاز النبيل","K: [Ar] 4s¹","Sr: [Kr] 5s²","الغازات النبيلة للدورات 1–5"]'::jsonb, '["K: 19 − 18 = 1 ← [Ar] 4s¹","Sr: 38 − 36 = 2 ← [Kr] 5s²"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في توزيع أو تفسير ناقص"},{"level":"1–2 درجة","description":"(ج) فقط أو توزيع واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام الغاز النبيل الذي يلي العنصر","كتابة Sr: [Kr] 4d²","إغفال الهيليوم للدورة الأولى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.257Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(461, 2, 'من استخدامات الليثيوم صناعة البطاريات.', '["حماية الأسنان من التسوس من استخدامات الفلور.","رقائق الحاسوب من استخدامات السيليكون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.259Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(462, 0, 'يُستخدم الفلور (مركباته) في حماية الأسنان من التسوس.', '["","الصوديوم يدخل في مكونات الطعام.","المغنيسيوم يُستخدم في الأجهزة الإلكترونية لخفته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.259Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(463, 2, 'السيليكون شبه فلز يُستخدم في صناعة رقائق الحاسوب والخلايا الشمسية.', '["البطاريات من استخدامات الليثيوم.","لوحات النيون من استخدامات النيون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.259Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(464, 0, 'يُستخدم المغنيسيوم في الأجهزة الإلكترونية لخفته.', '["","المغنيسيوم فلز لامع، واللون لا علاقة له بهذا الاستخدام.","المغنيسيوم فلز قابل للطرق والسحب، والهشاشة صفة غير مرغوبة في هذا الاستخدام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.259Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(465, 1, 'الكالسيوم من العناصر المهمة لصحة الإنسان، أما صناعة البطاريات فمن استخدامات الليثيوم.', '["الصوديوم يدخل فعلًا في مكونات الطعام، فالصف صحيح.","","السيليكون يُستخدم فعلًا في رقائق الحاسوب، فالصف صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.260Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(466, 2, 'الكالسيوم (ومعه المغنيسيوم) من العناصر المهمة لصحة الإنسان.', '["الليثيوم يُستخدم في البطاريات.","السيليكون يُستخدم في رقائق الحاسوب والخلايا الشمسية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.260Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(467, 0, 'الصوديوم يدخل في مكونات الطعام، ومن أشهر مركباته ملح الطعام (كلوريد الصوديوم).', '["","رقائق الحاسوب من استخدامات السيليكون.","حماية الأسنان من استخدامات الفلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.260Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(468, null, null, null, 'الصوديوم: يدخل في مكونات الطعام (ملح الطعام). الليثيوم: صناعة البطاريات. الفلور: حماية الأسنان من التسوس. المغنيسيوم: صناعة الأجهزة الإلكترونية لخفته (أو مهم لصحة الإنسان). الكالسيوم: مهم لصحة الإنسان. السيليكون: صناعة رقائق الحاسوب والخلايا الشمسية.', '["الصوديوم: الطعام","الليثيوم: البطاريات","الفلور: الأسنان","المغنيسيوم: الأجهزة الإلكترونية/الصحة","الكالسيوم: صحة الإنسان","السيليكون: رقائق الحاسوب/الخلايا الشمسية"]'::jsonb, '[]'::jsonb, '[{"element":"الصوديوم","marks":1},{"element":"الليثيوم","marks":1},{"element":"الفلور","marks":1},{"element":"المغنيسيوم","marks":1},{"element":"الكالسيوم","marks":1},{"element":"السيليكون","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"استخدام صحيح للعناصر الستة"},{"level":"4–5 درجات","description":"استخدامات صحيحة لأربعة أو خمسة عناصر"},{"level":"2–3 درجات","description":"استخدامات صحيحة لعنصرين أو ثلاثة"},{"level":"1 درجة","description":"استخدام صحيح لعنصر واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["نسبة البطاريات إلى الصوديوم أو الكالسيوم","الخلط بين استخدامات الفلور والنيون","نسبة رقائق الحاسوب إلى المغنيسيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.260Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(469, null, null, null, '(أ) لخفة وزنه، فيقلل وزن الأجهزة. (ب) لأشباه الفلزات خواص تشبه الفلزات واللافلزات، فتوصيله للكهرباء متوسط (أقل من الفلزات وأكبر من اللافلزات)، وهذا يجعله مناسبًا لصناعة رقائق الحاسوب والخلايا الشمسية. (ج) الجرمانيوم Ge.', '["خفة المغنيسيوم","خواص السيليكون بين الفلزات واللافلزات (توصيل متوسط)","الربط بالاستخدام","الجرمانيوم"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) الخاصية والربط","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة"},{"level":"3 درجات","description":"ربط ناقص في (ب)"},{"level":"2 درجتان","description":"(أ) و(ج) فقط"},{"level":"1 درجة","description":"جزء واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تفسير استخدام المغنيسيوم بلونه","القول إن السيليكون فلز جيد التوصيل","ذكر الألومنيوم شبه فلز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.260Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(470, null, null, null, 'Na: فلز — الفلزات القلوية — مكونات الطعام. Li: فلز — الفلزات القلوية — البطاريات. F: لافلز — الهالوجينات — حماية الأسنان من التسوس. Mg: فلز — الفلزات القلوية الأرضية — الأجهزة الإلكترونية لخفته. Ca: فلز — الفلزات القلوية الأرضية — صحة الإنسان. Si: شبه فلز — (المجموعة 14، لا يُطلب اسمها) — رقائق الحاسوب والخلايا الشمسية.', '["التصنيفات الصحيحة","أسماء المجموعات الصحيحة","الاستخدامات الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"التصنيف","marks":2},{"element":"أسماء المجموعات","marks":2},{"element":"الاستخدامات","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الجدول كامل صحيح"},{"level":"4–5 درجات","description":"خطأ في خليتين أو ثلاث"},{"level":"2–3 درجات","description":"عمود واحد كامل صحيح"},{"level":"1 درجة","description":"بعض الخلايا فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تصنيف Si فلزًا","تسمية مجموعة Mg وCa الفلزات القلوية","نسبة البطاريات إلى Ca"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.261Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
