(479, null, null, null, '(أ) اللانثانيدات في الصف الأول، والأكتينيدات في الصف الثاني أسفل الجدول. (ب) اللانثانيدات تتبع الدورة السادسة، والأكتينيدات الدورة السابعة. (ج) يمتلئ 4f في اللانثانيدات و5f في الأكتينيدات. (د) كلتاهما فلزات انتقالية داخلية من الفئة f، وتضم كل منهما 14 عنصرًا.', '["ترتيب الصفين","الدورتان 6 و7","4f و5f","الاشتراك في الفئة f و14 عنصرًا"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة صحيحة"},{"level":"3 درجات","description":"خطأ في جزء"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس الدورتين","كتابة 4d و5d","اعتبارهما من الفئة d"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.264Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(480, null, null, null, '(أ) X لانثانيد؛ لأن توزيعه ينتهي بالمستوى 4f. Y أكتينيد؛ لأن توزيعه ينتهي بالمستوى 5f. Z عنصر انتقالي رئيس؛ لأن توزيعه ينتهي بالمستوى 4d (الفئة d). (ب) X: الدورة 6، Y: الدورة 7، Z: الدورة 5 (رقم الدورة = أكبر رقم مستوى رئيسي: 6s، 7s، 5s).', '["X لانثانيد (4f)","Y أكتينيد (5f)","Z انتقالي رئيس (4d)","الدورات 6 و7 و5"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف X","marks":1},{"element":"تصنيف Y","marks":1},{"element":"تصنيف Z","marks":1},{"element":"الدورات","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في تصنيف أو دورة"},{"level":"1–2 درجة","description":"تصنيف واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تحديد الدورة برقم المستوى f (4 أو 5)","اعتبار Z لانثانيدًا","عكس اللانثانيدات والأكتينيدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.265Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(481, 1, 'إلكترونات التكافؤ هي إلكترونات آخر مستوى رئيسي (n = 3): 3s² 3p⁴ أي 2 + 4 = 6 إلكترونات.', '["عُدّت إلكترونات 3p فقط وأُهملت إلكترونات 3s من المستوى الرئيسي نفسه.","","هذا العدد الكلي لإلكترونات الذرة (العدد الذري) لا إلكترونات التكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-11T11:15:01.267Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(482, 2, 'رقم الدورة يساوي رقم آخر مستوى رئيسي مشغول بالإلكترونات، وأعلى مستوى هنا n = 4 (4s² 4p²)، فالعنصر في الدورة الرابعة.', '["اعتُمد على المستوى 3d الذي يُملأ قبل 4p، مع أن أعلى مستوى رئيسي هو الرابع.","اعتُمد على عدد إلكترونات 4p (2) بدل رقم المستوى الرئيسي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-11T11:15:01.268Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(483, 0, 'العنصر من الفئة p، ورقم مجموعته = عدد إلكترونات p في آخر مستوى + 12 = 5 + 12 = 17 (أو عدد إلكترونات التكافؤ 7 + 10).', '["","أُضيف 10 إلى عدد إلكترونات p (5) بدل إضافة 12، أي أُهمل إلكترونا 3s.","اكتُفي بعدد إلكترونات 3p دون تطبيق قاعدة الفئة p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.268Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(484, 2, 'العنصر من الفئة d، ورقم مجموعته = عدد إلكترونات d + 2 = 10 + 2 = 12.', '["عُدّت إلكترونات 3d فقط دون إضافة إلكتروني 4s.","اعتُمد على إلكتروني 4s فقط كأن العنصر من الفئة s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-11T11:15:01.268Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(485, 1, 'X: آخر مستوى n = 2 فيه 2s² 2p³ أي 5 إلكترونات تكافؤ، والدورة 2، والمجموعة 3 + 12 = 15، فالاستنتاج صحيح. Y: التكافؤ 2 والدورة 3 لكن المجموعة 2 لا 12. Z: أعلى مستوى n = 4 فالدورة 4 لا 3.', '["Y من الفئة s، فرقم مجموعته يساوي عدد إلكترونات التكافؤ (2) لا 12.","","أعلى مستوى رئيسي في Z هو الرابع (4s¹) فهو في الدورة 4 لا 3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.268Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(486, 0, 'عناصر المجموعة الواحدة لها العدد نفسه من إلكترونات التكافؤ؛ العنصر المعطى له إلكترون تكافؤ واحد (3s¹)، والتوزيع المنتهي بـ 4s¹ له إلكترون تكافؤ واحد أيضًا فهو في المجموعة 1.', '["","هذا العنصر في الدورة نفسها (3) لكنه في المجموعة 2 لأن له إلكتروني تكافؤ.","هذا العنصر في الدورة نفسها (3) لكنه في المجموعة 13 لأن له 3 إلكترونات تكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.269Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(487, 2, 'الدورة الثالثة تعني أن آخر مستوى رئيسي n = 3، والمجموعة 16 من الفئة p تعني أن عدد إلكترونات p = 16 − 12 = 4، فالتوزيع ينتهي بـ 3s² 3p⁴.', '["هذا العنصر في المجموعة 16 لكنه في الدورة الثانية (آخر مستوى n = 2).","هذا العنصر في الدورة الثالثة لكنه في المجموعة 18 (6 إلكترونات p).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.269Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(488, null, null, null, 'K: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹ ← آخر مستوى n = 4 فيه إلكترون واحد: التكافؤ 1، الدورة 4، والعنصر من الفئة s فالمجموعة = عدد إلكترونات s = 1. Ge: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p² ← آخر مستوى n = 4 فيه 4s² 4p²: التكافؤ 4، الدورة 4، والعنصر من الفئة p فالمجموعة = عدد إلكترونات p + 12 = 2 + 12 = 14.', '["توزيع K صحيح","K: تكافؤ 1، دورة 4، مجموعة 1","توزيع Ge صحيح","Ge: تكافؤ 4 (إلكترونات 3d ليست تكافؤًا)","Ge: دورة 4، مجموعة 14 بقاعدة p + 12"]'::jsonb, '["K (Z = 19): 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹","آخر مستوى n = 4 ← الدورة 4، التكافؤ = 1، المجموعة = 1","Ge (Z = 32): 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p²","آخر مستوى n = 4: 4s² 4p² ← التكافؤ = 4، الدورة 4","المجموعة = 2 + 12 = 14"]'::jsonb, '[{"element":"التوزيعان الإلكترونيان","marks":2},{"element":"استنتاجات K","marks":1},{"element":"استنتاجات Ge مع القاعدة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"التوزيعان صحيحان وجميع الاستنتاجات صحيحة مع ذكر القاعدة"},{"level":"3–4 درجات","description":"التوزيعان صحيحان مع خطأ في استنتاج واحد أو اثنين"},{"level":"1–2 درجة","description":"توزيع واحد صحيح أو استنتاجات صحيحة لعنصر واحد"},{"level":"صفر","description":"لا إجابة أو توزيعات خاطئة كليًا"}]'::jsonb, '["عدّ إلكترونات 3d ضمن إلكترونات التكافؤ للجرمانيوم","اعتبار Ge في الدورة 3 بسبب 3d","إضافة 10 بدل 12 إلى عدد إلكترونات p"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.269Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(489, null, null, null, 'لأن عناصر المجموعة الواحدة لها العدد نفسه من إلكترونات التكافؤ، وإلكترونات التكافؤ هي التي تشترك في التفاعلات الكيميائية فتحدد الخواص الكيميائية. مثال: الليثيوم Li: 1s² 2s¹ والصوديوم Na: 1s² 2s² 2p⁶ 3s¹، لكل منهما إلكترون تكافؤ واحد (ns¹)، لذلك يتفاعل كلاهما بفقد هذا الإلكترون مكوّنًا أيونًا موجبًا أحادي الشحنة.', '["تساوي عدد إلكترونات التكافؤ","إلكترونات التكافؤ هي المسؤولة عن التفاعل الكيميائي","توزيعان صحيحان لعنصرين من المجموعة 1","الإشارة إلى التوزيع الخارجي المشترك ns¹"]'::jsonb, '[]'::jsonb, '[{"element":"التعليل بتساوي إلكترونات التكافؤ","marks":1},{"element":"ربط التكافؤ بالسلوك الكيميائي","marks":1},{"element":"المثال بتوزيعين صحيحين","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل ومثال صحيح بتوزيعين"},{"level":"2–3 درجات","description":"تعليل صحيح مع مثال ناقص، أو مثال صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"ذكر تساوي التكافؤ فقط"},{"level":"صفر","description":"تعليل خاطئ كأن يُعزى التشابه لتساوي عدد المستويات"}]'::jsonb, '["تعليل التشابه بتساوي عدد مستويات الطاقة (وهذا يخص الدورة)","اختيار مثال من دورة واحدة لا من مجموعة واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.269Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(490, null, null, null, '(أ) آخر مستوى n = 3 فيه 3s² 3p⁶: إلكترونات التكافؤ 8، الدورة 3، المجموعة 6 + 12 = 18. (ب) مجموعة الغازات النبيلة (الخاملة). (ج) مستقر لأن مستواه الخارجي ممتلئ بثمانية إلكترونات (ns² np⁶)، فلا يميل إلى فقد الإلكترونات أو اكتسابها.', '["التكافؤ 8","الدورة 3","المجموعة 18","الغازات النبيلة","التعليل بامتلاء المستوى الخارجي بثمانية إلكترونات"]'::jsonb, '["آخر مستوى رئيسي n = 3 ← الدورة 3","إلكترونات التكافؤ = 2 + 6 = 8","المجموعة = 6 + 12 = 18"]'::jsonb, '[{"element":"(أ) الاستنتاجات الثلاثة","marks":3},{"element":"(ب) اسم المجموعة","marks":1},{"element":"(ج) تفسير الاستقرار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في أحد استنتاجات (أ) أو نقص في التفسير"},{"level":"1–2 درجة","description":"استنتاج واحد أو اثنان صحيحان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["كتابة المجموعة 8 بدل 18","تفسير الاستقرار بكبر حجم الذرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.270Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(491, 0, 'يقسم الجدول الدوري إلى أربع فئات هي s وp وd وf، بحسب نوع آخر مستوى ثانوي يُملأ بالإلكترونات.', '["","سبعة هو عدد الدورات (الصفوف) لا الفئات.","ثمانية عشر هو عدد المجموعات (الأعمدة) لا الفئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.272Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(492, 2, 'فئة العنصر تحددها نوعية آخر مستوى ثانوي (مجال) يدخله الإلكترون في التوزيع الإلكتروني: s أو p أو d أو f.', '["عدد مستويات الطاقة الرئيسية يحدد رقم الدورة لا الفئة.","الجدول الحديث مرتب حسب العدد الذري، والفئات مرتبطة بالتوزيع الإلكتروني لا بالكتلة أو الحالة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.272Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(493, 1, 'العناصر الانتقالية الرئيسية هي عناصر الفئة d التي ينتهي توزيعها بالمستوى الثانوي d (من nd¹ إلى nd¹⁰).', '["الفئة f تضم العناصر الانتقالية الداخلية (اللانثانيدات والأكتينيدات).","","الفئة p من العناصر المثالية (الممثلة) وليست انتقالية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.272Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(494, 0, 'المستوى الثانوي d يتسع لعشرة إلكترونات، لذا يتدرج التوزيع الخارجي لعناصر الفئة d من nd¹ إلى nd¹⁰، ولهذا يضم كل صف منها 10 عناصر.', '["","ستة إلكترونات هي سعة المستوى الثانوي p لا d.","أربعة عشر إلكترونًا هي سعة المستوى الثانوي f لا d."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.273Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(495, 2, 'اللانثانيدات والأكتينيدات تُكتب في صفين أسفل الجدول، وينتهي توزيعها بالمستوى الثانوي f، فهي العناصر الانتقالية الداخلية.', '["الفئة d تضم الانتقالية الرئيسية في المجموعات 3–12 لا اللانثانيدات والأكتينيدات.","الفئة s تضم المجموعتين 1 و2 فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.273Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(496, 1, 'العناصر المثالية تشمل الفئة s (المجموعتان 1 و2) والفئة p (المجموعات 13–18)، أما d وf فهما العناصر الانتقالية والانتقالية الداخلية.', '["d وf هما فئتا العناصر الانتقالية الرئيسية والداخلية.","","الفئة d انتقالية وليست من العناصر المثالية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.273Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(497, 0, 'عدد عناصر الفئة في الدورة يساوي سعة مستواها الثانوي: f يتسع لـ 14 إلكترونًا فتضم 14 عنصرًا، مقابل 10 للفئة d و6 للفئة p.', '["","الفئة d تضم 10 عناصر في الدورة لأن المستوى d يتسع لـ 10 إلكترونات فقط.","الفئة p تضم 6 عناصر في الدورة لأن المستوى p يتسع لـ 6 إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.273Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(498, null, null, null, '1) الفئة s: تنتهي بـ ns¹ أو ns²، عنصران في الدورة، عناصر مثالية (الفلزات القلوية والقلوية الأرضية). 2) الفئة p: تنتهي بـ np¹ إلى np⁶، ستة عناصر، عناصر مثالية. 3) الفئة d: تنتهي بـ nd¹ إلى nd¹⁰، عشرة عناصر، العناصر الانتقالية الرئيسية. 4) الفئة f: تنتهي بـ nf¹ إلى nf¹⁴، أربعة عشر عنصرًا، العناصر الانتقالية الداخلية (اللانثانيدات والأكتينيدات).', '["ذكر الفئات الأربع s وp وd وf","المستوى الثانوي لكل فئة","عدد العناصر 2، 6، 10، 14","نوع العناصر: مثالية، انتقالية رئيسية، انتقالية داخلية"]'::jsonb, '[]'::jsonb, '[{"element":"تعداد الفئات الأربع","marks":2},{"element":"المستوى الثانوي وعدد العناصر","marks":2},{"element":"نوع العناصر في كل فئة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الفئات الأربع بجميع خصائصها صحيحة"},{"level":"4–5 درجات","description":"الفئات صحيحة مع خطأ في خاصية أو اثنتين"},{"level":"2–3 درجات","description":"تعداد الفئات فقط أو مع خاصية واحدة"},{"level":"1 درجة","description":"ذكر فئتين أو ثلاث فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الخلط بين d (انتقالية رئيسية) وf (انتقالية داخلية)","جعل عدد عناصر الفئة p ثمانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.273Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(499, null, null, null, 'لأن عدد العناصر في الصف الواحد من الفئة يساوي أقصى عدد من الإلكترونات يتسع له مستواها الثانوي؛ ففي كل عنصر تالٍ يُضاف إلكترون واحد. المستوى الثانوي s يتسع لإلكترونين فقط (ns¹، ns²) فيضم صفه عنصرين، أما المستوى الثانوي f فيتسع لأربعة عشر إلكترونًا (nf¹ إلى nf¹⁴) فيضم صفه أربعة عشر عنصرًا.', '["الربط بين عدد العناصر وسعة المستوى الثانوي","كل عنصر تالٍ يزيد إلكترونًا واحدًا","سعة s = 2","سعة f = 14"]'::jsonb, '[]'::jsonb, '[{"element":"الربط بسعة المستوى الثانوي","marks":2},{"element":"سعة s وسعة f","marks":1},{"element":"إضافة إلكترون مع كل عنصر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل بسعة المستويين وإضافة إلكترون لكل عنصر"},{"level":"2–3 درجات","description":"ذكر السعتين دون ربط واضح بعدد العناصر"},{"level":"1 درجة","description":"ذكر سعة مستوى واحد فقط"},{"level":"صفر","description":"تفسير خاطئ"}]'::jsonb, '["تفسير الفرق بعدد مستويات الطاقة الرئيسية","الخلط بين سعة f (14) وسعة d (10)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.274Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(500, null, null, null, 'الفئة s في يسار الجدول (العمودان الأولان)، والفئة p في يمينه (الأعمدة الستة الأخيرة)، والفئة d في وسطه بين s وp (عشرة أعمدة)، والفئة f في صفين منفصلين أسفل الجدول (اللانثانيدات والأكتينيدات). ويُستثنى الهيليوم: يوضع في المجموعة 18 مع الغازات النبيلة لأن مستواه الخارجي ممتلئ ويشبهها في الخواص، لكنه من الفئة s لأن توزيعه 1s².', '["s يسار الجدول","p يمين الجدول","d في الوسط","f صفان أسفل الجدول","استثناء الهيليوم مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"مواقع الفئات الأربع","marks":4},{"element":"استثناء الهيليوم وتعليله","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"المواقع الأربعة صحيحة مع استثناء الهيليوم معللًا"},{"level":"4–5 درجات","description":"المواقع صحيحة مع نقص في تعليل الاستثناء"},{"level":"2–3 درجات","description":"موقعان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"موقع واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["وضع الفئة f في وسط الجدول بدل أسفله","اعتبار الهيليوم من الفئة p لوقوعه في المجموعة 18"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.274Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
