(501, 1, 'الفئة p تضم ست مجموعات هي من 13 إلى 18، لأن المستوى الثانوي p يتسع لستة إلكترونات.', '["المجموعات 3–12 تقع ضمن الفئة d.","","المجموعتان 1 و2 تقعان ضمن الفئة s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.276Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(502, 2, 'الفئة d تشغل المجموعات من 3 إلى 12، والمجموعة 7 تقع ضمن هذا المدى.', '["الفئة p تبدأ من المجموعة 13.","الفئة s تضم المجموعتين 1 و2 فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.277Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(503, 0, 'الفئة d تمتد من المجموعة 3 إلى المجموعة 12، أي 12 − 3 + 1 = 10 مجموعات، وهو ما يوافق سعة المستوى الثانوي d (10 إلكترونات).', '["","ست مجموعات هي عدد مجموعات الفئة p.","ناتج طرح 12 − 3 دون إضافة 1، أو خلط مع عدد الإلكترونات في التركيب الثماني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.278Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(504, 0, 'المجموعة 12 هي آخر مجموعات الفئة d (3–12)، أما الفئة p فتبدأ من المجموعة 13؛ لذا نسبتها إلى p خطأ.', '["","المجموعة 15 تقع فعلًا ضمن الفئة p (13–18).","المجموعة 4 تقع فعلًا ضمن الفئة d (3–12)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.278Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(505, 1, 'عناصر الفئة f (الانتقالية الداخلية: اللانثانيدات والأكتينيدات) لا تأخذ أرقام مجموعات مستقلة، وتكتب في صفين أسفل الجدول.', '["المجموعات 13–18 هي مجموعات الفئة p.","","المجموعتان 1 و2 هما مجموعتا الفئة s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.278Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(506, 2, 'المجموعة 18 ضمن الفئة p (np⁶)، لكن الهيليوم يُستثنى لأن توزيعه 1s² فهو من الفئة s رغم وضعه مع الغازات النبيلة لامتلاء مستواه الخارجي.', '["أُغفل استثناء الهيليوم الذي ينتهي توزيعه بـ 1s².","المجموعة 18 ضمن الفئة p، والنيون (2p⁶) من الفئة p كبقية المجموعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.278Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(507, 1, 'بين المجموعة 2 (آخر مجموعات s) والمجموعة 13 (أول مجموعات p) تقع المجموعات 3–12 وهي مجموعات الفئة d.', '["عناصر الفئة f توضع أسفل الجدول ولا تقع بين المجموعتين 2 و13 في الدورة الرابعة.","","الفئة p تبدأ من المجموعة 13 نفسها فلا تقع بينهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.278Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(508, null, null, null, 'الفئة s: المجموعتان 1 و2 (مجموعتان). الفئة p: المجموعات 13–18 (6 مجموعات). الفئة d: المجموعات 3–12 (10 مجموعات). الفئة f: لا تأخذ أرقام مجموعات مستقلة، وتوضع في صفين أسفل الجدول (اللانثانيدات والأكتينيدات، 14 عنصرًا في كل صف).', '["s: 1–2","p: 13–18","d: 3–12","f: أسفل الجدول دون أرقام مجموعات","الأعداد 2، 6، 10"]'::jsonb, '[]'::jsonb, '[{"element":"مجموعات s وp","marks":2},{"element":"مجموعات d","marks":1},{"element":"موقع f","marks":1},{"element":"أعداد المجموعات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الفئات بمجموعاتها وأعدادها صحيحة"},{"level":"3–4 درجات","description":"خطأ في فئة واحدة أو في الأعداد"},{"level":"1–2 درجة","description":"فئة أو فئتان صحيحتان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل الفئة d في المجموعات 3–10","إعطاء الفئة f أرقام مجموعات مثل 19–32"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.279Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(509, null, null, null, 'عدد مجموعات الفئة يساوي عدد الإلكترونات التي يتسع لها مستواها الثانوي؛ المستوى p يتسع لـ 6 إلكترونات (np¹ إلى np⁶) فتضم الفئة p ست مجموعات، والمستوى d يتسع لـ 10 إلكترونات (nd¹ إلى nd¹⁰) فتضم الفئة d عشر مجموعات. المجموعة 1: s، المجموعة 7: d، المجموعة 13: p، المجموعة 18: p (ما عدا الهيليوم فهو من s).', '["الربط بسعة المستوى الثانوي","p = 6 وd = 10","تصنيف المجموعات الأربع صحيحًا","الإشارة إلى استثناء الهيليوم"]'::jsonb, '[]'::jsonb, '[{"element":"التفسير بسعة المستوى الثانوي","marks":2},{"element":"تصنيف المجموعات الأربع","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح وتصنيف صحيح للمجموعات الأربع"},{"level":"2–3 درجات","description":"تفسير ناقص أو خطأ في تصنيف مجموعة واحدة"},{"level":"1 درجة","description":"تصنيف صحيح دون تفسير أو العكس جزئيًا"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تصنيف المجموعة 7 ضمن p","التفسير بعدد الدورات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.279Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(510, null, null, null, 'الفئة s: المجموعتان 1 و2، آخر مستوى ثانوي ns (ns¹ أو ns²)، عناصر مثالية؛ والمجموعة 1 (عدا الهيدروجين) هي الفلزات القلوية والمجموعة 2 هي الفلزات القلوية الأرضية. الفئة d: المجموعات 3–12، آخر مستوى ثانوي (n−1)d من d¹ إلى d¹⁰، وعناصرها هي العناصر الانتقالية الرئيسية.', '["مجموعات s: 1 و2","مجموعات d: 3–12","المستوى الثانوي لكل منهما","مثالية مقابل انتقالية","الفلزات القلوية والقلوية الأرضية"]'::jsonb, '[]'::jsonb, '[{"element":"أرقام المجموعات","marks":2},{"element":"المستوى الثانوي","marks":1},{"element":"نوع العناصر","marks":1},{"element":"اسما مجموعتي s","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة صحيحة مع الاسمين"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع نقص عنصر"},{"level":"1–2 درجة","description":"ذكر أرقام المجموعات فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عدّ الهيدروجين من الفلزات القلوية","الخلط بين القلوية والقلوية الأرضية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.279Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(511, 0, 'فئة العنصر يحددها آخر مستوى ثانوي يُملأ بالإلكترونات حسب ترتيب الملء، وهو هنا 3d¹، فالعنصر من الفئة d (السكانديوم).', '["","اعتُمد على المستوى 4s لأنه الأعلى رقمًا، لكن آخر مستوى ثانوي يُملأ هو 3d.","المستوى 3p ممتلئ وليس آخر ما يُملأ في التوزيع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.282Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(512, 1, 'آخر مستوى رئيسي n = 3 ← الدورة 3، وآخر مستوى ثانوي p فالعنصر من الفئة p ومجموعته = 3 + 12 = 15.', '["عُدّت إلكترونات التكافؤ (5) رقمًا للمجموعة دون قاعدة الفئة p.","","عُكس رقما الدورة والمجموعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.282Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(513, 2, 'أعلى مستوى رئيسي هو n = 4 ← الدورة 4، والعنصر من الفئة d فمجموعته = عدد إلكترونات d + 2 = 6 + 2 = 8.', '["اعتُمد رقم المستوى 3d للدورة، والدورة يحددها أعلى مستوى رئيسي (4s).","عُدّت إلكترونات d فقط دون إضافة إلكتروني 4s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.282Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(514, 1, 'آخر مستوى ثانوي يُملأ في Y هو 4s²، فهو من الفئة s (المجموعة 2، الدورة 4). أما X فينتهي بـ 3p¹ (فئة p)، وZ ينتهي بـ 3d² (فئة d).', '["X ينتهي توزيعه بـ 3p¹ فهو من الفئة p رغم وجود 3s² فيه.","","Z ينتهي بـ 3d² فهو من الفئة d رغم أن 4s² هو أعلى مستوى رئيسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.282Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(515, 0, 'آخر مستوى ثانوي p ← الفئة p، والمستوى الرئيسي الرابع ← الدورة 4، والمجموعة = 5 + 12 = 17 (الهالوجينات).', '["","أُخذ عدد الإلكترونات (5) رقمًا للدورة، ورقم المستوى (4) رقمًا للمجموعة.","الفئة يحددها آخر مستوى ثانوي (p) لا المستوى s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.283Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(516, 2, 'آخر مستوى رئيسي لكليهما n = 3 فهما في الدورة الثالثة، لكن A ينتهي بـ 3s (فئة s، المجموعة 2) وB ينتهي بـ 3p (فئة p، المجموعة 16).', '["عدد إلكترونات التكافؤ مختلف (2 و6) فهما في مجموعتين مختلفتين، وآخر مستوى ثانوي مختلف.","كلاهما في الدورة الثالثة لأن أعلى مستوى رئيسي هو n = 3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.283Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(517, 1, 'توزيعه 1s² 2s² 2p⁶ 3s¹: آخر مستوى ثانوي s ← الفئة s، وآخر مستوى رئيسي n = 3 ← الدورة 3، وفيه إلكترون واحد ← المجموعة 1.', '["عُكس رقما الدورة والمجموعة.","","المستوى 2p ممتلئ وليس الأخير؛ آخر مستوى يُملأ هو 3s فالفئة s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.283Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(518, null, null, null, 'Na: 1s² 2s² 2p⁶ 3s¹ ← الفئة s، الدورة 3، المجموعة 1. O: 1s² 2s² 2p⁴ ← الفئة p، الدورة 2، المجموعة 4 + 12 = 16. Sc: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹ ← الفئة d، الدورة 4، المجموعة 1 + 2 = 3.', '["التوزيعات الثلاثة صحيحة","Na: s، 3، 1","O: p، 2، 16","Sc: d، 4، 3"]'::jsonb, '["Na (Z = 11): 1s² 2s² 2p⁶ 3s¹ ← آخر مستوى ثانوي 3s","O (Z = 8): 1s² 2s² 2p⁴ ← المجموعة = 4 + 12 = 16","Sc (Z = 21): ... 4s² 3d¹ ← المجموعة = 1 + 2 = 3، الدورة = 4"]'::jsonb, '[{"element":"التوزيعات الإلكترونية","marks":3},{"element":"الفئة والموقع لكل عنصر","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"التوزيعات والفئات والمواقع كلها صحيحة"},{"level":"4–5 درجات","description":"خطأ في موقع عنصر واحد"},{"level":"2–3 درجات","description":"توزيعات صحيحة مع أخطاء في المواقع"},{"level":"1 درجة","description":"توزيع واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["وضع Sc في الفئة s لأن 4s أعلى مستوى","جعل الأكسجين في المجموعة 6"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.283Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(519, null, null, null, '(أ) مجموع الإلكترونات = 2 + 2 + 6 + 2 + 6 + 2 + 10 + 3 = 33، فالعدد الذري 33. (ب) الفئة p (آخر مستوى ثانوي 4p)، الدورة 4، المجموعة 3 + 12 = 15. (ج) العنصر فوقه في الدورة 3 والمجموعة 15: 1s² 2s² 2p⁶ 3s² 3p³.', '["العدد الذري 33","الفئة p","الدورة 4","المجموعة 15","توزيع العنصر فوقه 1s² 2s² 2p⁶ 3s² 3p³"]'::jsonb, '["جمع الإلكترونات: 33","آخر مستوى ثانوي 4p ← فئة p","n = 4 ← الدورة 4 ؛ المجموعة = 3 + 12 = 15","الدورة السابقة مع التوزيع الخارجي نفسه ns² np³ → 3s² 3p³"]'::jsonb, '[{"element":"(أ) العدد الذري","marks":1},{"element":"(ب) الفئة والدورة والمجموعة","marks":3},{"element":"(ج) التوزيع المطلوب","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4–5 درجات","description":"خطأ واحد في (ب) أو (ج)"},{"level":"2–3 درجات","description":"(أ) صحيح مع جزء من (ب)"},{"level":"1 درجة","description":"العدد الذري فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عدّ الفئة d بسبب 3d¹⁰","كتابة توزيع عنصر في الدورة نفسها بدل المجموعة نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.283Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(520, null, null, null, 'العبارة خاطئة. صحيح أن أعلى مستوى رئيسي هو n = 4 (فالدورة 4)، لكن الفئة يحددها آخر مستوى ثانوي يُملأ بالإلكترونات وهو 3d⁵، فالعنصر من الفئة d، ورقم مجموعته = عدد إلكترونات d + 2 = 5 + 2 = 7. التصحيح: العنصر في الفئة d، الدورة 4، المجموعة 7.', '["الحكم بخطأ العبارة","الفئة تحدد بآخر مستوى ثانوي يُملأ","الفئة d","المجموعة 7 بقاعدة d + 2","الدورة 4"]'::jsonb, '["آخر مستوى ثانوي يُملأ: 3d ← الفئة d","المجموعة = 5 + 2 = 7","الدورة = أعلى مستوى رئيسي = 4"]'::jsonb, '[{"element":"الحكم مع التعليل","marks":2},{"element":"التصحيح: الفئة والمجموعة","marks":2},{"element":"الدورة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح معلل وتصحيح كامل"},{"level":"3–4 درجات","description":"حكم صحيح مع تصحيح ناقص"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"الموافقة على العبارة"}]'::jsonb, '["الموافقة على أن الفئة يحددها المستوى 4s","كتابة المجموعة 5 بدل 7"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.284Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(521, 2, 'الحجم الذري هو الحيز الذي تشغله الذرة، ولأنه لا يقاس مباشرة يُعبَّر عنه بنصف قطر الذرة.', '["هذا العدد الكتلي، ولا يعبر عن الحيز الذي تشغله الذرة.","نصف القطر يحسب من المسافة بين نواتي ذرتين متماثلتين متجاورتين، لا من عنصرين مختلفين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.286Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(522, 0, 'السحابة الإلكترونية حول النواة لا تنتهي عند سطح محدد، لذلك يحدد الحجم من المسافة بين نواتي ذرتين متجاورتين.', '["","النواة صغيرة جدًا مقارنة بحجم الذرة، ومعظم حجم الذرة تشغله السحابة الإلكترونية.","الذرة المتعادلة المنفردة تحتوي على إلكترونات عددها يساوي عدد بروتوناتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.286Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(523, 1, 'أنصاف أقطار الذرات صغيرة جدًا، لذا تقاس عادة بالبيكومتر (1 pm = 1×10⁻¹² m).', '["الكيلومتر وحدة طول كبيرة جدًا لا تناسب أبعاد الذرات.","","المليلتر وحدة حجم وليست وحدة طول لقياس نصف القطر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.286Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(524, 2, 'نصف قطر الذرة نصف المسافة بين نواتي ذرتين متماثلتين مرتبطتين: 228 ÷ 2 = 114 pm.', '["ضُربت المسافة في 2 بدل قسمتها؛ المسافة بين النواتين تساوي مجموع نصفي القطرين.","هذا تكرار لخطأ الطالب؛ المسافة بين النواتين تساوي ضعف نصف القطر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.287Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(525, 0, 'نصف القطر الذري يعبر عن حجم الذرة، فكبر نصف القطر يعني كبر الحجم.', '["","نصف القطر لا يدل على الكتلة؛ فقد تكون ذرة أثقل وأصغر حجمًا (مثل Cl مقارنة بـ Na).","عدد البروتونات قد يكون أكبر في الذرة الأصغر حجمًا، كما في عناصر يمين الدورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.287Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(526, 1, 'تمثل الدائرتان المتداخلتان ذرتي لافلز مرتبطتين برابطة في جزيء ثنائي مثل Br₂، أما المتلاصقتان فتمثلان ذرات الفلز المتجاورة في البلورة.', '["ذرات الفلز المتجاورة في البلورة تُمثَّل بدائرتين متلاصقتين لا متداخلتين.","","الرسم يخص ذرتين متماثلتين من العنصر نفسه لا أيونين مختلفين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.287Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(527, 2, 'نصف قطر الذرة = نصف المسافة بين نواتي الذرتين المتماثلتين المرتبطتين: 266 ÷ 2 = 133 pm.', '["هذه المسافة كاملة بين النواتين، وهي تساوي ضعف نصف القطر.","ضُربت المسافة في 2 بدل القسمة عليها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.289Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(528, null, null, null, 'الحجم الذري هو الحيز الذي تشغله الذرة. ولأن السحابة الإلكترونية حول النواة ليس لها حدود واضحة، فلا يمكن قياس حجم الذرة المنفردة مباشرة، لذلك يُعبَّر عنه بنصف قطر الذرة الذي يحدد من المسافة بين نواتي ذرتين متجاورتين. ويقاس نصف القطر عادة بالبيكومتر (1 pm = 1×10⁻¹² m).', '["تعريف الحجم الذري","السحابة الإلكترونية بلا حدود واضحة","يحدد من المسافة بين نواتين متجاورتين","الوحدة pm"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"تعليل التعبير بنصف القطر","marks":2},{"element":"الوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وتعليل كامل والوحدة"},{"level":"2–3 درجات","description":"تعريف صحيح مع تعليل ناقص أو دون الوحدة"},{"level":"1 درجة","description":"التعريف أو الوحدة فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الادعاء بأن للذرة سطحًا خارجيًا محددًا","الخلط بين الحجم الذري والكتلة الذرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.289Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(529, null, null, null, '(أ) نصف القطر = المسافة بين النواتين ÷ 2 = 228 pm ÷ 2 = 114 pm. (ب) 114 pm × 1×10⁻¹² m/pm = 1.14×10⁻¹⁰ m.', '["نصف القطر = نصف المسافة","114 pm","استخدام 1 pm = 1×10⁻¹² m","1.14×10⁻¹⁰ m"]'::jsonb, '["r = d ÷ 2 = 228 ÷ 2 = 114 pm","r = 114 × 10⁻¹² m = 1.14×10⁻¹⁰ m"]'::jsonb, '[{"element":"العلاقة والناتج 114 pm","marks":2},{"element":"التحويل إلى المتر","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الجزآن صحيحان بالوحدات"},{"level":"2–3 درجات","description":"(أ) صحيح مع خطأ في التحويل"},{"level":"1 درجة","description":"كتابة أن نصف القطر نصف المسافة دون حساب صحيح"},{"level":"صفر","description":"اعتبار نصف القطر 228 pm أو لا إجابة"}]'::jsonb, '["اعتبار المسافة كاملة نصف القطر","التحويل باستخدام 10⁻⁹ بدل 10⁻¹²"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.290Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(530, null, null, null, 'في الفلزات: نصف القطر هو نصف المسافة بين نواتي ذرتين متجاورتين في الشبكة البلورية للفلز، ويمثلها رسم دائرتين متلاصقتين. في اللافلزات (مثل Br₂): نصف القطر هو نصف المسافة بين نواتي ذرتين متماثلتين مرتبطتين برابطة كيميائية في الجزيء، ويمثلها رسم دائرتين متداخلتين. وفي الحالتين نأخذ نصف المسافة بين النواتين.', '["تعريف نصف قطر الفلز","رسم الدائرتين المتلاصقتين","تعريف نصف قطر اللافلز","رسم الدائرتين المتداخلتين","القاسم المشترك: نصف المسافة بين النواتين"]'::jsonb, '[]'::jsonb, '[{"element":"حالة الفلز ورسمها","marks":2},{"element":"حالة اللافلز ورسمها","marks":2},{"element":"وجه التشابه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة بالتعريفين والرسمين ووجه التشابه"},{"level":"3–4 درجات","description":"التعريفان صحيحان مع نقص في الرسم"},{"level":"1–2 درجة","description":"تعريف حالة واحدة فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عكس الرسمين بين الفلز واللافلز","أخذ المسافة كاملة بدل نصفها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.290Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(531, 1, 'نصف قطر ذرة الفلز هو نصف المسافة بين نواتي ذرتين متجاورتين في الشبكة البلورية للفلز.', '["المسافة الكاملة بين النواتين تساوي ضعف نصف القطر.","","هذا تعريف نصف قطر ذرة اللافلز الموجود في صورة جزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.294Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(532, 2, 'نصف قطر ذرة الفلز = نصف المسافة بين النواتين المتجاورتين = 372 ÷ 2 = 186 pm.', '["هذه المسافة كاملة بين النواتين لا نصفها.","ضُربت المسافة في 2 بدل القسمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T11:15:01.294Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(533, 0, 'المسافة بين النواتين = 2 × نصف القطر = 2 × 160 = 320 pm.', '["","قُسم نصف القطر على 2 بدل ضربه، أي عُكست العلاقة.","هذه قيمة نصف القطر لا المسافة بين النواتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-11T11:15:01.294Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(534, 1, 'ذرات الفلز في البلورة متجاورة يلامس بعضها بعضًا، فتمثل بدائرتين متلاصقتين، ونصف القطر نصف المسافة بين مركزيهما.', '["الدائرتان المتداخلتان تمثلان ذرتي لافلز مرتبطتين في جزيء.","","ذرات الفلز في البلورة متراصة ولا تفصلها فراغات كبيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.295Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(535, 0, 'نصف القطر = المسافة ÷ 2: Li = 304 ÷ 2 = 152 pm، K = 454 ÷ 2 = 227 pm، Ca = 394 ÷ 2 = 197 pm.', '["","نصف قطر ذرة K = 454 ÷ 2 = 227 pm.","نصف قطر ذرة Li = 304 ÷ 2 = 152 pm."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:01.295Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(536, 2, 'حدود السحابة الإلكترونية غير واضحة فلا يقاس حجم الذرة المنفردة مباشرة، أما المسافة بين نواتي ذرتين متجاورتين في البلورة فيمكن قياسها.', '["ذرة الفلز المنفردة تملك إلكترونات تكافؤ (مثل 3s¹ في الصوديوم).","عدد البروتونات يميز العنصر ولا يتغير داخل البلورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.296Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(537, 1, 'نصف القطر = 256 ÷ 2 = 128 pm، وبالتحويل: 128 × 10⁻¹² m = 1.28×10⁻¹⁰ m.', '["حُوّلت المسافة كاملة إلى المتر دون قسمتها على 2.","","كُتب الرقم 1.28 مع 10⁻¹² دون تعديل الأس بعد نقل الفاصلة (128 pm = 1.28×10⁻¹⁰ m)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-11T11:15:01.296Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(538, null, null, null, 'نصف قطر الذرة للفلزات هو نصف المسافة بين نواتي ذرتين متجاورتين في الشبكة البلورية للفلز. الحساب: r = 454 pm ÷ 2 = 227 pm.', '["التعريف: نصف المسافة بين نواتين متجاورتين","ذكر الشبكة البلورية للفلز","العلاقة r = d ÷ 2","الناتج 227 pm"]'::jsonb, '["r = d ÷ 2","r = 454 ÷ 2 = 227 pm"]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"العلاقة والتعويض","marks":1},{"element":"الناتج بالوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وحساب صحيح بالوحدة"},{"level":"2–3 درجات","description":"تعريف ناقص مع حساب صحيح أو العكس"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["إغفال كلمة «نصف» في التعريف","كتابة الناتج 454 pm أو 908 pm"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-11T11:15:01.296Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(539, null, null, null, '(أ) Na: 372 ÷ 2 = 186 pm ؛ I: 266 ÷ 2 = 133 pm. (ب) الصوديوم فلز فتؤخذ المسافة بين نواتي ذرتين متجاورتين في شبكته البلورية، واليود لافلز يوجد على شكل جزيئات فتؤخذ المسافة بين نواتي ذرتيه المرتبطتين برابطة في الجزيء. (ج) ذرة الصوديوم أكبر حجمًا لأن نصف قطرها أكبر (186 pm > 133 pm).', '["186 pm للصوديوم","133 pm لليود","الفلز: ذرتان متجاورتان في البلورة","اللافلز: ذرتان مرتبطتان في جزيء","الصوديوم أكبر حجمًا"]'::jsonb, '["r(Na) = 372 ÷ 2 = 186 pm","r(I) = 266 ÷ 2 = 133 pm","مقارنة: 186 > 133"]'::jsonb, '[{"element":"(أ) الحسابان","marks":2},{"element":"(ب) الفرق بين الطريقتين","marks":2},{"element":"(ج) المقارنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"الحسابان صحيحان مع نقص في التوضيح"},{"level":"1–2 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تطبيق تعريف الفلز على اليود","اعتبار اليود أكبر لأن كتلته أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-11T11:15:01.297Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(540, null, null, null, 'إجابة الطالب خاطئة؛ لأن المسافة بين نواتي ذرتين متجاورتين متلاصقتين تساوي مجموع نصفي قطريهما أي ضعف نصف القطر. التصحيح: r = 286 ÷ 2 = 143 pm. والتحقق العكسي: المسافة = 2 × 143 = 286 pm، وهي تطابق القياس.', '["الحكم بخطأ الإجابة","التعليل: المسافة = ضعف نصف القطر","التصحيح 143 pm","الحساب العكسي 286 pm"]'::jsonb, '["r = 286 ÷ 2 = 143 pm","d = 2 × 143 = 286 pm"]'::jsonb, '[{"element":"الحكم مع التعليل","marks":2},{"element":"التصحيح","marks":1},{"element":"الحساب العكسي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم معلل وتصحيح وحساب عكسي صحيح"},{"level":"2–3 درجات","description":"تصحيح صحيح دون تعليل كافٍ"},{"level":"1 درجة","description":"الحكم بالخطأ فقط"},{"level":"صفر","description":"الموافقة على إجابة الطالب"}]'::jsonb, '["الموافقة على أن نصف القطر هو المسافة كاملة","قسمة 143 على 2 في الحساب العكسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:01.298Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(541, 0, 'في الدورة تزداد الشحنة الموجبة للنواة بينما تضاف الإلكترونات إلى المستوى الرئيسي نفسه، فيزداد جذب النواة لإلكترونات التكافؤ ويصغر نصف القطر.', '["","عدد المستويات الرئيسية ثابت في الدورة الواحدة؛ زيادته تحدث في المجموعة.","عدد إلكترونات المستوى الخارجي يزداد في الدورة لا يقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.301Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(542, 2, 'عناصر الدورة الواحدة لها العدد نفسه من مستويات الإلكترونات الداخلية، فلا يتغير الحجب تقريبًا، ولذلك يظهر أثر زيادة الشحنة النووية.', '["الحجب يزداد بزيادة عدد المستويات الداخلية، وهذا يحدث نزولًا في المجموعة لا في الدورة.","الإلكترونات الداخلية موجودة دائمًا فلا يختفي حجبها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T11:15:01.301Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(543, 1, 'كل عناصر الدورة الثانية لها مستويان رئيسيان مشغولان، بينما يزداد عدد البروتونات وإلكترونات التكافؤ من Li إلى F.', '["عدد البروتونات يزداد من 3 في Li إلى 9 في F.","","إلكترونات التكافؤ تزداد من 1 في Li إلى 7 في F."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.302Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(544, 2, 'زيادة الإلكترونات في الدورة لا تضيف مستوى جديدًا، بل تضاف إلى المستوى الخارجي نفسه، ومع زيادة الشحنة النووية يزداد جذبها فيقل الحجم.', '["إضافة مستوى جديد تحدث عند الانتقال إلى دورة جديدة لا داخل الدورة.","عدد الإلكترونات يزداد بزيادة العدد الذري في الدورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.302Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(545, 0, 'العدد الذري يزداد من 11 إلى 14 فتزداد الشحنة النووية، والإلكترونات تضاف إلى المستوى الثالث نفسه، فيزداد جذبها ويقل نصف القطر من 186 إلى 118 pm.', '["","جميع هذه العناصر في الدورة الثالثة فلها ثلاثة مستويات رئيسية فقط.","الجدول يبين أن العدد الذري (عدد البروتونات) يزداد لا يقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.303Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(546, 1, 'تزداد الشحنة النووية والحجب ثابت تقريبًا، فتزداد قوة جذب النواة لإلكترونات التكافؤ، وهذا سبب نقص نصف القطر.', '["قوة الجذب تقل نزولًا في المجموعة لا في الدورة.","","زيادة عدد البروتونات تغير قوة الجذب فلا تبقى ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T11:15:01.303Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(547, 0, 'N وO كلاهما في الدورة الثانية بمستويين رئيسيين، لكن نواة O فيها 8 بروتونات مقابل 7، فتجذب إلكترونات المستوى الثاني بقوة أكبر.', '["","لكليهما مستويان رئيسيان مشغولان (الدورة الثانية).","لكليهما إلكترونان داخليان فقط (1s²)، فالحجب متساوٍ تقريبًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.304Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(548, null, null, null, 'لأنه عند الانتقال من عنصر إلى الذي يليه في الدورة يزداد عدد البروتونات فتزداد الشحنة الموجبة للنواة، بينما يضاف الإلكترون الجديد إلى المستوى الرئيسي نفسه، ويبقى عدد الإلكترونات الداخلية (الحجب) ثابتًا تقريبًا. لذلك تزداد قوة جذب النواة لإلكترونات المستوى الخارجي فتقترب منها، فيقل نصف قطر الذرة.', '["زيادة الشحنة النووية (عدد البروتونات)","الإلكترونات تضاف إلى المستوى الرئيسي نفسه","الحجب ثابت تقريبًا","زيادة الجذب واقتراب الإلكترونات من النواة"]'::jsonb, '[]'::jsonb, '[{"element":"زيادة الشحنة النووية","marks":1},{"element":"ثبات المستوى الرئيسي والحجب","marks":1},{"element":"زيادة الجذب ونقص نصف القطر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل يربط الشحنة بثبات المستوى وزيادة الجذب"},{"level":"2 درجة","description":"ذكر زيادة الشحنة وزيادة الجذب دون ثبات المستوى"},{"level":"1 درجة","description":"ذكر زيادة عدد البروتونات فقط"},{"level":"صفر","description":"تعليل خاطئ كزيادة عدد المستويات"}]'::jsonb, '["التعليل بزيادة عدد مستويات الطاقة","الاعتقاد أن زيادة الإلكترونات تكبر الذرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:01.304Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(549, null, null, null, 'Li: 1s² 2s¹ ، F: 1s² 2s² 2p⁵. كلاهما يملك مستويين رئيسيين (الدورة الثانية). نصف قطر Li أكبر؛ لأن نواة F تحتوي على 9 بروتونات مقابل 3 في Li، والإلكترونات المضافة في F تدخل المستوى الثاني نفسه والحجب بإلكتروني 1s² متساوٍ، فتجذب نواة F إلكترونات المستوى الثاني بقوة أكبر فيصغر نصف قطرها.', '["توزيع Li","توزيع F","Li أكبر نصف قطر","التفسير بالشحنة النووية مع تساوي المستويات والحجب"]'::jsonb, '[]'::jsonb, '[{"element":"التوزيعان","marks":2},{"element":"تحديد الأكبر","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"توزيعان صحيحان وتحديد صحيح وتفسير كامل"},{"level":"3–4 درجات","description":"تحديد صحيح مع تفسير ناقص"},{"level":"1–2 درجة","description":"التوزيعان فقط أو التحديد دون تفسير"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اختيار F أكبر لأن إلكتروناته أكثر","إغفال تساوي عدد المستويات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.305Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(550, null, null, null, '(أ) يقل نصف القطر بزيادة العدد الذري من Na (186 pm) إلى S (103 pm). (ب) لأن الشحنة النووية تزداد والإلكترونات تضاف إلى المستوى الثالث نفسه مع ثبات الحجب تقريبًا، فيزداد الجذب ويقل نصف القطر. (ج) أصغر؛ لأن Cl يقع يمين S في الدورة نفسها وشحنة نواته أكبر.', '["وصف النقص","التفسير بالشحنة وثبات المستوى","توقع أن Cl أصغر","تعليل التوقع"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) وصف التدرج","marks":1},{"element":"(ب) التفسير","marks":2},{"element":"(ج) التوقع مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة ومعللة"},{"level":"3–4 درجات","description":"خطأ أو نقص في جزء واحد"},{"level":"1–2 درجة","description":"وصف التدرج فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["توقع أن Cl أكبر لأن عدده الذري أكبر","وصف التدرج بالزيادة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.306Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(551, 0, 'يقل نصف القطر في الدورة من اليسار إلى اليمين، والصوديوم أقصى اليسار (المجموعة 1) فهو الأكبر.', '["","Al يقع يمين Na فنصف قطره أصغر.","S يقع أقصى اليمين بين الخيارات فهو الأصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T11:15:01.309Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(552, 2, 'في الدورة يقل نصف القطر من اليسار إلى اليمين: Li (المجموعة 1) ثم C (14) ثم O (16)، فالأصغر O والأكبر Li.', '["هذا الترتيب تنازلي لا تصاعدي (عُكس الاتجاه).","O يقع يمين C فنصف قطره أصغر لا أكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.309Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(553, 1, 'Mg في المجموعة 2 وCl في المجموعة 17 من الدورة نفسها، ونصف القطر يقل نحو اليمين فـ Mg أكبر.', '["زيادة الإلكترونات في الدورة لا تكبر الذرة لأنها تضاف للمستوى نفسه مع زيادة جذب النواة.","","تساوي عدد المستويات لا يعني تساوي الحجم؛ الشحنة النووية مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:01.310Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(554, 0, 'كلاهما في الدورة الثالثة؛ X في المجموعة 13 وY في المجموعة 17. وبما أن نصف القطر يقل نحو اليمين فـ X أكبر.', '["","كثرة إلكترونات التكافؤ في الدورة نفسها تعني شحنة نووية أكبر وحجمًا أصغر.","تساوي عدد المستويات يجعلهما في دورة واحدة، لكن الشحنة النووية تختلف فيختلف الحجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.310Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(555, 2, 'النيتروجين أكبر الثلاثة عددًا ذريًا وأبعدها إلى يمين الدورة، فنصف قطره هو الأصغر: 75 pm (وB = 85 pm وLi = 152 pm).', '["85 pm قيمة البورون الذي يقع يسار النيتروجين.","152 pm أكبر القيم وتخص الليثيوم أقصى يسار الدورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.311Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(556, 1, 'البروم في المجموعة 17 فهو أبعد الثلاثة إلى اليمين، ونصف القطر يقل في الدورة من اليسار إلى اليمين.', '["K في المجموعة 1 فهو أكبرها حجمًا.","","Ca في المجموعة 2 فهو أكبر من Br."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T11:15:01.311Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(557, 2, 'في الدورة الواحدة يقع عنصر المجموعة 2 يسار عنصر المجموعة 16، ونصف القطر يقل نحو اليمين.', '["رقم المجموعة الأكبر في الدورة نفسها يعني شحنة نووية أكبر وحجمًا أصغر.","وجودهما في دورة واحدة لا يعني تساوي حجميهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:01.312Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(558, null, null, null, 'الترتيب تنازليًا: Na > Mg > Al > P > Cl. التعليل: العناصر في الدورة نفسها (لها ثلاثة مستويات رئيسية)، وكلما اتجهنا يمينًا يزداد العدد الذري (الشحنة النووية) وتضاف الإلكترونات إلى المستوى الثالث نفسه، فيزداد جذب النواة لها ويقل نصف القطر.', '["الترتيب الصحيح Na > Mg > Al > P > Cl","العناصر في الدورة نفسها","زيادة الشحنة النووية نحو اليمين","زيادة الجذب ونقص نصف القطر"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":2},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتعليل كامل"},{"level":"2–3 درجات","description":"ترتيب صحيح مع تعليل ناقص أو خطأ في موضع عنصر واحد"},{"level":"1 درجة","description":"ترتيب معكوس أو تعليل دون ترتيب صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الترتيب تصاعديًا بدل تنازليًا","التعليل بزيادة عدد الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.312Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(559, null, null, null, '(أ) A: 1s² 2s² ، B: 1s² 2s² 2p⁴. (ب) آخر مستوى رئيسي لكليهما n = 2 فهما في الدورة الثانية. (ج) A أكبر حجمًا من B؛ لأن A في المجموعة 2 وB في المجموعة 16 من الدورة نفسها، وشحنة نواة B (8 بروتونات) أكبر من شحنة نواة A (4 بروتونات) مع تساوي عدد المستويات، فيكون جذب نواة B لإلكتروناتها الخارجية أقوى.', '["التوزيعان","كلاهما في الدورة الثانية","A أكبر","التعليل بالشحنة النووية مع تساوي المستويات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التوزيعان","marks":2},{"element":"(ب) الدورة","marks":1},{"element":"(ج) المقارنة والتعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في جزء واحد"},{"level":"1–2 درجة","description":"التوزيعان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اعتبار B أكبر لأن عدد إلكتروناته أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.313Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(560, null, null, null, '(أ) بين 77 pm و112 pm (القيمة الفعلية نحو 85 pm). (ب) لأن البورون يقع بين Be وC في الدورة الثانية، ونصف القطر يقل بانتظام من اليسار إلى اليمين بزيادة الشحنة النووية مع ثبات عدد المستويات، فيكون أصغر من Be وأكبر من C. (ج) النيتروجين N (75 pm) لأنه أبعدها إلى اليمين.', '["المدى بين 77 و112 pm","B بين Be وC في الدورة","التدرج بنقص نصف القطر نحو اليمين","N الأصغر"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التوقع","marks":1},{"element":"(ب) التعليل","marks":2},{"element":"(ج) الأصغر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توقع صحيح معلل وتحديد الأصغر"},{"level":"2–3 درجات","description":"توقع صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"تحديد الأصغر فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["توقع قيمة أكبر من 112 pm","اختيار Li الأصغر بسبب صغر عدده الذري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.314Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(561, 1, 'كلما نزلنا في المجموعة يزداد رقم الدورة فيزداد عدد المستويات الرئيسية المشغولة، فتصبح إلكترونات التكافؤ أبعد عن النواة ويكبر نصف القطر.', '["الشحنة النووية تزداد نزولًا في المجموعة لا تقل.","","عدد الإلكترونات الداخلية يزداد نزولًا فيزداد الحجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.317Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(562, 0, 'تزداد الإلكترونات الداخلية نزولًا في المجموعة فتحجب إلكترونات التكافؤ عن النواة، فيضعف جذبها وتبتعد فيكبر الحجم.', '["","الإلكترونات الداخلية سالبة تتنافر مع إلكترونات التكافؤ وتقلل أثر النواة، لا تزيد جذبها.","عدد إلكترونات التكافؤ ثابت في المجموعة الواحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.318Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(563, 2, 'زيادة عدد المستويات الرئيسية تبعد إلكترونات التكافؤ، وزيادة الإلكترونات الداخلية تحجبها، وهذان الأثران أقوى من أثر زيادة الشحنة النووية.', '["عدد البروتونات يزداد بزيادة العدد الذري نزولًا في المجموعة.","عناصر المجموعة الواحدة لها العدد نفسه من إلكترونات التكافؤ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.318Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(564, 0, 'Be في الدورة الثانية (2s²) وCa في الدورة الرابعة (4s²)، فإلكترونات تكافؤ Ca في مستوى أبعد عن النواة ومحجوبة بعدد أكبر من الإلكترونات الداخلية.', '["","لكل منهما إلكترونا تكافؤ لأنهما في المجموعة 2.","شحنة نواة Ca (20) أكبر من شحنة نواة Be (4)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.319Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(565, 1, 'يزداد عدد المستويات من 2 في Li إلى 5 في Rb، ويزداد نصف القطر معه من 152 إلى 248 pm، فالعلاقة طردية.', '["البيانات تبين أن نصف القطر يزداد لا يقل بزيادة المستويات.","","البيانات تبين زيادة منتظمة في نصف القطر مع كل مستوى إضافي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.319Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(566, 2, 'إلكترونات التكافؤ تشغل مستوى رئيسيًا أعلى رقمًا في كل دورة تالية، فتكون أبعد عن النواة.', '["البعد يقل في الدورة من اليسار لليمين، أما في المجموعة فيزداد.","عدد المستويات يتغير في المجموعة فلا يبقى البعد ثابتًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.319Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(567, 1, 'صحيح أن شحنة نواة K أكبر، لكن إلكترون تكافئه في المستوى الرابع (4s¹) لا الثالث، ومحجوب بثمانية عشر إلكترونًا داخليًا، فيكون أبعد وأضعف انجذابًا فتكبر الذرة.', '["K (Z = 19) له بروتونات أكثر من Na (Z = 11).","","لكل منهما إلكترون تكافؤ واحد لأنهما في المجموعة 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.321Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(568, null, null, null, 'لأنه كلما نزلنا في المجموعة يزداد عدد مستويات الطاقة الرئيسية المشغولة بالإلكترونات (بزيادة رقم الدورة)، فتصبح إلكترونات التكافؤ أبعد عن النواة، كما يزداد عدد الإلكترونات الداخلية التي تحجبها عن جذب النواة. ومع أن الشحنة النووية تزداد أيضًا، فإن أثر زيادة المستويات والحجب يكون هو الغالب، فيضعف الجذب ويكبر نصف القطر.', '["زيادة عدد المستويات الرئيسية","بعد إلكترونات التكافؤ عن النواة","زيادة الحجب بالإلكترونات الداخلية","غلبة هذه العوامل على زيادة الشحنة النووية"]'::jsonb, '[]'::jsonb, '[{"element":"زيادة المستويات وبعد الإلكترونات","marks":2},{"element":"الحجب","marks":1},{"element":"غلبة الأثر على زيادة الشحنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل بالعوامل الثلاثة"},{"level":"2–3 درجات","description":"ذكر زيادة المستويات مع عامل آخر"},{"level":"1 درجة","description":"ذكر زيادة المستويات فقط"},{"level":"صفر","description":"تعليل خاطئ"}]'::jsonb, '["التعليل بنقص الشحنة النووية","التعليل بزيادة إلكترونات التكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:01.322Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(569, null, null, null, 'Be: 1s² 2s² ، Ca: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s². إلكترونا تكافؤ Be في المستوى الثاني، أما إلكترونا تكافؤ Ca ففي المستوى الرابع، أي أبعد عن النواة، ويحجبهما 18 إلكترونًا داخليًا مقابل إلكترونين فقط في Be. لذلك يكون جذب نواة Ca لإلكترونات تكافئها أضعف رغم أن شحنتها أكبر، فيكون نصف قطرها أكبر.', '["توزيع Be","توزيع Ca","المستوى الرابع مقابل الثاني","الحجب 18 مقابل 2","غلبة البعد والحجب على الشحنة"]'::jsonb, '[]'::jsonb, '[{"element":"التوزيعان","marks":2},{"element":"التفسير بعدد المستويات","marks":1},{"element":"التفسير بالحجب وغلبته على الشحنة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"توزيعان صحيحان وتفسير كامل"},{"level":"3–4 درجات","description":"تفسير صحيح جزئيًا مع توزيعين صحيحين"},{"level":"1–2 درجة","description":"التوزيعان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن إلكترونات تكافؤ Ca أكثر","إغفال تفسير غلبة البعد على زيادة الشحنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.322Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(570, null, null, null, 'في الدورة: عدد المستويات الرئيسية ثابت والحجب ثابت تقريبًا، فيكون العامل الحاسم زيادة الشحنة النووية التي تزيد جذب إلكترونات المستوى الخارجي فيقل نصف القطر. في المجموعة: يضاف مستوى رئيسي جديد مع كل دورة فتبتعد إلكترونات التكافؤ ويزداد الحجب بالإلكترونات الداخلية، فيكون العامل الحاسم زيادة عدد المستويات (والحجب) الذي يغلب أثر زيادة الشحنة فيزداد نصف القطر.', '["في الدورة المستويات والحجب ثابتة","العامل الحاسم في الدورة: الشحنة النووية","في المجموعة يضاف مستوى جديد ويزداد الحجب","العامل الحاسم في المجموعة: عدد المستويات"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل حالة الدورة","marks":2},{"element":"تحليل حالة المجموعة","marks":2},{"element":"المقارنة بالعامل الحاسم","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل كامل للحالتين مع العامل الحاسم"},{"level":"3–4 درجات","description":"تحليل صحيح لحالة وناقص للأخرى"},{"level":"1–2 درجة","description":"وصف التدرج دون تحليل"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الشحنة النووية تقل في المجموعة","إغفال دور الحجب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(571, 2, 'يزداد نصف القطر في المجموعة من الأعلى إلى الأسفل، والبوتاسيوم أسفلها بين الخيارات (الدورة الرابعة).', '["Na في الدورة الثالثة فوق K، فهو أصغر منه.","Li في الدورة الثانية أعلى المجموعة، فهو أصغرها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.326Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(572, 0, 'في المجموعة يزداد نصف القطر نزولًا: F (الدورة 2) ثم Cl (3) ثم Br (4).', '["","هذا ترتيب تنازلي (معكوس).","F أعلى من Cl في المجموعة فهو أصغر منه لا أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.326Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(573, 1, 'كلاهما في المجموعة 17 (7 إلكترونات تكافؤ)، لكن Y في الدورة الثالثة وX في الثانية، فإلكترونات تكافؤ Y أبعد عن النواة وحجمه أكبر.', '["قلة الشحنة النووية لا تجعل X أكبر؛ العامل الحاسم في المجموعة عدد المستويات.","","تساوي إلكترونات التكافؤ يضعهما في مجموعة واحدة لكن لا يعني تساوي الحجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.327Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(574, 2, 'نصف القطر يزداد بانتظام نزولًا في المجموعة (160 → 197 → 215)، والباريوم أسفل السترونشيوم فيتوقع أن يكون نصف قطره أكبر من 215 pm.', '["هذا يعني أن Ba أصغر من Mg، وهو يخالف التدرج في المجموعة.","هذا المدى بين Mg وCa، والباريوم يقع أسفل كليهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.327Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(575, 0, 'Se في الدورة الرابعة وO في الثانية، فعدد مستويات Se أكبر وإلكترونات تكافئه أبعد عن النواة، فحجمه أكبر.', '["","O أعلى المجموعة فهو أصغر من Se.","اختلاف عدد المستويات يجعل حجميهما مختلفين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.328Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(576, 1, 'Rb يقع أسفل K في المجموعة 1 فهو أكبر منه. أما Na فيقع فوق K، وCl فوق Br، فالأول أصغر في الحالتين.', '["Na فوق K في المجموعة 1 فهو أصغر منه.","","Cl فوق Br في المجموعة 17 فهو أصغر منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.328Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(577, 0, 'B في الدورة الخامسة فلديه خمسة مستويات رئيسية مشغولة مقابل مستويين لـ A، فإلكترونات تكافئه أبعد وحجمه أكبر.', '["","قلة الشحنة النووية لا تحدد الحجم في المجموعة؛ العامل الحاسم عدد المستويات.","تساوي إلكترونات التكافؤ لا يعني تساوي الحجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.328Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(578, null, null, null, 'الترتيب تصاعديًا: Li < Na < K < Cs. التعليل: هذه العناصر في مجموعة واحدة، وكلما نزلنا فيها يزداد عدد مستويات الطاقة الرئيسية المشغولة (Li الدورة 2، Na الدورة 3، K الدورة 4، Cs الدورة 6)، فتبتعد إلكترونات التكافؤ عن النواة ويزداد الحجب فيكبر نصف القطر.', '["الترتيب Li < Na < K < Cs","العناصر في مجموعة واحدة","زيادة عدد المستويات نزولًا","بعد إلكترون التكافؤ وزيادة الحجب"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":2},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتعليل كامل"},{"level":"2–3 درجات","description":"ترتيب صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"ترتيب معكوس مع تعليل صحيح جزئيًا"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الترتيب حسب الشحنة النووية بأن Cs الأصغر","الترتيب تنازليًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.329Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(579, null, null, null, '(أ) X: 1s² 2s² 2p⁶ 3s² ، Y: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s². (ب) لكل منهما إلكترونا تكافؤ (ns²) فهما في المجموعة 2؛ X في الدورة 3 وY في الدورة 4. (ج) Y أكبر حجمًا؛ لأن إلكترونات تكافئه في المستوى الرابع الأبعد عن النواة، ويحجبها عدد أكبر من الإلكترونات الداخلية.', '["التوزيعان","المجموعة 2 لكليهما","X الدورة 3 وY الدورة 4","Y أكبر","التعليل بعدد المستويات والحجب"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التوزيعان","marks":2},{"element":"(ب) المجموعة والدورتان","marks":1},{"element":"(ج) المقارنة والتعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في جزء واحد"},{"level":"1–2 درجة","description":"التوزيعان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اعتبار X أكبر لأن شحنة نواته أقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.329Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(580, null, null, null, 'B هو الأكبر. المقارنة الأولى (في المجموعة): A وB في المجموعة 1، وB أسفل A فلديه مستوى رئيسي إضافي، لذا B > A. المقارنة الثانية (في الدورة): B وC في الدورة 3، وB في أقصى اليسار وC في اليمين بشحنة نووية أكبر، لذا B > C. إذن B أكبر من العنصرين الآخرين.', '["B الأكبر","مقارنة B وA بقاعدة المجموعة","مقارنة B وC بقاعدة الدورة","الاستنتاج من المقارنتين"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد B","marks":1},{"element":"مقارنة المجموعة","marks":2},{"element":"مقارنة الدورة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح بمقارنتين معللتين"},{"level":"3–4 درجات","description":"تحديد صحيح بمقارنة واحدة معللة"},{"level":"1–2 درجة","description":"تحديد صحيح دون تعليل"},{"level":"صفر","description":"تحديد خاطئ"}]'::jsonb, '["اختيار C لأن عدده الذري أكبر","تطبيق قاعدة الدورة على A وB"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.330Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(581, 1, 'الأيون ذرة أو مجموعة ذرات مرتبطة معًا تحمل شحنة كهربائية موجبة أو سالبة نتيجة فقد إلكترونات أو اكتسابها.', '["هذا وصف الذرة المتعادلة لا الأيون.","","هذا وصف البروتون، وهو جسيم نووي لا أيون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.332Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(582, 0, 'الشحنة الموجبة للبروتونات تعادل الشحنة السالبة للإلكترونات عندما يتساوى عددهما، فتكون الذرة متعادلة.', '["","النيوترونات متعادلة الشحنة فلا يؤثر عددها في شحنة الذرة.","النيوترونات لا تحمل شحنة، فالمقارنة الصحيحة بين البروتونات والإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(583, 2, 'عند فقد الذرة إلكترونًا أو أكثر يصبح عدد البروتونات أكبر من عدد الإلكترونات فتصبح الشحنة موجبة، مثل Na → Na⁺.', '["عدد البروتونات لا يتغير عند تكوين الأيونات.","اكتساب الإلكترونات يكوّن أيونًا سالبًا (أنيونًا).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(584, 0, 'الذرة المتعادلة فيها 12 إلكترونًا، والشحنة 2+ تعني فقد إلكترونين: 12 − 2 = 10 إلكترونات.', '["","أُضيف إلكترونان بدل طرحهما؛ الشحنة الموجبة تعني فقد إلكترونات.","هذا عدد إلكترونات الذرة المتعادلة لا الأيون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(585, 1, 'B فيه 17 بروتونًا و18 إلكترونًا، فالإلكترونات أكثر بواحد وشحنته 1− (أيون سالب). A أيون موجب (11 بروتونًا و10 إلكترونات)، وC متعادل.', '["A فيه بروتونات أكثر من الإلكترونات فهو أيون موجب.","","C عدد بروتوناته يساوي عدد إلكتروناته فهو ذرة متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(586, 2, 'NH₄⁺ مجموعة ذرات مرتبطة تحمل شحنة موجبة، فهو أيون متعدد الذرات (الأمونيوم).', '["H₂O جزيء متعادل لا يحمل شحنة.","Ne ذرة غاز نبيل متعادلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(587, 0, 'تكوين الأيون يكون بتغير عدد الإلكترونات فقط؛ يكتسب الكلور إلكترونًا فيصبح فيه 18 إلكترونًا ويبقى عدد بروتوناته 17.', '["","الذي يزداد إلى 18 هو عدد الإلكترونات لا البروتونات.","البروتونات لا تُفقد عند تكوين الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(588, null, null, null, 'الأيون: ذرة أو مجموعة ذرات تحمل شحنة كهربائية موجبة أو سالبة. الأيون الموجب (الكاتيون) يتكون بفقد الذرة إلكترونًا أو أكثر، فيصبح عدد البروتونات أكبر من عدد الإلكترونات، مثل Na⁺ وCa²⁺. الأيون السالب (الأنيون) يتكون باكتساب الذرة إلكترونًا أو أكثر، فيصبح عدد الإلكترونات أكبر من عدد البروتونات، مثل Cl⁻ وO²⁻.', '["تعريف الأيون","الموجب: فقد إلكترونات","الموجب: البروتونات أكثر","السالب: اكتساب إلكترونات","السالب: الإلكترونات أكثر","مثال لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الأيون الموجب","marks":2},{"element":"الأيون السالب","marks":2},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بالمثالين"},{"level":"4–5 درجات","description":"نقص عنصر واحد"},{"level":"2–3 درجات","description":"التعريف مع وصف نوع واحد"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الأيون الموجب يتكون باكتساب بروتونات","عكس المثالين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(589, null, null, null, 'Na⁺: بروتونات 11، إلكترونات 11 − 1 = 10، موجب. O²⁻: بروتونات 8، إلكترونات 8 + 2 = 10، سالب. Al³⁺: بروتونات 13، إلكترونات 13 − 3 = 10، موجب. S²⁻: بروتونات 16، إلكترونات 16 + 2 = 18، سالب.', '["البروتونات تساوي العدد الذري","طرح الشحنة الموجبة من عدد الإلكترونات","إضافة الشحنة السالبة لعدد الإلكترونات","تحديد نوع كل أيون"]'::jsonb, '["Na⁺: e = 11 − 1 = 10","O²⁻: e = 8 + 2 = 10","Al³⁺: e = 13 − 3 = 10","S²⁻: e = 16 + 2 = 18"]'::jsonb, '[{"element":"البروتونات للأيونات الأربعة","marks":1},{"element":"الإلكترونات للأيونات الأربعة","marks":2},{"element":"نوع الأيون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الجدول كله صحيح"},{"level":"2–3 درجات","description":"خطأ في أيون أو اثنين"},{"level":"1 درجة","description":"البروتونات فقط صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تغيير عدد البروتونات بحسب الشحنة","إضافة الشحنة الموجبة إلى عدد الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(590, null, null, null, 'لأن هوية العنصر يحددها عدد البروتونات (العدد الذري) لا عدد الإلكترونات. أيون الصوديوم Na⁺ يحتوي على 11 بروتونًا و10 إلكترونات، أما ذرة النيون فتحتوي على 10 بروتونات و10 إلكترونات. لذلك يبقى الصوديوم صوديومًا لكنه أصبح أيونًا موجبًا شحنته 1+ لأن بروتوناته تزيد على إلكتروناته بواحد.', '["عدد البروتونات يحدد العنصر","Na⁺: 11 بروتونًا و10 إلكترونات","Ne: 10 بروتونات","الشحنة 1+"]'::jsonb, '[]'::jsonb, '[{"element":"التفسير بعدد البروتونات","marks":2},{"element":"المقارنة العددية","marks":1},{"element":"شحنة الأيون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع المقارنة والشحنة"},{"level":"2–3 درجات","description":"تفسير صحيح دون مقارنة عددية"},{"level":"1 درجة","description":"ذكر الشحنة فقط"},{"level":"صفر","description":"الموافقة على تحول الصوديوم إلى نيون"}]'::jsonb, '["الاعتقاد أن تشابه التوزيع يعني تشابه العنصر","كتابة الشحنة 1−"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.335Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(591, 2, 'عند فقد الصوديوم إلكترون 3s¹ يفقد مستواه الخارجي ويقل التنافر بين الإلكترونات المتبقية، فيكون Na⁺ أصغر من Na.', '["الأيون السالب هو الذي يكون أكبر من ذرته.","فقد إلكترون من المستوى الخارجي يغير الحجم بوضوح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.337Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(592, 1, 'الإلكترون المفقود هو الوحيد في المستوى الثالث، فيصبح Na⁺ بتوزيع 1s² 2s² 2p⁶ أي بمستويين رئيسيين فقط، وهذا أحد أسباب صغر حجمه.', '["فقد الإلكترونات لا يضيف مستويات جديدة.","","المستوى الثالث لم يكن فيه إلا إلكترون واحد، وبفقده يصبح فارغًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.337Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(593, 0, 'عدد البروتونات ثابت، ومع نقص عدد الإلكترونات يقل التنافر بينها، فتجذب النواة كل إلكترون متبقٍ بقوة أكبر فيصغر الأيون.', '["","عدد البروتونات لا يتغير عند تكوين الأيون.","التنافر يقل لا يزداد عند نقص عدد الإلكترونات، وزيادته تحدث في الأيون السالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.338Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(594, 2, 'K: 227 → 138 pm، Ca: 197 → 100 pm، Al: 143 → 54 pm؛ في كل حالة نصف قطر الأيون الموجب أصغر من نصف قطر ذرته.', '["القيم تبين أن نصف قطر كل أيون أقل من قيمة ذرته.","الفرق كبير في كل الحالات (مثلًا 89 pm في K)، فالحجم يتغير بوضوح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.338Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(595, 0, 'يفقد المغنيسيوم إلكتروني 3s² فيصبح للأيون 10 إلكترونات بتوزيع 1s² 2s² 2p⁶ (مستويان فقط)، لذلك هو أصغر من ذرة Mg.', '["","هذا توزيع ذرة Mg المتعادلة قبل فقد الإلكترونين.","هذا توزيع لـ 14 إلكترونًا، أي أُضيف إلكترونان بدل فقدهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.338Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(596, 1, 'يبقى في نواة Na⁺ 11 بروتونًا بينما يصبح عدد الإلكترونات 10، فتتوزع قوة جذب النواة على عدد أقل من الإلكترونات فيقوى جذبها لكل إلكترون.', '["هذه حالة الأيون السالب حيث تزيد الإلكترونات على البروتونات.","","التساوي حالة ذرة Na المتعادلة لا الأيون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.339Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(597, 0, 'K (… 4s¹) يفقد إلكترون 4s فيصبح K⁺ بثلاثة مستويات رئيسية فقط، ويقل التنافر بين إلكتروناته مع ثبات عدد البروتونات، فيكون أصغر.', '["","K هو الأكبر لا الأصغر، وكثرة إلكتروناته تزيد التنافر.","النتيجة صحيحة لكن السبب خاطئ؛ عدد البروتونات لا يتغير عند تكوين الأيون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.339Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(598, null, null, null, 'Na: 1s² 2s² 2p⁶ 3s¹ ، Na⁺: 1s² 2s² 2p⁶. السبب الأول: الإلكترون المفقود هو إلكترون التكافؤ الوحيد في المستوى الثالث، فيُفقد المستوى الخارجي كله ويبقى للأيون مستويان رئيسيان فقط. السبب الثاني: يقل عدد الإلكترونات إلى 10 مع بقاء 11 بروتونًا في النواة، فيقل التنافر بين الإلكترونات وتجذبها النواة بقوة أكبر، فيصغر نصف القطر.', '["توزيع Na","توزيع Na⁺","فقد المستوى الخارجي","قلة التنافر بين الإلكترونات","ثبات عدد البروتونات وزيادة الجذب"]'::jsonb, '[]'::jsonb, '[{"element":"التوزيعان","marks":2},{"element":"السبب الأول: فقد المستوى","marks":1},{"element":"السبب الثاني: التنافر والجذب","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"توزيعان صحيحان وسببان كاملان"},{"level":"3–4 درجات","description":"سبب واحد كامل مع التوزيعين"},{"level":"1–2 درجة","description":"التوزيعان فقط أو سبب ناقص"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن عدد البروتونات يزداد","اعتبار Na⁺ أكبر لأنه مشحون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.339Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(599, null, null, null, '(أ) النقص = 197 − 100 = 97 pm، والنسبة المئوية = (97 ÷ 197) × 100 ≈ 49.2%. (ب) يفقد الكالسيوم (… 3p⁶ 4s²) إلكتروني 4s² فيُفقد المستوى الرابع كله ويبقى للأيون ثلاثة مستويات، كما يقل التنافر بين الإلكترونات المتبقية (18 إلكترونًا) مع بقاء 20 بروتونًا في النواة، فيزداد جذب النواة لكل إلكترون ويصغر الأيون.', '["النقص 97 pm","النسبة 49.2% تقريبًا","فقد المستوى الرابع","قلة التنافر وثبات البروتونات"]'::jsonb, '["النقص = 197 − 100 = 97 pm","النسبة = 97 ÷ 197 × 100 = 49.2%"]'::jsonb, '[{"element":"(أ) الحساب","marks":2},{"element":"(ب) التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح وتفسير كامل"},{"level":"2–3 درجات","description":"حساب صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"حساب النقص فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["قسمة النقص على 100 بدل 197","التفسير بزيادة عدد البروتونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.339Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(600, null, null, null, 'لكلا الأيونين التوزيع 1s² 2s² 2p⁶ أي العدد نفسه من الإلكترونات والمستويات. لكن نواة Mg²⁺ تحتوي على 12 بروتونًا مقابل 11 في Na⁺، فالشحنة النووية الأكبر تجذب الإلكترونات العشرة بقوة أكبر، فيكون نصف قطر Mg²⁺ أصغر.', '["التوزيع نفسه 1s² 2s² 2p⁶","عدد البروتونات 12 مقابل 11","الشحنة الأكبر تجذب الإلكترونات أكثر","الاستنتاج: Mg²⁺ أصغر"]'::jsonb, '[]'::jsonb, '[{"element":"ملاحظة تساوي التوزيع","marks":1},{"element":"المقارنة بعدد البروتونات","marks":1},{"element":"الربط بقوة الجذب والحجم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحليل كامل يربط عدد البروتونات بقوة الجذب"},{"level":"2 درجة","description":"ذكر اختلاف عدد البروتونات دون ربط واضح"},{"level":"1 درجة","description":"ذكر تساوي التوزيع فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن Mg²⁺ فقد مستويات أكثر من Na⁺","اعتبار عدد الإلكترونات مختلفًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.340Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(601, 0, 'عند اكتساب الكلور إلكترونًا يزداد التنافر بين الإلكترونات مع بقاء شحنة النواة ثابتة، فيتمدد المستوى الخارجي ويكون Cl⁻ أكبر.', '["","الأيون الموجب هو الذي يكون أصغر من ذرته.","اكتساب إلكترون يغير الحجم بوضوح (من نحو 100 pm إلى 181 pm)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.342Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(602, 2, 'الإلكترونات المضافة تدخل المستوى الخارجي نفسه فيزداد التنافر، بينما تبقى شحنة النواة ثابتة، فيقل جذبها لكل إلكترون ويكبر الأيون.', '["عدد البروتونات لا يتغير عند تكوين الأيون.","الإلكترونات المضافة تدخل المستوى الخارجي الموجود ولا تضيف مستوى جديدًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.342Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(603, 1, 'المستوى الثانوي 2p في الأكسجين فيه 4 إلكترونات ويتسع لـ 6، فيدخله الإلكترونان ليصبح التوزيع 1s² 2s² 2p⁶.', '["لا يلزم مستوى جديد لأن 2p لم يمتلئ بعد.","","المستوى 1s ممتلئ بإلكترونين ولا يتسع لغيرهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.343Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(604, 0, 'مقدار الزيادة = نصف قطر الأيون − نصف قطر الذرة = 184 − 103 = 81 pm.', '["","جُمعت القيمتان بدل طرحهما.","هذا نصف قطر الأيون نفسه لا مقدار الزيادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.343Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(605, 2, 'الشحنة 2− تعني اكتساب إلكترونين: 8 + 2 = 10 إلكترونات، ويبقى عدد البروتونات 8.', '["طُرح إلكترونان بدل إضافتهما؛ الشحنة السالبة تعني اكتساب إلكترونات.","هذا عدد إلكترونات الذرة المتعادلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.343Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(606, 1, 'شحنة النواة ثابتة (9 بروتونات) لكنها توزع جذبها على 10 إلكترونات بدل 9 مع زيادة التنافر، فيقل الجذب لكل إلكترون ويكبر الأيون.', '["شحنة النواة لا تتغير عند اكتساب الإلكترونات.","","ثبات البروتونات لا يعني ثبات الجذب لكل إلكترون، لأن عدد الإلكترونات والتنافر يزدادان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.343Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(607, 0, 'الإلكترون الإضافي يزيد التنافر في المستوى الخارجي دون زيادة في شحنة النواة، فتتباعد الإلكترونات ويكبر الأيون.', '["","عدد البروتونات لا يتغير عند تكوين الأيونات.","الإلكترون المضاف يدخل المستوى الخارجي لا مستوى داخليًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.344Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(608, null, null, null, 'لأن ذرة الكلور تكتسب إلكترونًا يدخل مستواها الخارجي نفسه (3p⁵ → 3p⁶)، فيزداد عدد الإلكترونات إلى 18 بينما يبقى عدد البروتونات 17. فيزداد التنافر بين الإلكترونات ويقل جذب النواة لكل إلكترون، فتتباعد الإلكترونات ويتمدد المستوى الخارجي، فيكبر نصف القطر.', '["اكتساب إلكترون إلى المستوى الخارجي نفسه","ثبات عدد البروتونات","زيادة التنافر","قلة الجذب لكل إلكترون وتمدد المستوى"]'::jsonb, '[]'::jsonb, '[{"element":"اكتساب الإلكترون وثبات البروتونات","marks":1},{"element":"زيادة التنافر","marks":1},{"element":"قلة الجذب وكبر الحجم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل"},{"level":"2 درجة","description":"ذكر زيادة التنافر دون ثبات الشحنة"},{"level":"1 درجة","description":"ذكر اكتساب إلكترون فقط"},{"level":"صفر","description":"تعليل خاطئ كإضافة مستوى جديد"}]'::jsonb, '["القول إن الإلكترون يدخل مستوى رئيسيًا جديدًا","القول إن النواة تجذب الإلكترونات أكثر فيصغر الأيون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:01.344Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(609, null, null, null, 'F: 1s² 2s² 2p⁵ ، F⁻: 1s² 2s² 2p⁶. عدد البروتونات: 9 في كليهما. عدد الإلكترونات: 9 في F و10 في F⁻. نصف القطر: F⁻ أكبر من F، لأن الإلكترون المضاف يدخل المستوى الثاني نفسه فيزداد التنافر بين الإلكترونات بينما تبقى شحنة النواة ثابتة، فيقل جذبها لكل إلكترون ويتمدد المستوى الخارجي.', '["توزيع F","توزيع F⁻","البروتونات 9 في كليهما","الإلكترونات 9 و10","F⁻ أكبر مع التفسير"]'::jsonb, '[]'::jsonb, '[{"element":"التوزيعان","marks":2},{"element":"مقارنة البروتونات والإلكترونات","marks":1},{"element":"مقارنة نصف القطر وتفسيرها","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة"},{"level":"3–4 درجات","description":"خطأ في عنصر واحد"},{"level":"1–2 درجة","description":"التوزيعان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل عدد بروتونات F⁻ يساوي 10","اعتبار F⁻ أصغر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.344Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(610, null, null, null, 'فقد الإلكترونات (Na → Na⁺) يصغّر نصف القطر لأن الذرة تفقد مستواها الخارجي غالبًا ويقل التنافر بين الإلكترونات المتبقية مع ثبات شحنة النواة فيزداد الجذب. أما اكتساب الإلكترونات (Cl → Cl⁻) فيكبّر نصف القطر لأن الإلكترون المضاف يدخل المستوى الخارجي نفسه فيزداد التنافر مع ثبات شحنة النواة فيقل الجذب لكل إلكترون. فالأثر متعاكس لأن عدد الإلكترونات ينقص في الحالة الأولى ويزيد في الثانية بينما تبقى شحنة النواة ثابتة في الحالتين، فيتغير التنافر والجذب في اتجاهين متعاكسين.', '["Na⁺ أصغر من Na","تفسير: فقد المستوى وقلة التنافر","Cl⁻ أكبر من Cl","تفسير: زيادة التنافر","ثبات شحنة النواة في الحالتين وتعاكس الأثر"]'::jsonb, '[]'::jsonb, '[{"element":"حالة فقد الإلكترونات","marks":2},{"element":"حالة اكتساب الإلكترونات","marks":2},{"element":"تفسير التعاكس","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة مع تفسير التعاكس"},{"level":"3–4 درجات","description":"الحالتان صحيحتان دون تفسير التعاكس"},{"level":"1–2 درجة","description":"حالة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عكس أثر الفقد والاكتساب","التفسير بتغير عدد البروتونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.345Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(611, 2, 'طاقة التأين هي الطاقة اللازمة (الممتصة) لنزع إلكترون من ذرة في الحالة الغازية، ونزع الإلكترون الأول يسمى طاقة التأين الأولى.', '["طاقة التأين طاقة ممتصة لنزع إلكترون، لا منطلقة عند إضافته.","التأين يتعلق بنزع الإلكترونات لا البروتونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:01.348Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(612, 0, 'طاقة التأين تخص ذرة في الحالة الغازية تمتص طاقة فتفقد إلكترونًا وتصبح أيونًا موجبًا أحادي الشحنة.', '["","أُغفل شرط الحالة الغازية؛ التعريف يشترط ذرة غازية.","هذه معادلة اكتساب إلكترون وتكوين أيون سالب، لا تأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.349Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(613, 1, 'كلما زادت طاقة التأين احتاج نزع الإلكترون إلى طاقة أكبر، أي أن النواة تجذبه بقوة فيصعب نزعه ويقل ميل الذرة لتكوين أيون موجب.', '["سهولة نزع الإلكترون تعني طاقة تأين منخفضة.","","سهولة تكوين أيون موجب ترتبط بطاقة التأين المنخفضة لا المرتفعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.349Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(614, 2, 'تسمى طاقة التأين أيضًا جهد التأين، كما في أسئلة تدريب المذكرة («الأعلى جهد تأين»).', '["الكهروسالبية قدرة الذرة على جذب إلكترونات الرابطة، وهي خاصية مختلفة.","الحجم الذري يعبر عنه بنصف القطر وليس طاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.349Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(615, 0, 'أقل طاقة تأين في الجدول للصوديوم (496 kJ/mol)، فنزع إلكترونه هو الأسهل، لذا يكوّن أيونًا موجبًا بسهولة أكبر.', '["","طاقة تأين Mg (738 kJ/mol) أعلى من Na فنزع إلكترونه أصعب.","Ar له أعلى طاقة تأين (1521 kJ/mol) فهو الأصعب في فقد الإلكترون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.349Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(616, 1, 'الغازات النبيلة مستواها الخارجي ممتلئ ومستقر، وتقع في نهاية كل دورة، فطاقات تأينها هي الأعلى في دوراتها.', '["الفلزات القلوية لها أقل طاقات تأين في دوراتها.","","الفلزات القلوية الأرضية طاقات تأينها منخفضة نسبيًا لوقوعها في يسار الجدول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.349Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(617, 0, 'الإلكترون مرتبط بالنواة بقوة جذب كهربائية، ولنزعه يجب تزويد الذرة بطاقة تتغلب على هذا الجذب.', '["","نزع الإلكترون يحتاج طاقة ولا يطلقها؛ هذا مفهوم خاطئ شائع.","الإلكترون السالب ينجذب إلى النواة الموجبة ولا يتنافر معها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.350Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(618, null, null, null, 'طاقة التأين: الطاقة اللازمة لنزع إلكترون من ذرة في الحالة الغازية، وطاقة نزع الإلكترون الأول تسمى طاقة التأين الأولى. المعادلة: K(g) + طاقة → K⁺(g) + e⁻ ؛ حيث K(g) ذرة بوتاسيوم غازية متعادلة، والطاقة ممتصة، وK⁺(g) أيون بوتاسيوم موجب أحادي الشحنة في الحالة الغازية، وe⁻ الإلكترون المنزوع.', '["التعريف مع شرط الحالة الغازية","الطاقة لازمة (ممتصة)","معادلة صحيحة بالحالات","تفسير الرموز"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المعادلة","marks":1},{"element":"تفسير الرموز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق ومعادلة صحيحة مفسرة"},{"level":"2–3 درجات","description":"تعريف دون شرط الحالة الغازية أو معادلة دون حالات"},{"level":"1 درجة","description":"تعريف ناقص فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["إغفال الحالة الغازية","وضع الطاقة في نواتج المعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.350Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(619, null, null, null, '(أ) الأسهل Na لأن طاقة تأينه الأقل (496)، والأصعب Ne لأن طاقة تأينه الأعلى (2081). (ب) جذب نواة Na لإلكترونه الخارجي ضعيف، وجذب نواة Ne لإلكتروناته الخارجية قوي جدًا. (ج) لأن النيون غاز نبيل مستواه الخارجي ممتلئ (2s² 2p⁶) ومستقر، ونواته تجذب إلكتروناته بقوة، فيحتاج نزع إلكترون منه إلى طاقة كبيرة جدًا.', '["Na الأسهل","Ne الأصعب","ربط طاقة التأين بقوة الجذب","تفسير استقرار النيون"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التحديد","marks":2},{"element":"(ب) الاستنتاج","marks":1},{"element":"(ج) التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ أو نقص في جزء"},{"level":"1–2 درجة","description":"التحديد فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اعتبار الطاقة الأعلى دليلًا على سهولة نزع الإلكترون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.350Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(620, null, null, null, '(أ) علاقة طردية: كلما زادت قوة جذب النواة للإلكترون الخارجي زادت الطاقة اللازمة لنزعه أي زادت طاقة التأين. (ب) علاقة عكسية: كلما زادت طاقة التأين قل ميل الذرة إلى فقد الإلكترون وتكوين أيون موجب. مثال منخفض: الفلزات القلوية مثل Na أو K. مثال مرتفع: الغازات النبيلة مثل Ne أو Ar.', '["علاقة طردية مع قوة الجذب","علاقة عكسية مع الميل لتكوين أيون موجب","مثال صحيح منخفض","مثال صحيح مرتفع"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) العلاقة الأولى","marks":1},{"element":"(ب) العلاقة الثانية","marks":1},{"element":"المثالان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"العلاقتان صحيحتان مع مثالين صحيحين"},{"level":"2–3 درجات","description":"علاقة واحدة مع مثالين أو العلاقتان دون أمثلة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل العلاقة مع الميل لتكوين أيون موجب طردية","اختيار هالوجين مثالًا لطاقة تأين منخفضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.351Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(621, 1, 'في الدورة تزداد الشحنة النووية والإلكترونات تضاف إلى المستوى نفسه فلا يزداد الحجب تقريبًا، فيقوى جذب النواة لإلكترونات التكافؤ ويصعب نزعها.', '["عدد المستويات ثابت في الدورة الواحدة.","","نصف القطر يقل نحو اليمين في الدورة لا يزداد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-11T11:15:01.353Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(622, 2, 'صغر نصف القطر يعني قرب إلكترونات التكافؤ من النواة فيزداد جذبها، فتلزم طاقة أكبر لنزعها.', '["نصف القطر يقل في الدورة نحو اليمين لا يزداد.","قرب الإلكترون من النواة يجعل نزعه أصعب لا أسهل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:01.353Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(623, 0, 'F وBe في الدورة الثانية بمستويين وإلكترونين داخليين لكل منهما، لكن نواة F فيها 9 بروتونات مقابل 4، فيقوى جذبها ويصغر نصف القطر فيصعب نزع الإلكترون.', '["","لكليهما مستويان رئيسيان لأنهما في الدورة الثانية.","لكليهما إلكترونان داخليان فقط (1s²)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-11T11:15:01.353Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(624, 1, 'العدد الذري يزداد (11 → 18) فتزداد الشحنة النووية، والإلكترونات في المستوى الثالث نفسه، فيقوى جذبها وتزداد طاقة التأين من 496 إلى 1521 kJ/mol.', '["إلكترونات التكافؤ تقترب من النواة في الدورة لا تبتعد.","","الجدول يبين أن العدد الذري يزداد لا يقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:01.354Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(625, 2, 'طاقة التأين تزداد في الدورة؛ فزيادة الإلكترونات تصاحبها زيادة في عدد البروتونات، والإلكترونات تضاف إلى المستوى نفسه، فيقوى الجذب.', '["الإلكترونات في الدورة الواحدة تضاف إلى المستوى الرئيسي نفسه.","ثبات عدد المستويات لا يعني ثبات طاقة التأين لأن الشحنة النووية تتغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.354Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(626, 0, 'يقع النيون في آخر الدورة الثانية فشحنة نواته هي الأكبر فيها مع المستويين نفسيهما، ومستواه الخارجي ممتلئ مستقر، فنزع إلكترون منه هو الأصعب.', '["","لكل عناصر الدورة الثانية مستويان رئيسيان.","نصف القطر يقل نحو يمين الدورة، فليس النيون الأكبر حجمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-11T11:15:01.354Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
